# ЧИСТИМ перенесенням. Тут лишились два входи шва (`підготувати`, `перевірити_образ`)
# і реекспорт КОЖНОГО імені, що переїхало, — щоб `pipeline.ім'я` працювало для всіх
# викликачів як доти. Нові модулі один одного імпортують у порядку нижче (без кіл),
