# ── `_формат_відповіді` ЗНЕСЕНО (Т-02, 12.09.2026) ───────────────────────────
# Функція просила формат відповіді ПРОЗОЮ — «Останнім рядком дай «ОБРАЗ: id, id,
# …»» при одному образі й п'ять рядків із «ПІДПИС:/ОБРАЗ:/СВІДОМО:» при кількох, —
# а нижче в тому самому файлі стояв її ж перевизначений двійник, який при кількох
# образах просив JSON. Два контракти в одному промпті (Н-V33-061): який переможе,
# вирішувала свіжість рядка, не код. Аліас `_формат_відповіді_старий`, яким
# двійник тримав прозову гілку, знесено разом із ним.
# Форму відповіді тепер називає САМ ПАКЕТ: `завдання.відповідь = "ОБРАЗИ_V1"`, а
# схема цієї відповіді лежить у `протокол.py` — одне оголошення на обидва боки.
# Полюси задуму лишились (`ПОЛЮСИ_ОБРАЗУ` → `ПАКЕТ_V1.полюси`), рядки про
# різницю задумів і підпис — у `завдання.вимоги`.


def _питання_або_нуль(z):
    """Знахідка без виміру: регістр «питання» (дефолтний крій, невідома довжина,
    не виміряний баланс) або сила 0/None. Це запити на дані, не зауваження.

    Переїхала сюди з `bridge` (Т-03): тепер її читає `знахідки_вердикту`, а
    `bridge` імпортує `pipeline`, не навпаки — другої копії бути не може."""
    if z.get("сила") == "питання" or z.get("регістр") == "питання":
        return True
    # «тут не вирішує нічого / нема що сказати» — це відсутність знахідки, не знахідка
    # (K-SHO-07 давав такий рядок на 85 % образів у чотирьох сценаріях, 05.09)
    if _re_ід.search(r"не вирішує нічого|нема що сказати|не впливає тут|нічого не змінює",
                     str(z.get("суть") or ""), _re_ід.I):
        return True
    нп = z.get("сила_нп")
    try:
        return нп is None or float(нп) <= 0.0
    except (TypeError, ValueError):
        return True


# Ім'я ПОЛЯ в лапках («устілка_см», «довжина_стопи_мм») — підкреслення тут і є
# розрізнювачем: назва речі в лапках («Сумка жіноча Sack») його не має, а поле
# картки чи виміру людини без нього не пишеться ніде в корпусі.
_ПОЛЕ_У_ПИТАННІ = r"[«\"']([a-zа-яіїєґ0-9]+(?:_[a-zа-яіїєґ0-9]+)+)[»\"']"


def вага_питання(z):
    """Наскільки питання адресне: 3 — названо і річ, і поле; 2 — лише річ;
    1 — лише поле; 0 — загальне. Ключ сортування черги на вхід (більше — раніше).

    ЩО ЦЕ МІНЯЄ В РІШЕННІ (рядок 19 дошки, РВ-4 З-3). `bridge` ріже питання на
    12, а показ бере з них ПЕРШІ П'ЯТЬ — у діагноз екрана і в колонку
    `питання_коду` журналу. Порядок доти був порядком народження знахідок, і на
    образі з восьми речей до жінки доїжджали «площі не виміряні» та сім
    однакових «входу нема», а K-SHO-13 («вимір людини "довжина_стопи_мм", поле
    речі "устілка_см"») і K-HAT-01 не влазили навіть у дванадцять. Тобто з
    черги на вхід було видно рівно те, чого доміряти не може ніхто, і не видно
    того, що закривається одним полем картки.

    Обидва розрізнювачі — про АДРЕСУ, не про важливість:
    · названа річ — `речі` непорожні й це не службове «образ» (ним позначають
      себе записи `БЕЗ_ВХОДУ`: вони від речей не залежать за побудовою);
    · назване поле — у `суть` стоїть ім'я поля, а не назва речі.
    Сила тут не важить навмисно: у питань її нема — вони й є ті рядки, у яких
    вимір відсутній (`_питання_або_нуль`)."""
    речі = [str(r) for r in (z.get("речі") or []) if str(r or "").strip()]
    названа_річ = bool(речі) and речі != ["образ"]
    назване_поле = bool(_re_ід.search(_ПОЛЕ_У_ПИТАННІ, str(z.get("суть") or "")))
    return (2 if названа_річ else 0) + (1 if назване_поле else 0)


# ── СЛОТИ, ЯКИХ ВИМАГАЄ СТРУКТУРНИЙ БЛОКЕР (18.09.2026, доповнено 19.09.2026) ─
# Коди — ті самі, що дає `_код_блокера` зі слів `структура_образу`; слоти — ті
# самі, за якими та сама функція рахує «є». Одна таблиця на обидва боки: інакше
# блокер називав би слот, якого вітрина не знає, і ремонт лишався б без матеріалу.
# «неповний» несе обидва рядки повноти («потрібна ще одна річ» і «образ неповний:
# N речей»), і сімʼя в нього одна — те, що `структура_образу` рахує як _ТРЕТЯ.
# «нема_верху_низу» (рядок 46 дошки, власник 19.09) — ОСНОВА: без сукні чи
# комплекту, які закривають слот одним SKU, ремонту потрібні і «верх», і «низ»
# РАЗОМ — сама лише одна з половинок лишає образ означеним як «аксесуари, а не
# образ». Порядок сімʼї не випадковий: сукня/комплект пробуються ПЕРШИМИ (одна
# річ закриває обидва обов'язкові слоти одразу), верх і низ — запасний шлях, коли
# в пулі немає ні сукні, ні комплекту (`_дібрати_кодом` веде його окремо, бо жоден
# одинокий верх чи низ не закриває блокер сам по собі).
СЛОТИ_БЛОКЕРА = {
    "нема_сумки": ("сумка",),
    "нема_взуття": ("взуття",),
    "нема_верху_низу": ("сукня", "комплект", "верх", "низ"),
    "неповний": ("верхній_шар", "прикраси", "сережки", "кольє", "намисто", "браслет",
                 "каблучка", "брошка", "пояс", "шарф", "головний_убір"),
}
_ЧОМУ_БЛОКЕРА = {"нема_сумки": "нема сумки", "нема_взуття": "нема взуття",
                 "нема_верху_низу": "нема основи (сукні чи верху й низу)",
                 "неповний": "нема третьої речі"}


# ── СІМ'Я СЛОТУ — ОДНЕ МІСЦЕ, ЗВІДКИ ЧИТАЄ І СТРУКТУРА, І РЕМОНТ (рядок 47,
# 19.09.2026). Власник побачив дві пари сережок в ОДНОМУ образі: «Malachite» і
# «золотистого кольору Придане». Правило «по одній речі на слот» рахує буквальний
# слот, а сережки лежать у двох під-слотах — `feed._слот_у_тексті` ділить
# генеричну категорію «прикраси» на під-слоти (`feed.ПІД_СЛОТИ_ПРИКРАС`) ЗА
# НАЗВОЮ під час збору каталогу, і річ, чия назва не збіглася з жодним ключем
# того словника (діалектне слово продавця, річ руки 3/4 без проходу через
# feed), лишається генеричною «прикраси» — дубль для лічби невидимий.
# Ключі НЕ дублюються другим списком: та сама перевірка `feed.ПІД_СЛОТИ_ПРИКРАС`
# застосовується тут ще раз, над тим, що фактично прийшло в готовий образ.
_АЛІАС_СІМ_Ї = {"клатч": "сумка"}      # рука 3/4 без проходу через feed.слот()


def _сім_я_слота(слот, назва=None):
    """Сім'я слота для лічби «одна річ на сім'ю», а не буквальний слот пулу.

    «сумка»/«клатч» → одна сім'я; «прикраси», коли назва називає сережки,
    кольє, намисто, брошку, браслет чи каблучку, → та сім'я; решта — сама собою."""
    слот = str(слот or "")
    if слот in _АЛІАС_СІМ_Ї:
        return _АЛІАС_СІМ_Ї[слот]
    if слот == "прикраси":
        import feed as _Ф
        т = str(назва or "").lower()
        для = next((під for під, кл in _Ф.ПІД_СЛОТИ_ПРИКРАС if any(k in т for k in кл)), None)
        if для:
            return для
    return слот


# ── K-VAR-01 МІЖ КАРТКАМИ, А НЕ ЛИШЕ ВСЕРЕДИНІ РУКИ (рядок 48, 19.09.2026) ───
# `різноманітність()` нижче судить 10 варіантів ОДНІЄЇ руки — картки рук 1 і 2
# складаються в РІЗНИХ вердиктах, які одне одного не бачать за побудовою, тож
# «той самий клатч у двох картках одного прогону» K-VAR-01 не міг спіймати
# НІКОЛИ, скільки завгодно образів руки не давай. Виміряно `проби/сумка_руки.py`
# на каталог_повний (побачення·ресторан·19:00·20 °C, сіди 4242/17/101): пул
# сумок після відсічень — лише 22–23 моделі (взуття для порівняння — 29–37 із
# 1966), перетин пулів рук 1↔2 — 75–85 % усього слота. PR #92 дав руці 2
# ВЛАСНИЙ сід лише для розв'язання нічиєї (`bridge._сід_руки`) — це міняє
# ПОРЯДОК рівних, а не саму множину: коли реальний найкращий кандидат один на
# всю тонку множину, обидві моделі незалежно тягнуться до нього, хоч і бачать
# його в різному місці списку. Ліки тут не в порядку показу, а в тому, щоб
# повтор між картками СТАВ ВИДИМИЙ — той самий регістр, що для повтору
# всередині руки.
def повтор_прогону(реєстр, рука, речі):
    """Знахідка K-VAR-01, коли РІЧ цієї руки вже стояла в ІНШІЙ руці прогону.

    `реєстр` — {сім'я слота: [(рука, id, назва)]}, спільний на ВЕСЬ прогін (той
    самий сід): викликач (`bridge.від_моделі`) тримає його між викликами різних
    рук і передає сюди тим самим об'єктом — функція дописує в нього ЦЮ руку.
    Повертає ЩОНАЙБІЛЬШЕ одну знахідку (перший повтор), як і належить одному
    правилу на один рядок (Н-P37)."""
    import реєстр_правил as _РЕЄСТР
    знайдено = None
    for r in (речі or []):
        сім = _сім_я_слота(r.get("слот"), r.get("назва"))
        бачені = реєстр.setdefault(сім, [])
        інша_рука = next((р2 for р2, і2, _ in бачені if р2 != рука and і2 == r.get("id")), None)
        if інша_рука and знайдено is None:
            знайдено = (r, інша_рука)
        бачені.append((рука, r.get("id"), r.get("назва")))
    if not знайдено:
        return None
    r, інша_рука = знайдено
    return _РЕЄСТР._зн(
        "K-VAR-01", "soft",
        "«%s» уже стоїть у руці %s цього прогону — та сама річ, а не вибір"
        % (r.get("назва") or r.get("id"), інша_рука),
        [r.get("id")],
        "тема-4 XIII: набір існує, щоб було з чого обирати; та сама річ у двох "
        "картках одного прогону — це повтор, не вибір ші",
        ремонт="узяти в цій руці іншу річ тієї самої сім'ї слота",
    )


def _слоти_повноти(образи, кандидати):
    """{слот: [ід образів]} і {ід образу: [причини]} — чого бракує за блокерами.

    ЧОМУ ЦЕ ІСНУЄ (18.09.2026, спіймано власницею на опублікованому продукті).
    Вітрина бралась ЛИШЕ з вузлів напруги, а «нема сумки» вузлом не буває: слот
    порожній не має ребер, за якими напруга рахується. Тож ремонт другої ітерації
    фізично не міг полагодити те, через що вибір потім відмовляв, — у контексті
    моделі не було жодної сумки, а пулу першого пакета вона вже не бачить.
    Третя річ така сама: сімʼя слотів велика, а показували з неї нуль."""
    import реєстр_правил as _РЕЄСТР
    слоти, чому = {}, {}
    for і, о in enumerate(образи or [], 1):
        ід = str(о.get("номер") or о.get("ід") or ("о%d" % і))
        коди = []
        # ЗАПИС `bridge._запис` тримає блокери полем, вердикт (`ВЕРДИКТ_V1`) — у
        # «структура»: одна функція читає обидві форми, бо кличуть її з обох боків.
        for b in (о.get("блокери") or (о.get("структура") or {}).get("блокери") or []):
            к = str((b or {}).get("код") or "")
            if к in СЛОТИ_БЛОКЕРА and к not in коди:
                коди.append(к)
        for к in коди:
            чому.setdefault(ід, []).append(_ЧОМУ_БЛОКЕРА[к])
            _сім = [с for с in СЛОТИ_БЛОКЕРА[к] if (кандидати or {}).get(с)]
            # СІМʼЯ «ТРЕТЬОЇ РЕЧІ» ЗРІЗАЄТЬСЯ ДО НАЙБАГАТШИХ СЛОТІВ: потрібна ОДНА
            # річ, а слотів у сімʼї одинадцять — платити за всі означало б платити
            # за вибір, якого не просили.
            if len(_сім) > 1:
                _сім = sorted(_сім, key=lambda с: -len(кандидати[с]))[:_РЕЄСТР.C["слотів_третьої"]]
            for с in _сім:
                if ід not in слоти.setdefault(с, []):
                    слоти[с].append(ід)
    return слоти, чому


def _вітрина_ремонту(образи, кандидати, скільки_слотів=2, на_слот=12):
    """Речі, якими можна розвʼязати те, що тисне — саме в тих слотах, де тисне.
    → (`вітрина` за схемою `ВЕРДИКТ_V1.вітрина`: {слот: [річ]}, ноти для `завдання.вимоги`).

    ЧОМУ ЦЕ ІСНУЄ (31.08.2026). Промпт ремонту ніс лише ВЛАСНІ образи моделі:
    зміряно — 2 094 символи, 5 id, нуль кандидатів, нуль слотів. А кожен виклик іде
    свіжим контекстом без історії, тож на другій ітерації модель фізично не бачила
    жодної речі, крім тих, які сама вже обрала. Якщо ремонт вимагав ІНШОГО взуття,
    взуття не було звідки взяти — вона могла лише переставляти вже обране.
    Приймальня при цьому існувала: `ід_з_тексту` резолвить річ поза пулом із повного
    каталогу. Тобто приймальня була, вітрини не було.

    ЧОМУ НЕ ВЕСЬ ПУЛ. Повторити сотні речей у кожному виклику ремонту означало б
    платити за них удруге й утретє. Вітрина адресна: спершу слоти, яких вимагають
    СТРУКТУРНІ БЛОКЕРИ образів (нема сумки, нема взуття, нема третьої речі —
    `_слоти_повноти`), а вже потім ВУЗЛИ напруги — з того, що код зміряв на тому,
    що ші справді склала, а не з припущення. Речі, які модель уже взяла, виключаються: показувати їй те,
    що вона й так має, — не вибір.

    ОБʼЄКТОМ, А НЕ РЯДКАМИ (Т-03). Річ вітрини — той самий `_річ_пулу`, що будує
    пул першого пакета: один будівник речі на обидва виклики, інакше вітрина
    розійшлася б із пулом на першій же правці полів. Знайдене на «потрібно» моделі
    (`за_запитом`) стоїть у вітрині свого слота ЗАВЖДИ, а не лише коли слот —
    вузол: це відповідь на її запит, і без неї право на річ поза пулом порожнє.
    """
    if not образи or not кандидати:
        return {}, []
    import collections as _c, реєстр_правил as _РЕЄСТР
    вузли = _c.Counter(о.get("вузол") for о in образи if о.get("вузол") in кандидати)
    взяті = {i for о in образи for i in (о.get("ід") or [])}
    # НОМЕРИ — З ПОВНОГО ПУЛУ, як їх бачила модель у першій ітерації і як їх
    # читає `ід_з_тексту`. Підмножина, пронумерована сама по собі, — інша нумерація.
    _ном = номери_речей(кандидати)[0] if ПАКУВАТИ_ІНДЕКСОМ else {}
    вітрина, ноти = {}, []

    def _вільні(слот, скільки):
        """Речі слота, яких модель не брала, по одній на МОДЕЛЬ (`group_id`).
        Дедуп навмисно: вісім кольорів однієї сумки — це один вибір, повторений
        вісім разів, і за нього платить кожен виклик ремонту."""
        вих, моделі = [], set()
        for r in (кандидати.get(слот) or []):
            if r.get("id") in взяті or r.get("за_запитом"):
                continue
            м = r.get("group_id") or r.get("id")
            if м in моделі:
                continue
            моделі.add(м); вих.append(_річ_пулу(r, _ном))
            if len(вих) >= скільки:
                break
        return вих

    # ── СПЕРШУ ТЕ, ЧОГО ВИМАГАЄ БЛОКЕР, І ЛИШЕ ПОТІМ ВУЗОЛ НАПРУГИ (18.09.2026) ──
    # Порядок не косметичний: вузол напруги — це «тут вузько», а блокер структури —
    # «цього образу не покажуть узагалі». Друге сильніше за перше, і коли на слоти
    # бракує бюджету, платити треба за те, без чого картки не буде.
    _треба, _чому_образів = _слоти_повноти(образи, кандидати)
    for слот in _треба:
        речі = _вільні(слот, _РЕЄСТР.C["вітрина_блокера"])
        if речі:
            вітрина[слот] = речі
    if _чому_образів:
        # НОТА АДРЕСНА: до правки вітрина мовчала про те, ЧИЙ образ неповний, і
        # модель ремонтувала не те. Групуємо за причиною, щоб рядок лишався коротким.
        за_причиною = {}
        for ід, причини in _чому_образів.items():
            за_причиною.setdefault(" / ".join(причини), []).append(ід)
        ноти.append("ПОВНОТА ОБРАЗУ — це умова показу, не порада: %s. Слоти, яких "
                    "бракує, стоять у «вітрина» ПЕРШИМИ — доповни ці образи звідти, "
                    "інакше код їх не покаже жінці."
                    % "; ".join("%s — %s" % (", ".join(sorted(ід)), причина)
                                for причина, ід in sorted(за_причиною.items())))
    for слот, скільки in вузли.most_common(скільки_слотів):
        if слот in вітрина:
            continue
        речі = _вільні(слот, на_слот)
        if речі:
            вітрина[слот] = речі
    for слот, пул in кандидати.items():
        for r in пул:
            if r.get("за_запитом") and r.get("id") not in взяті:
                вітрина.setdefault(слот, []).append(
                    dict(_річ_пулу(r, _ном), за_запитом=str(r["за_запитом"])))
    if вітрина:
        ноти.append("«вітрина» — речі, яких ти ще не брала: спершу слоти, яких твоїм образам "
                    "БРАКУЄ для повноти, потім ті, де сходиться найбільше умов, і те, що код "
                    "знайшов на твоє «потрібно» (поле «за_запитом»). Слот повноти взяти треба; "
                    "решта — не наказ міняти саме там.")
    # ── ДЕ МОЖНА ЛАМАТИ — З РЕАЛЬНИХ ОБРАЗІВ, А НЕ З ВИГАДАНИХ ─────────────
    # Слот розриву доти обирався в композиторі за 200 ВИГАДАНИХ комбінацій із
    # топ-5 на слот: образів, яких ніхто не збирав і не збиратиме. Після першої
    # ітерації на руках десять СПРАВЖНІХ образів, кожен уже проведений крізь граф
    # із вузлом напруги. Міряти по них і дешевше, і чесніше — той самий принцип,
    # яким прибрано власний образ коду: код судить складене, не вигадане.
    # МЕЖА ЛИШАЄТЬСЯ ТА САМА, що стерегла композитор: ламати можна лише далеко від
    # обличчя. Верх, сукня й верхній шар не пропонуються ніколи — там колір біля
    # обличчя вирішує (K-CLR-02), і розрив коштував би головного правила системи.
    _далеко = [(с, n) for с, n in вузли.most_common()
               if с not in ("верх", "сукня", "комплект", "верхній_шар")]
    if _далеко:
        _с, _n = _далеко[0]
        ноти.append("Де можна ламати палітру: слот «%s» — вузол у %d з %d твоїх образів, і він "
                    "далеко від обличчя, тож колірні правила біля обличчя тут не діють. Річ поза "
                    "палітрою туди — лише з записом у «свідомо»: оголошений розрив судиться "
                    "мʼякше, неоголошений — як помилка." % (_с, _n, len(образи)))
    return вітрина, ноти


def образ_рядком(о, кандидати=None, ном=None):
    """«взуття: #12·33 Босоніжки… · низ: #45·10 Штани…» — образ зі СЛОТАМИ.

    ЧОМУ (02.09.2026, прогін 21:24: три образи поспіль із двома взуттями).
    Доти образ друкувався голими id: «ж-04756@miraton.ua, ж-00132@gepur.com».
    Модель не бачила, який id — взуття, тож коли вітрина ремонту пропонувала
    інше взуття, вона ДОДАВАЛА його, а не заміняла: замінити означало б
    вгадати, який із голих id прибрати. А до правки нумерації вітрини 02.09
    додане взуття не резолвилось узагалі й випадало мовчки — тому «раніше
    такого не було»: помилка була, її не було видно.
    Тепер кожна річ образу підписана слотом і номером із того самого пулу,
    що бачить модель, — замінити взуття означає замінити рядок «взуття: …»."""
    частини = []
    за_ід = {}
    for сл, пул in (кандидати or {}).items():
        for r in пул:
            if r.get("id"): за_ід.setdefault(r["id"], (сл, r.get("назва") or ""))
    for і in (о.get("ід") or []):
        сл, назва = за_ід.get(і, ("?", ""))
        мітка = ("#%d·%s" % ном[і]) if ном and і in ном else str(і)
        частини.append(("%s: %s %s" % (сл, мітка, назва[:40])).rstrip())
    return " · ".join(частини) if частини else ", ".join(str(x) for x in (о.get("ід") or []))


# ── `промпт_ремонту` ЗНЕСЕНО (Т-03, 12.09.2026) ─────────────────────────────
# Другий виклик до моделі говорив прозою: «· суть [0.50]», «БЛОКУЄ: …», «СТЕЛЯ
# НАДЛИШКУ…», «МОВА — це ТВІЙ текст…», вітрина рядками пулу. По дорозі туди
# гинули `регістр` і `ремонт` (`bridge._стислі_знахідки` лишав пʼять полів), а
# знахідки з одним `правило` йшли окремими рядками — три «тип … не належить до
# коду» на три речі (Н-P37). Тепер вердикт — один обʼєкт за схемою
# `протокол.ВЕРДИКТ_V1` (`вердикт_v1`), і промпт — той самий обʼєкт: модель
# читає ті самі поля, які код потім звірить у `перевірити_виконання` (Т-05).
# Інструкції моделі, які стояли абзацом у кінці промпта, — тепер `ВИМОГИ_ВЕРДИКТУ`.

# ВИМОГИ ДО МОДЕЛІ — СПИСОК КОРОТКИХ РЯДКІВ, те саме рішення, що `ВИМОГИ_ПАКЕТА`
# (Т-02): інструкція лишається текстом, але не прозою, у якій тонуть дані. Кожен
# рядок стоїть проти названого провалу першої ітерації; жоден не описує ФОРМАТ
# відповіді — форму називає `завдання.відповідь` і скелет зі схеми.
ВИМОГИ_ВЕРДИКТУ = (
    "Це вердикт коду над ТВОЇМИ образами: у кожного — «структура», «знахідки», "
    "«чекліст» і «вузол». Це матеріал для роботи, а не оцінка образу.",
    # БЛОКУЄ — мусить зникнути. Доти це був рядок «БЛОКУЄ:» без адреси в обʼєкті.
    "«структура.блокери» і знахідки з регістром «гейт» мусять зникнути: або зміни "
    "річ, або зніми образ із розгляду.",
    # ВИКОНАНО — те, за чим Т-05 перевірить ремонт фактом. Без `ід` знахідки
    # запису не було до чого привʼязати.
    "На кожну знахідку з регістром «гейт» — запис у «виконано» свого образу: "
    "«знахідка» = її «ід», «дія» — виправлено|відхилено|частково, і «чому».",
    # СВІДОМИЙ ХІД ПОКАЗУЄТЬСЯ ЯК ХІД. Без цього друга ітерація «лагодила» те, що
    # сама пояснила в першій, — механізм працював навпаки до задуму.
    "Знахідка зі «свідомий: true» — твій оголошений хід з попередньої ітерації; код "
    "його вже послабив. Не «виправляй» його: або лиши й повтори у «свідомо», або "
    "передумай — і тоді скажи, чому.",
    # R-ABC-08: число описує ребро, не образ. Інакше модель сортує за лічбою.
    "«сила_нп» описує окрему знахідку, не образ. Менше знахідок не означає кращий образ.",
    "Обери ті образи, які ТИ можеш зробити кращими, якщо попрацюєш глибше, — не ті, "
    "до яких менше питань.",
    # K-SYS-08 / K-SYS-09: дві межі. «без_входу» — третій стан, не «пройдено».
    "Дві межі рівносильні: «чекліст.надлишок» — що вже забагато, «чекліст.прісність» "
    "— чого бракує. Образ без ЖОДНОГО джерела інтересу — не «спокійний», а порожній, "
    "і це провал такий самий, як перебір. «без_входу» — пункт не перевірений, це не "
    "«пройдено».",
    "По одній речі на слот: замінюй, а не додавай — два взуття чи дві сумки код "
    "відкине. Образ мусить мати сукню, комплект або верх і низ.",
    # K-VAR-01: РІЗНІ ОБРАЗИ — ЦЕ Й РІЗНЕ ВЗУТТЯ. Рядок стоїть проти виміряного
    # провалу (18.09.2026): десять образів на ОДНІЙ парі проходили як «усі різні»,
    # бо спільна річ одна з дев'яти, а Jaccard міряє склад цілком. Тепер це
    # знахідка K-VAR-01 («слот … — одна річ … на N образів із M»), і вимога до
    # моделі стоїть поруч із нею, а не лишається здогадом.
    "Різні образи — це й різне ВЗУТТЯ та сумка, не лише різні верх і низ. Одна пара "
    "більш ніж на половину набору — це слот, який ти не вибирала, і код називає це "
    "знахідкою K-VAR-01: бери в такому слоті інші речі з пулу.",
    "Бери речі лише з пулу першого пакета або з «вітрина»; називай кожну полем «н» "
    "цілком («#412·29»). Половина комплекту — «#412·29/верх» або «#412·29/низ».",
    "Свідомо береш річ поза списком або ламаєш умову — назви це в полі «свідомо» "
    "свого образу (річ і чому).",
    "«потрібно» — лише коли для доброго образу справді бракує речі, якої нема ні в "
    "пулі, ні у «вітрина»: код знайде її в каталозі й покаже наступного разу.",
    "Дай стільки допрацьованих образів, скільки каже «завдання.образів». Відповідь — "
    "ЛИШЕ один JSON-обʼєкт за «завдання.схема_відповіді», без пояснень і без ```.",
)
# Ставиться лише коли мовний гейт справді щось знайшов: інструкція без предмета —
# шум у запиті (те саме правило, що для комплекту в `пакет_для_моделі`).
_ВИМОГА_МОВИ = ("«мова» — вирок над ТВОЇМ текстом, не над образом: кожне порушення мусить "
                "зникнути з наступної відповіді; «натомість» каже, чим замінити.")


def _код_блокера(рядок):
    """Код структурного блокера зі слів `структура_образу`, або None для не-структурного.

    Слова — ті самі, за якими показ вирізняє структурні рядки з `блокує`
    (показ.html: «по одній на слот|аксесуари, а не образ|подвоєн|з однієї речі»):
    вони вже були контрактом, тут він названий одним місцем. Рядки гейтів коду не
    мають навмисно: гейт — знахідка з регістром «гейт», і живе у `знахідки`."""
    т = str(рядок or "")
    if "по одній на слот" in т or "подвоєн" in т:
        return "слот_двічі"
    if "аксесуари, а не образ" in т:
        return "нема_верху_низу"
    if "з однієї речі" in т:
        return "одна_річ"
    if "нема взуття" in т:
        return "нема_взуття"
    if "нема сумки" in т:
        return "нема_сумки"
    if "потрібна ще одна річ" in т or "образ неповний" in т:
        return "неповний"
    return None


def _у_лапках(т):
    """Усі «…» з рядка по порядку — слоти, які `структура_образу` називає в лапках."""
    out, i = [], 0
    while True:
        a = т.find("«", i)
        b = т.find("»", a + 1) if a >= 0 else -1
        if b < 0:
            return out
        out.append(т[a + 1:b])
        i = b + 1


def номер_речі(ід, ном=None, частина=None):
    """«#N·MM» з нумерації пулу (той самий номер, що бачила модель); річ поза пулом —
    своїм id, як в `образ_рядком`. Половина комплекту — «#N·MM/низ»."""
    н = (ном or {}).get(ід)
    т = ("#%d·%s" % н) if н else str(ід or "")
    return т + ("/%s" % частина if частина else "")


def блокери_структури(рядки, речі=None, ном=None):
    """Структурні рядки `блокує` → `[{код, речі, суть}]` за `ВЕРДИКТ_V1.структура.блокери`.

    `речі` — речі образу з `перевірити_від_моделі` ({id, слот, назва}); для
    «слот_двічі» адресою стають речі названого слота, для решти адреси нема — образ
    цілий. Вето людини (K-PC-08) сюди кладе `знахідки_вердикту`, бо його речі лежать
    у знахідці, не в рядку."""
    вих = []
    for р in (рядки or []):
        т = str(р or "")
        код = _код_блокера(т)
        if not код:
            continue
        адреси = []
        if код == "слот_двічі":
            слоти = set(_у_лапках(т))
            # ІМЕНА В ЛАПКАХ — ТЕПЕР МОЖУТЬ БУТИ СІМ'ЄЮ (рядок 47): дві пари
            # сережок у різних буквальних слотах адресуються обидві, не лише та,
            # чий літеральний слот збігся з іменем у рядку.
            адреси = [номер_речі(r.get("id"), ном, r.get("частина_комплекту"))
                      for r in (речі or [])
                      if r.get("слот") in слоти
                      or _сім_я_слота(r.get("слот"), r.get("назва")) in слоти]
        вих.append(dict(код=код, речі=адреси, суть=т))
    return вих


def _ремонт_рядком(z):
    """`ремонт` знахідки одним рядком: у `_зн` він рядок або список, у рядках
    `для_стиліста` — список `ремонти`. Схема тримає один рядок, бо модель читає
    його як пораду, а не як меню."""
    р = z.get("ремонт")
    if р in (None, "", [], ()):
        р = z.get("ремонти")
    if р in (None, "", [], ()):
        # `що_зняло_б` — ТЕЖ РЕМОНТ, і доти він до моделі не доїжджав (17.09.2026).
        # Три емітенти цього модуля пишуть саме це поле: `схема_образу` (K-PAL-03),
        # `акцент_образу` (K-PAL-18) і `палітра_образу` (K-PAL-04…15). Виміряно на
        # вердикті стенда: рядок K-PAL-14 виходив із `ремонт: null`, хоч знахідка
        # несла «той самий колір у слоті далі від обличчя». Гейт, який називає
        # межу й мовчить про вихід, — половина правила.
        р = z.get("що_зняло_б")
    if isinstance(р, str):
        return р.strip() or None
    if isinstance(р, (list, tuple)):
        ч = [str(x).strip() for x in р if str(x or "").strip()]
        if not ч:
            return None
        # `_мʼякший_ремонт` ставить першим рядком заголовок «як варіанти:»
        if ч[0].endswith(":") and len(ч) > 1:
            return ч[0] + " " + "; ".join(ч[1:])
        return "; ".join(ч)
    return None


def знахідки_вердикту(знахідки, образ, ном=None):
    """Знахідки одного образу → рядки `ЗНАХІДКА_ВЕРДИКТУ` і вето-блокери: (рядки, вето).

    ТРИ РЕЧІ ПО ДОРОЗІ, У ЦЬОМУ ПОРЯДКУ:
    1. `реєстр_правил.обмежити_вагу` — стеля категорії й підлога (V10: доти на шляху до
       моделі її не було; рядки `_доповнення_судді` виходили силою понад стелю).
       На копіях: сирі знахідки лишаються в `в["знахідки"]` журналу як були.
    2. Відсів того, що не є зауваженням (`_питання_або_нуль`); K-PC-08 (вето
       людини) виймається у блокер `вето` — це не знахідка з ремонтом, а межа.
    3. ОДНЕ ПРАВИЛО — ОДИН РЯДОК (Н-P37): знахідки з тим самим `правило` зливаються
       в одну з НАЙБІЛЬШОЮ силою і обʼєднанням речей. Представник — найсильніша:
       її суть, ремонт, регістр і `свідомий`; злиті речі дописуються, лічба злиття
       названа в суті, щоб одна суть над трьома речами не читалась як помилка.
    `ід` = «з-<образ>-<n>» після сортування за силою — стабільний у межах вердикту;
    на нього модель посилається у «виконано», код — у `перевірити_виконання`."""
    import outfit as _O
    import колір_образу as _КОЛІР, реєстр_правил as _РЕЄСТР, формальність as _ФОРМ   # Н-02-01, сесія 4
    рядки = [dict(z) for z in (знахідки or []) if isinstance(z, dict) and z.get("правило")]
    рядки = [z for z in _РЕЄСТР.обмежити_вагу(рядки) if not z.pop("під_підлогою", False)]
    вето = [dict(код="вето", речі=[номер_речі(r, ном) for r in (z.get("речі") or []) if r not in (None, "")],
                 суть="вето людини: %s" % str(z.get("суть") or "")[:80])
            for z in рядки if z.get("правило") == "K-PC-08"]
    рядки = [z for z in рядки if z.get("правило") != "K-PC-08" and not _питання_або_нуль(z)]
    злиті, порядок = {}, []
    for z in рядки:
        п = str(z["правило"])
        речі = [str(r) for r in (z.get("речі") or []) if r not in (None, "")]
        if п not in злиті:
            злиті[п] = dict(z, речі=речі, злито=1)
            порядок.append(п)
            continue
        м = злиті[п]
        якщо_сильніша = float(z.get("сила_нп") or 0) > float(м.get("сила_нп") or 0)
        усі_речі = (речі + [r for r in м["речі"] if r not in речі]) if якщо_сильніша \
            else (м["речі"] + [r for r in речі if r not in м["речі"]])
        злиті[п] = dict(z if якщо_сильніша else м, речі=усі_речі, злито=м["злито"] + 1)
    вих = sorted((злиті[п] for п in порядок), key=lambda z: -float(z.get("сила_нп") or 0))
    рядки_схеми = []
    for n, z in enumerate(вих, 1):
        # Слово регістру не вирішується тут (Н-02-05): знахідка правила несе його
        # від `реєстр_правил.регістр`, а рядок без правила в корпусі
        # (`_доповнення_судді`) дістає його від `протокол.регістр_знахідки` — за
        # `блокує`, рівно так, як їх читав старий промпт.
        рег = _ПР.регістр_знахідки(z)
        суть = str(z.get("суть") or "")
        if z.get("злито", 1) > 1:
            суть += " (+%d за цим самим правилом; речі обʼєднано)" % (z["злито"] - 1)
        рядки_схеми.append(dict(
            ід="з-%s-%d" % (образ, n), правило=str(z["правило"]),
            сила=z.get("сила"), сила_нп=round(float(z.get("сила_нп") or 0), 2),
            регістр=рег, суть=суть, ремонт=_ремонт_рядком(z),
            речі=[номер_речі(r, ном) for r in z["речі"]],
            свідомий=bool(z.get("свідомий")),
            # ДРУГИЙ КОД ДОЇЖДЖАЄ НА ДРІТ (17.09.2026). Правило, чий вимір
            # збігається з чужим, окремого рядка не дістає — але й зникати не
            # має: ×0.6 K-KOH-03 на K-KOH-02 і ×0.6 K-SIL-07 на K-COL-01 міняють
            # силу, яку ші бачить. Без цього поля ші бачить наслідок і не бачить
            # причини, а зведення чесно рахує обидва правила «лише слідом».
            **({"також_правила": [str(x) for x in z["також_правила"]]}
               if z.get("також_правила") else {})))
    return рядки_схеми, вето


def чекліст_вердикту(чеклісти):
    """`суд_образу.чеклісти` (пункти зі станом) → `ВЕРДИКТ_V1.чекліст`: провалені пункти
    словами, решта — лічбою. Тристановість зберігається: «без входу» ≠ «пройдено»."""
    if not isinstance(чеклісти, dict):
        return None
    вих = {}
    # ТРЕТІЙ БІК — ПАЛІТРА (K-PAL, 17.09.2026). Додано сюди, а не окремим полем:
    # форма пункта та сама (провал словами, решта лічбою), і тристановість тут
    # важить найбільше — саме в цьому списку «без входу» є нормальним станом
    # (сивини нема, бік температури утримано), а не дефектом.
    for бік in ("надлишок", "прісність", "палітра", "аксесуари"):
        пункти = [p for p in (чеклісти.get(бік) or []) if isinstance(p, dict)]
        if not пункти:
            continue
        вих[бік] = dict(провал=[str(p.get("що") or p.get("пункт") or "")
                                for p in пункти if p.get("стан") == "провал"],
                        пройдено=sum(1 for p in пункти if p.get("стан") == "пройдено"),
                        без_входу=sum(1 for p in пункти if p.get("стан") == "без входу"))
        # ── ПРОВАЛЕНИЙ ПУНКТ НАЗИВАЄ СВОЇ ПРАВИЛА (друге проходження гейта) ───
        # ЩО ЦЕ МІНЯЄ (правило 3, before/after). Пункт чекліста НЕСЕ
        # `правила=[...]` — це його половина змісту: «бюджет хроми» без K-COL-02
        # не приписується нічому. Тут ID відкидались усі: у вердикт ішов лише
        # рядок `що`. Отже правило, чий єдиний вихід — рядок чекліста, у виході
        # себе не називало, і гейт досяжності чесно рахував його без сліду.
        вих[бік]["правила"] = sorted({r for p in пункти for r in (p.get("правила") or ())})

        # ── ЩО САМЕ ВИМКНЕНО, А НЕ ЛИШЕ СКІЛЬКИ (17.09.2026) ─────────────────
        # Лічба «без входу: 4» каже, що черга є, і не каже, з чого вона. Для
        # трьох перших боків цього досі вистачало (там «без входу» нормальний
        # стан — сивини нема, принту нема), для аксесуарного не вистачає: там
        # у черзі стоять ПРАВИЛА КОРПУСУ, і вимкнене правило без назви поля —
        # це та сама тиша, яку весь цей шар і ловить.
        # ── `вхід` — ТЕЖ НАЗВА ТОГО, ЧОГО БРАКУЄ (друге проходження гейта) ────
        # Умова була `and p.get("бракує")`, а поле `бракує` ставить РІВНО ОДИН із
        # чотирьох боків (`пункт_аксесуара`). Отже для надлишку, прісності й
        # палітри `вимкнено` не будувалось ніколи, і в них «без входу» лишалось
        # чистою лічбою — без назви поля й без ID правила. А `вхід` у кожного
        # пункта є за побудовою (це ключ, за яким `_вхід_є` і вирішує стан), і
        # він і є назва того, чого бракує: «ахроматичне волосся», «≥2 принти»,
        # «довжина виробу в см». Тому `бракує` лишається докладнішою назвою там,
        # де вона зміряна, а `вхід` — назвою за замовчуванням, і жоден вимкнений
        # пункт більше не виходить безіменним.
        _бракує = [dict(що=str(p.get("що") or ""),
                        бракує=str(p.get("бракує") or p.get("вхід") or ""),
                        правила=list(p.get("правила") or ()))
                   for p in пункти if p.get("стан") == "без входу"
                   and (p.get("бракує") or p.get("вхід"))]
        if _бракує:
            вих[бік]["вимкнено"] = _бракує
    return вих or None


def _реєстр_вердикту(реєстри):
    """`перевірити_образ["реєстри"]` → `{провідний, поруч}` назвами реєстрів (тема-13)."""
    if not isinstance(реєстри, dict):
        return None
    import реєстри as _РЕ
    назва = lambda k: (_РЕ.РЕЄСТРИ.get(k) or {}).get("назва") or str(k)
    дом = реєстри.get("домінанта")
    поруч = [назва(k) for k in (реєстри.get("цитати") or []) if k][:3]
    if not дом and not поруч:
        return None
    return dict(провідний=(назва(дом) if дом else None), поруч=поруч)


def _мова_вердикту(мова):
    """`language_gate.перевірити` → `ВЕРДИКТ_V1.мова`: вирок і порушення з тим, чим
    замінити. Помилка гейта чи його відсутність — поля нема, а не «можна»."""
    if not isinstance(мова, dict) or "можна_видавати" not in мова:
        return None
    пор = []
    for п in (мова.get("порушення") or []):
        if not isinstance(п, dict) or not п.get("правило"):
            continue
        з = dict(правило=str(п["правило"]), суть=str(п.get("суть") or п["правило"]))
        зб = [str(x) for x in (п.get("збіги") or []) if x][:2]
        if зб:
            з["суть"] += " — «%s»" % "», «".join(зб)
        н = п.get("дозволено_натомість") or п.get("дозволено")
        if н:
            з["натомість"] = str(н)
        пор.append(з)
    return dict(можна_видавати=bool(мова["можна_видавати"]), порушення=пор)


# ── МОВНИЙ ВИРОК ЗАМИКАЄ ПЕТЛЮ (Т-07) ────────────────────────────────────────
# ЩО ЦЕ МІНЯЄ В РІШЕННІ. Гейт судить текст опису з 02.09, і вирок їде полем
# `мова` — але реагував на нього ОДИН ярус: показ фільтрував `R-LNG-UA` (російське)
# і переписував текст промптом, зшитим у JS. Решта одинадцяти анти-правил
# («сховати ваду», «дасть впевненість», «твій сезон — Winter», «вам краще L»)
# лишала слід у вердикті й доходила до жінки як є — при `можна_видавати=False`.
# Тобто правило сили `hard` було звітом, а не гейтом, а модуль при цьому в
# докстрінгу стверджував, що текст «не видається, поки модель не перепише».
# ЩО ТУТ. Вирок будує ПОВТОРНИЙ ВИКЛИК тим самим каналом, яким його будує невалідна
# відповідь (`протокол.помилка_формату`): обʼєкт із `порушення` і `натомість`, який
# показ лише віддає моделі. Формулювання анти-правил лишається в ОДНОМУ місці
# (`language_gate.АНТИ.дозволено`) — рівно та вада, через яку промпт ремонту свого
# часу переїхав із JS у Python.
# ЧОМУ ТЕКСТ НЕ ВКЛАДАЄТЬСЯ ТУТ. Переписувати треба ВІДПОВІДЬ моделі (обʼєкт
# `ОПИС_ВІДПОВІДЬ_V1`), а сюди доїжджає лише проза, яку з неї вийняв
# `опис_відповідь_з_json` (у гейт іде те, що читає жінка). Промпт, у який код
# вклав би прозу, просив би прозою й відповісти — і схема на повторі розсипалась
# би. Тому попередню відповідь доклеює той, у кого вона є (показ), — так само, як
# на повторі через формат опису.
# ЧОМУ ДВІ СПРОБИ. Одна — половина петлі: «переписала чисто» і «переписала гірше»
# кінчались однаково. Нескінченність коштує виклику на кожній із чотирьох рук
# (`ОДНОЧАСНО_П`, розведення стартів на 1.5 с), а гейт ловить ФОРМУЛЮВАННЯ:
# текст, що не очистився двічі, третім разом очиститься випадково, не через
# розуміння. Число живе тут, і показ читає його з обʼєкта (`спроб_усього`), щоб
# межа циклу не стояла двома літералами в двох мовах.
МОВНИХ_СПРОБ = 2

_НАКАЗ_МОВИ = ("Перепиши ЦЕЙ САМИЙ текст: ті самі речі, ті самі поради, той самий "
               "порядок. Міняється лише те, що назване в «порушення».")
# Ярус української (Т-07 крок 4): наказ про мову ВСЬОГО тексту, не про формулу.
_НАКАЗ_УКРАЇНСЬКОЇ = ("Жодного російського слова, закінчення чи літери: увесь текст "
                      "українською.")

# ── Р-2: ЩО РОБИТИ ПІСЛЯ ОСТАННЬОЇ СПРОБИ (РІШЕННЯ ВЛАСНИКА, 12.09.2026) ─────
# ЯРУСАМИ, БО ЯРУСИ РІЗНІ ЗА НАДІЙНІСТЮ ВИРОКУ — це і є зміст рішення:
#   · РОСІЙСЬКА (`R-LNG-UA`) — детектор дивиться на літери, закінчення й слова, і
#     помиляється рідко. Текст, який не очистився за дві спроби, тут означає рівно
#     те, що написано: російська доїхала до жінки. ТЕКСТ НЕ ПОКАЗУЄТЬСЯ.
#   · ФОРМУЛИ (решта анти-правил) — регекси-гіпотези над українською прозою
#     (`language_gate` про це й пише: «кожен тригер може давати хибні
#     спрацювання», роздільна здатність на живому виході не виміряна). Якщо модель
#     двічі не змогла переписати те, на що їй прямо показали, найімовірніша
#     причина — гейт неправий, а не вперта модель. Викидати справний опис через
#     баг регекса дорожче, ніж показати його з позначкою. ПОКАЗАТИ З ПОЗНАЧКОЮ.
# ЧОМУ НЕ «НЕ ПОКАЗУВАТИ РУКУ» (другий варіант §5). Разом із карткою зникає й рядок
# журналу вердиктів — він пишеться з картки, — тобто рука випадає з проби 2×2 і з
# замірів. Ховається ТЕКСТ, а не рука: речі, ціни й вердикт жінки лишаються.
# СИРИЙ ВИХІД МОДЕЛІ ПРИ ЦЬОМУ НЕ ГИНЕ: у журнал він іде як був (колонка `текст`) —
# це той самий принцип, що вже стоїть у показі: «показ чистимо, не дані».
Р2_ПОКАЗАТИ_З_ПОЗНАЧКОЮ = "показати з позначкою"
Р2_НЕ_ПОКАЗУВАТИ_ТЕКСТ = "не показувати текст"
Р2 = Р2_ПОКАЗАТИ_З_ПОЗНАЧКОЮ            # ярус формул
Р2_УКРАЇНСЬКА = Р2_НЕ_ПОКАЗУВАТИ_ТЕКСТ  # ярус R-LNG-UA


def _мова_порушення(мова):
    """Порушення вироку у вигляді, який читає модель: `суть`, перші два `збіги`,
    `натомість`. Порожньо — або гейт дозволив, або порушення без ід (збій гейта,
    а не брудний текст): у другому випадку просити перепис нема про що."""
    пор, натомість = [], []
    for п in ((мова or {}).get("порушення") or []):
        if not isinstance(п, dict) or not п.get("правило"):
            continue
        з = dict(правило=str(п["правило"]), суть=str(п.get("суть") or п["правило"]),
                 збіги=[str(x) for x in (п.get("збіги") or []) if x][:2])
        н = п.get("дозволено_натомість") or п.get("дозволено")
        if н:
            з["натомість"] = str(н)
            if str(н) not in натомість:
                натомість.append(str(н))
        пор.append(з)
    return пор, натомість


def мова_повтор(мова, спроба=1, відповідь="ОПИС_ВІДПОВІДЬ_V1"):
    """Вирок гейта → обʼєкт повторного виклику, або None, коли просити нема про що.

    `None` у трьох випадках, і всі три означають «цикл мови тут кінчається»: гейта
    не було (`мова` не вирок), гейт дозволив видачу, спроби вичерпані
    (`спроба > МОВНИХ_СПРОБ` — далі говорить `мова_рішення`, Р-2). `спроба` — номер
    тексту в циклі: 1 — те, що модель написала сама, 2 — після першого перепису.

    КОДИ ПРАВИЛ лишаються в обʼєкті: назовні до моделі його проводить
    `bridge._вердикт_для_моделі`, який знімає `правило` (§1(г), до рішення Р-1) —
    той самий шлях, що у вердикта. Читачеві коди потрібні: ними журнал називає, що
    саме вціліло."""
    import language_gate as _МГ
    if not isinstance(мова, dict) or мова.get("можна_видавати") is not False:
        return None
    try:
        с = max(1, int(спроба or 1))
    except (TypeError, ValueError):
        с = 1
    if с > МОВНИХ_СПРОБ:
        return None
    пор, натомість = _мова_порушення(мова)
    if not пор:
        return None
    укр = any(п["правило"] == _МГ.ЯРУС_УКРАЇНСЬКОЇ for п in пор)
    сх = str(відповідь or "ОПИС_ВІДПОВІДЬ_V1")
    наказ = _НАКАЗ_МОВИ + ((" " + _НАКАЗ_УКРАЇНСЬКОЇ) if укр else "")
    об = dict(версія=_ПР.ВЕРСІЯ, помилка="мова", спроба=с, спроб_усього=МОВНИХ_СПРОБ,
              наказ=наказ, порушення=пор, натомість=натомість, українська=укр,
              відповідь=сх,
              формат="Віддай ТОЙ САМИЙ обʼєкт за схемою «%s» — міняється лише "
                     "формулювання." % сх)
    # ── ПЕРЕПИС ФОТО НЕ БАЧИТЬ, І ЦЕ СКАЗАНО ВГОЛОС (рядок 44 дошки) ─────────
    # Перепис мови йде БЕЗ знімків (`показ.html`: «двадцять знімків удруге
    # коштують рівно стільки ж»), а «віддай ТОЙ САМИЙ обʼєкт» разом зі схемою
    # `ОПИС_ВІДПОВІДЬ_V1` просить заповнити й `фото_не_те` — тобто свідчення про
    # те, чого моделі не показали. Звідси позначка «фото крамниці може не
    # відповідати назві» на речах, чиє фото збігається. Межу тримає код
    # (`показ.html` бере свідчення з виклику, у якому фото були), а цей рядок
    # знімає з моделі саме прохання вигадати: мовчання тут було б проханням.
    if сх == "ОПИС_ВІДПОВІДЬ_V1":
        об["фото"] = ("Знімків у цьому виклику НЕМА — міняється лише мова тексту. "
                      "Поле «фото_не_те» лиши ПОРОЖНІМ: що на фото не те, вже записано "
                      "з попередньої відповіді, і звідти воно й береться.")
    return об


def мова_рішення(мова, спроб=0):
    """Р-2 над ЦИМ текстом: що робити, якщо він фінальний і гейт його не пустив.

    `None`, коли гейт дозволив видачу. Інакше — рішення полем: `показувати_текст`
    (чи показувати жінці опис; речі й вердикт на картці лишаються завжди),
    `позначка` (рядок для діагнозу й журналу), `правила` (що саме вціліло),
    `українська` (чи серед них ярус R-LNG-UA), `спроб` (скільки переписів
    витрачено). Рішення не приймається тут щоразу — воно стоїть константами `Р2` і
    `Р2_УКРАЇНСЬКА`; функція лише називає, котре з них діє на цьому вироку, щоб
    показ не вирішував за власника."""
    import language_gate as _МГ
    if not isinstance(мова, dict) or мова.get("можна_видавати") is not False:
        return None
    пор, _н = _мова_порушення(мова)
    if not пор:
        return None
    правила = [п["правило"] for п in пор]
    укр = _МГ.ЯРУС_УКРАЇНСЬКОЇ in правила
    try:
        с = max(0, int(спроб or 0))
    except (TypeError, ValueError):
        с = 0
    # ПОЗНАЧКА КАЖЕ Й ПРО НУЛЬ СПРОБ: цей самий вирок читають споживачі, які
    # переписів не роблять узагалі (гейти, стенд, руки без каталогу), і «не
    # очистилась за 0 переписів» було б звинуваченням моделі за те, чого в неї
    # не просили.
    позначка = ("гейт заблокував текст: %s" % ", ".join(правила) if not с else
                "мова не очистилась за %d перепис%s: %s"
                % (с, ("" if с == 1 else "и" if с < 5 else "ів"), ", ".join(правила)))
    # ЯРУС РІШУЧІШИЙ ЗА КІЛЬКІСТЬ: одна вціліла російська важить більше, ніж три
    # формули, бо вирок про неї надійніший. Тому `or`, а не «більшість правил».
    рішення = Р2_УКРАЇНСЬКА if укр else Р2
    return dict(рішення=рішення,
                показувати_текст=(рішення == Р2_ПОКАЗАТИ_З_ПОЗНАЧКОЮ),
                правила=правила, українська=укр,
                спроб=с, спроб_усього=МОВНИХ_СПРОБ, позначка=позначка,
                чому=("рішення власника Р-2: " + рішення))


# ── ЧИ ВИКОНАНО ПРАВКИ: СЛОВО МОДЕЛІ ПРОТИ ФАКТУ НОВОГО СУДУ (Т-05) ──────────
# ЩО ЦЕ ЛІКУЄ. Друга ітерація є з 30.08: код судить 10 образів, модель допрацьовує
# 5. Але ЧИ САМЕ вона допрацювала, не перевіряв НІХТО. Модель писала «виправлено» —
# і це слово нікуди не приходило: вердикт другої ітерації будувався з нуля, ніби
# першої не було. Наслідок класу, не екземпляра: «полагодив» і «переписав підпис, а
# річ лишив» виглядали для коду ОДНАКОВО, а гейт, який модель просто змовчала, не
# мав каналу, щоб повернутись у вимоги, — тобто петля «код вимагає, модель виконує»
# була розімкнена на останньому кроці, і найдорожчий виклик міг нічого не змінити.
# ЩО ТУТ. Заявка моделі звіряється з ФАКТОМ нового суду, а не зараховується словом.
# Оголошена ВІДМОВА при цьому лишається законним ходом — з тим самим множником, що
# «свідомо» (K-KOH-03): інакше друга ітерація вимагала б лагодити те, що модель
# щойно пояснила, тобто працювала б проти власного задуму (та сама хвороба, що V33).

# Наскільки мусить упасти `сила_нп`, щоб це звалось «послабилась». Сили у вердикті
# округлені до двох знаків (`знахідки_вердикту`), тож найменша справжня різниця —
# 0.01; поріг стоїть нижче неї рівно настільки, щоб не ловити шум float.
_ПОРІГ_ПОСЛАБЛЕННЯ = 0.005
# Власники слів: регістр — `знахідка.РЕГІСТРИ`, дія — enum `протокол.ОБРАЗ_МОДЕЛІ`
# («виправлено|відхилено|частково»). Тут вони літералами, як у `знахідки_вердикту`:
# читач мусить бачити, ЯКЕ саме слово вирішує, не ходячи по індексах чужого кортежу.
_ГЕЙТ = "гейт"
_ДІЯ_ВІДМОВИ = "відхилено"


def _ід_образу(о, i=1):
    """ід образу і в записі `bridge._вердикти_образів` (`номер`), і в готовому
    ВЕРДИКТ_V1 (`ід`). Те саме правило, що в `вердикт_v1`, — інакше ключі
    `виконання` не зійшлися б з образами, у які їх кладуть. У записі `ід` — це
    СПИСОК id каталогу, тому рядком він тут не вважається."""
    н = о.get("номер") if isinstance(о, dict) else None
    if not н:
        х = о.get("ід") if isinstance(о, dict) else None
        н = х if isinstance(х, str) else None
    return str(н or "о%d" % i)


def _образи_суду(суд):
    """Образи суду і з готового ВЕРДИКТ_V1 (`{образи: […]}`), і зі списку записів
    `bridge._вердикти_образів`. Два джерела навмисно: фікстура тримає суд обʼєктом,
    а живий шлях дає записи ДО того, як вердикт складено, — і судити двічі заради
    однієї форми входу було б найдорожчою покупкою в системі. Список повертається
    як є (без відсіву не-словників), щоб позиції збігались з `вердикт_v1`."""
    if isinstance(суд, dict):
        суд = суд.get("образи")
    return list(суд or [])


def _знахідки_набору(вердикт):
    """`ід` → знахідка з `набір.знахідки` (K-VAR-01 / K-COMP-02) готового вердикту.

    Окрема функція, бо адреса в цих знахідок інша: `речі` тут — ід ОБРАЗІВ, а не
    номери речей (`різноманітність`), і предмет суду — набір, а не образ. Список
    записів (`bridge._вердикти_образів`) набору ще не має — тоді порожньо."""
    наб = (вердикт.get("набір") or {}) if isinstance(вердикт, dict) else {}
    return {str(z["ід"]): z for z in (наб.get("знахідки") or [])
            if isinstance(z, dict) and z.get("ід")}


def _знахідки_попереднього(вердикт):
    """`ід` знахідки → сама знахідка з попереднього вердикту. Ключ один на вердикт,
    а не на образ: `знахідки_вердикту` роздає «з-<образ>-<n>», тож ід уже несе в собі
    свій образ, і другого рівня вкладення тут не треба.

    ЗНАХІДКИ НАБОРУ ТУТ ТЕЖ (рядок 14 дошки, РВ-3 З-3). `знахідки_вердикту` роздає
    їм ід тим самим правилом («з-набір-1»), вердикт везе їх моделі нарівні з
    образними — а індекс знав лише образні, і на чесне «виконано» над «з-набір-1»
    код відповідав «у попередньому вердикті знахідки з таким ід немає». Тобто ід,
    який дав сам код, код же й не впізнавав, і виконана робота ші йшла в журнал
    невиконаною."""
    інд = {}
    for о in _образи_суду(вердикт):
        if not isinstance(о, dict):
            continue
        for z in (о.get("знахідки") or []):
            if isinstance(z, dict) and z.get("ід"):
                інд[str(z["ід"])] = z
    інд.update(_знахідки_набору(вердикт))
    return інд


def _та_сама_знахідка(z, правило, речі):
    """Чи новий рядок — ТА САМА знахідка: те саме `правило` над тими самими речами.

    ПЕРЕТИН, А НЕ РІВНІСТЬ. Знахідки одного правила зливаються в одну з обʼєднанням
    речей (Н-P37), і склад того обʼєднання міняється разом з образом: новий рядок над
    двома речами з трьох — та сама знахідка, а не нова. Знахідка без речей (над
    образом у цілому) зіставляється лише правилом — адреси в неї нема й не було."""
    if not isinstance(z, dict) or str(z.get("правило") or "") != правило:
        return False
    нові = {str(r) for r in (z.get("речі") or []) if r not in (None, "")}
    if not речі or not нові:
        return True
    return bool(нові & речі)


def _речі_образу(о):
    """Номери речей образу: `речі` у вердикті, `речі_н` у записі `_вердикти_образів`."""
    if not isinstance(о, dict):
        return set()
    return {str(r) for r in (о.get("речі") or о.get("речі_н") or [])}


def _зіставити_образи(відповідь, нові):
    """Образ відповіді моделі → індекс запису нового суду над ним.

    ПОЗИЦІЯ, А НЕ ІД. `ід` образу дає модель, а `номер` у суді роздає код за
    позицією (`bridge._вердикти_образів`), і ці два слова не зобовʼязані сходитись:
    модель вільна назвати образи як завгодно. Коли довжини рівні — позиція і є
    зіставленням. Коли ні (образ, у якому не резолвився ЖОДЕН id, `_вердикти_образів`
    викидає — див. `_розбір_блоків`), позиція зсувається, і далі образи зводяться
    найбільшим перетином речей: номери в обох списках з однієї нумерації пакета."""
    if len(відповідь) == len(нові):
        return list(range(len(нові)))
    зайняті, вих = set(), []
    for о in відповідь:
        мої = {str(r) for r in (о.get("речі") or [])}
        найкращий, спільних = None, 0
        for j, н in enumerate(нові):
            if j in зайняті:
                continue
            с = len(мої & _речі_образу(н))
            if с > спільних:
                найкращий, спільних = j, с
        if найкращий is not None:
            зайняті.add(найкращий)
        вих.append(найкращий)
    return вих


def _чи_зникла(з_попередня, знахідки_нові):
    """Одна заявка проти факту: `(перевірено, чому, збіг)`.

    `збіг` — рядок нового суду, який лишився на місці знахідки: його послаблює
    оголошена відмова. Порівнюється НАЙСИЛЬНІШИЙ зі збігів, бо саме він і є тією
    знахідкою після злиття."""
    правило = str(з_попередня.get("правило") or "")
    речі = {str(r) for r in (з_попередня.get("речі") or []) if r not in (None, "")}
    було = float(з_попередня.get("сила_нп") or 0)
    збіги = [z for z in знахідки_нові if _та_сама_знахідка(z, правило, речі)]
    if not збіги:
        return True, "%s над цими речами в новому суді немає" % правило, None
    збіг = max(збіги, key=lambda z: float(z.get("сила_нп") or 0))
    стало = float(збіг.get("сила_нп") or 0)
    if стало < було - _ПОРІГ_ПОСЛАБЛЕННЯ:
        return True, "%s послабилась %.2f → %.2f" % (правило, було, стало), збіг
    return False, ("%s лишилась %.2f (було %.2f) над %s"
                   % (правило, стало, було, ", ".join(збіг.get("речі") or []) or "образом")), збіг


def перевірити_виконання(попередній_вердикт, образи_v1, новий_суд):
    """Заявки моделі у «виконано» проти факту нового суду — поле `виконання` (Т-05).

    Три входи, усі з одного обміну: `попередній_вердикт` — ВЕРДИКТ_V1 першої
    ітерації (у ньому знахідки з `ід`, на які модель і посилається); `образи_v1` —
    відповідь моделі на нього (ОБРАЗИ_V1 із полем `виконано`); `новий_суд` — суд
    коду над ЦИМИ образами, готовим вердиктом або записами `_вердикти_образів`.

    ЩО ЗАРАХОВУЄТЬСЯ, І ЧОМУ САМЕ ТАК.
    · `виправлено` і `частково` — лише ФАКТОМ: знахідка того самого правила над тими
      самими речами зникла або впала в силі. Слово без факту дає `перевірено=false`
      і `чому`, і модель читає це в наступному вердикті. Різниці між двома діями тут
      нема навмисно: обидві заявляють РУХ, а міряється рух однаково; що саме модель
      назвала, лишається в полі `дія` для журналу.
    · `відхилено` з `чому` — оголошений хід: приймається як є, а знахідка, що
      лишилась, іде тим самим множником, що оголошення в «свідомо»
      (`СВІДОМИЙ_МНОЖНИК`, K-KOH-03). Без `чому` не приймається: «відхилено» без
      причини — не хід, а тиша, і зарахувати її означало б дати моделі спосіб
      закрити будь-яку знахідку одним словом.
    · Гейт, якого модель не назвала й який СТОЇТЬ у новому суді, — у `невиконано` і
      в повторну вимогу. Гейт, що зник (річ замінено, образ знято з розгляду), туди
      не потрапляє: вимога була про факт, не про звіт, а «зніми образ із розгляду»
      сам вердикт і пропонує (`ВИМОГИ_ВЕРДИКТУ`).

    · Знахідка НАБОРУ (K-VAR-01 / K-COMP-02, ід «з-набір-N») зіставляється не зі
      знахідками образу, а з набором нової ітерації: `різноманітність` над тими
      записами, які модель повернула. Предмет цих правил — склад набору, і
      «виправлено» тут означає «набір став іншим», а не «в цьому образі зникло».

    Віддає: `{"образи": {<ід образу> : [{знахідка, дія, перевірено, чому}]},
    "невиконано": [<ід знахідки>], "вимоги": [<рядок>],
    "послаблення": {<ід образу>: {<ід НОВОЇ знахідки>: <чому>}},
    "послаблення_набору": {<ід НОВОЇ знахідки набору>: <чому>}}`. Послаблення тут
    лише НАЗВАНЕ, а накладає його `вердикт_v1` — той, хто будує рядки знахідок: ця
    функція нічого не переписує на вході, бо той самий запис образу читають ще показ
    і журнал.
    """
    інд = _знахідки_попереднього(попередній_вердикт)
    набір_поп = _знахідки_набору(попередній_вердикт)
    нові = _образи_суду(новий_суд)
    відповідь = образи_v1.get("образи") if isinstance(образи_v1, dict) else образи_v1
    відповідь = [о for о in (відповідь or []) if isinstance(о, dict)]
    зіставлення = _зіставити_образи(відповідь, нові)
    за_образом, послаблення, послаблення_набору, згадані = {}, {}, {}, set()
    # ФАКТ ДЛЯ ЗНАХІДКИ НАБОРУ — НАБІР НОВОЇ ІТЕРАЦІЇ, А НЕ ЗНАХІДКИ ОДНОГО ОБРАЗУ.
    # K-VAR-01 і K-COMP-02 судять склад набору, тож «виправлено» тут означає «набір
    # став іншим»: міряти це можна лише перерахунком `різноманітність` над тими
    # образами, які модель ПОВЕРНУЛА (зіставлені записи нового суду), а не над усіма
    # десятьма записами й не над знахідками образу, де цих правил не буває зовсім.
    # Ліниво і один раз: набір перераховується тільки якщо модель справді заявила
    # виконання над його знахідкою — інакше це був би другий O(n²) на кожен вердикт.
    _кеш_набору = {}

    def _набір_нового_суду():
        if "знахідки" not in _кеш_набору:
            підмножина = [нові[j] for j in зіставлення
                          if j is not None and 0 <= j < len(нові) and isinstance(нові[j], dict)]
            наб = різноманітність(підмножина) or {}
            _кеш_набору["знахідки"] = [z for z in (наб.get("знахідки") or []) if isinstance(z, dict)]
        return _кеш_набору["знахідки"]

    for k, о in enumerate(відповідь):
        j = зіставлення[k] if k < len(зіставлення) else None
        суд = нові[j] if (j is not None and j < len(нові) and isinstance(нові[j], dict)) else None
        ід_о = _ід_образу(суд, (j or 0) + 1) if суд else _ід_образу(о, k + 1)
        знахідки_нові = [z for z in ((суд or {}).get("знахідки") or []) if isinstance(z, dict)]
        записи, бачено = [], set()
        for з in (о.get("виконано") or []):
            if not isinstance(з, dict) or not з.get("знахідка"):
                continue
            ід_з = str(з["знахідка"])
            згадані.add(ід_з)
            if ід_з in бачено:          # та сама знахідка двічі — це не два виконання
                continue
            бачено.add(ід_з)
            дія = str(з.get("дія") or "")
            чому_моделі = str(з.get("чому") or "").strip()
            # `дія` порожнім рядком не пишеться: схема тримає її необовʼязковою, і
            # «дії не названо» — це ВІДСУТНЄ поле, а не «» (те саме правило, що для
            # `ремонт` у `знахідки_вердикту`).
            запис = lambda перев, чому: dict(
                знахідка=ід_з, перевірено=bool(перев), чому=чому,
                **({"дія": дія} if дія else {}))
            поп = інд.get(ід_з)
            if поп is None:
                записи.append(запис(False, "у попередньому вердикті знахідки з таким ід немає"))
                continue
            набірна = ід_з in набір_поп
            if суд is None and not набірна:
                записи.append(запис(False, "образ не дійшов до суду — перевіряти нічого"))
                continue
            перев, чому, збіг = _чи_зникла(
                поп, _набір_нового_суду() if набірна else знахідки_нові)
            if дія == _ДІЯ_ВІДМОВИ:
                # ОГОЛОШЕНА ВІДМОВА — ХІД, А НЕ ПРОВАЛ. Факт тут не суперечить
                # заявці: модель і не обіцяла, що знахідка зникне.
                if чому_моделі:
                    перев, чому = True, "відхилено свідомо: %s" % чому_моделі[:120]
                    if збіг and збіг.get("ід") and not збіг.get("свідомий"):
                        # Знахідка набору послаблюється В НАБОРІ, не в образі: у
                        # `зап["знахідки"]` образу її нема, і покласти її туди
                        # означало б написати оголошений хід у нікуди.
                        (послаблення_набору if набірна
                         else послаблення.setdefault(ід_о, {}))[str(збіг["ід"])] = чому_моделі[:120]
                else:
                    перев, чому = False, "«відхилено» без «чому» — причини нема, хід не оголошений"
            записи.append(запис(перев, чому))
        if записи:
            # Не `=`, а дозапис: `ід` образу дає модель, і два її образи з одним
            # іменем не мусять мовчки перетирати одне одного — це той самий клас
            # тиші, що й «невалідна відповідь = порожня» (§1(б) протоколу).
            за_образом.setdefault(ід_о, []).extend(записи)
    # ГЕЙТИ, ЯКИХ НІХТО НЕ НАЗВАВ: шукаються по ВСЬОМУ новому суду, а не в одному
    # образі, — образ, що зник, знімає свої гейти разом із собою, і саме це нам і
    # треба відрізнити від гейта, який просто перенесли в наступну ітерацію.
    усі_нові = [z for н in нові if isinstance(н, dict)
                for z in (н.get("знахідки") or []) if isinstance(z, dict)]
    # ПОРЯДОК — ВЕРДИКТІВ, НЕ АЛФАВІТНИЙ: `інд` іде образами й силою, як їх склав
    # `знахідки_вердикту`, а алфавіт поставив би «з-о10-1» перед «з-о2-1», і модель
    # прочитала б це як зміну пріоритету.
    невиконано = []
    for ід_з, з in інд.items():
        if з.get("регістр") != _ГЕЙТ or ід_з in згадані:
            continue
        правило = str(з.get("правило") or "")
        речі = {str(r) for r in (з.get("речі") or []) if r not in (None, "")}
        джерело = _набір_нового_суду() if ід_з in набір_поп else усі_нові
        if any(_та_сама_знахідка(z, правило, речі) for z in джерело):
            невиконано.append(ід_з)
    вимоги = []
    if невиконано:
        вимоги.append(
            "Гейти %s стоять і в новому суді, а в «виконано» їх не названо: на кожен — "
            "запис «виконано» свого образу (виправлено|відхилено|частково і «чому») або "
            "зніми образ із розгляду."
            % ", ".join("«%s»" % і for і in невиконано[:6]))
    return dict(образи=за_образом, невиконано=невиконано, вимоги=вимоги,
                послаблення=послаблення, послаблення_набору=послаблення_набору)


# ── РІЗНОМАНІТНІСТЬ НАБОРУ Й ГЕРОЙ ОБРАЗУ (Т-10) ────────────────────────────
# ЩО ЦЕ ЛІКУЄ. Модель дає десять образів, і доти ніхто не питав, чи це десять
# образів. K-VAR-01 («портфель РІЗНИХ полюсів, а не наступні за порядком») і
# K-COMP-02 («один якір, не два і не нуль») в коді БУЛИ — і обидва лишали самий
# запис сліду в `composer._портфель`, тобто судили портфель, який збирав КОД, і
# писали вирок у лог. Портфель коду знесено 31.08 (модель компонує сама), а
# правила лишились там же: проба P17 зміряла їх як «емітується лише слідом», і
# `gate_reach.НА_ЗНАХІДКУ` тримає обидва в знаменнику «мусять дати знахідку».
# Наслідок класу, не екземпляра: набір із пʼяти варіацій однієї відповіді й набір
# із пʼяти різних задумів виглядали для моделі ОДНАКОВО — жодного рядка про це у
# вердикті не було, тож «зроби різні» ніхто не просив, а ілюзія вибору доходила
# до людини як вибір.
# ЩО КОД РОБИТЬ І ЧОГО НЕ РОБИТЬ (Т-10, «що код НЕ робить»). Код МІРЯЄ схожість і
# називає групи; він не обирає, який образ лишити, не переставляє й не викидає
# образів сам. Тому обидві знахідки виходять регістром «репліка» (стеля тіру T3 —
# `реєстр_правил.REGISTRY`), а не гейтом: це спостереження над набором, а не заборона.

def риси_образу(речі, тіло=None, ном=None):
    """Три ознаки ОДНОГО образу, якими Т-10 порівнює образи між собою:
    колірна схема, літера силуету і герой.

    `речі` — речі, відновлені з каталогу (`composer._у_річ`), а НЕ рядки вердикту:
    схема рахується по `lab`, літера по `крій`, герой по `composer._виразність`, і
    жодного з цих полів у `речі_н` («#412·29») нема й бути не може.

    `ном` — нумерація пулу. Герой називається ТИМ САМИМ номером, що й речі образу
    (`речі_н`): голий id каталогу в записі, який читають показ і журнал, був би
    другою адресою тієї самої речі — і першим кандидатом розійтися з першою.

    НЕВІДОМО — ОКРЕМЕ ЗНАЧЕННЯ, А НЕ ЗБІГ. Кожна ознака віддає `None`, коли входу
    нема: кольору не виміряно, крій відомий менш ніж у `крою_для_літери` речей,
    жодної речі понад порогом виразності. Порівняння пар нижче вимагає `is not
    None` з обох боків — інакше два образи, про які не знають нічого, «збігались»
    би саме цим незнанням, і набір із десяти невиміряних виходив би однією групою.
    """
    import composer as _КМ, outfit as _O
    import колір_образу as _КОЛІР, реєстр_правил as _РЕЄСТР, формальність as _ФОРМ   # Н-02-01, сесія 4
    речі = [r for r in (речі or []) if isinstance(r, dict)]
    # `речей` — НЕ довідка, а розрізнювач станів. Без нього образ, речей якого не
    # вдалось відновити з каталогу (рука без каталогу, чужий магазин, порожній
    # `_каталог` у пакеті), мав би `виразні=[]` — рівно те саме, що образ, у якому
    # виразної речі справді нема, — і `різноманітність` записала б його в
    # «без героя», тобто звинуватила б модель у тому, чого код не міряв.
    вих = dict(схема=None, літера=None, герой=None, виразні=[], крої=0, речей=len(речі))
    if not речі:
        return вих
    # СХЕМА — СІМʼЇ КЛАСТЕРІВ, НЕ РЕЧЕЙ. `колір_образу.кластери` зводить речі одного
    # кольору в один голос (чорна сукня і чорні човники — один колір схеми, не
    # два) тим самим порогом ΔE, яким їх зводять колірні правила; рахувати сімʼї
    # по речах означало б завести другу колірну арифметику поруч із наявною.
    try:
        вих["схема"] = sorted({к["сім_я"] for к in _КОЛІР.кластери(_O.елементи(речі))})
    except Exception:
        вих["схема"] = None
    вих["крої"] = sum(1 for r in речі if _O.крій_речі(r))
    if тіло and вих["крої"] >= _РЕЄСТР.C["крою_для_літери"]:
        try:
            import silhouette as _СЛ
            л = _СЛ.літера(_СЛ.обгортка(тіло, речі))
            вих["літера"] = л.get("літера") if л.get("доступно") else None
        except Exception:
            вих["літера"] = None
    # ГЕРОЙ — НАЙВИРАЗНІША РІЧ ПОНАД ПОРОГОМ; `виразні` — УСІ понад порогом.
    # «Два герої» рахується саме по цьому списку, а не по відриву першої від
    # другої: K-COMP-02 забороняє ДВА якорі, а не близькі оцінки.
    оцінки = []
    for r in речі:
        try:
            оцінки.append((_КМ._виразність(r),
                           номер_речі(r.get("id"), ном, r.get("частина_комплекту"))))
        except Exception:
            continue
    вих["виразні"] = [і for в, і in sorted(оцінки, key=lambda т: -т[0])
                      if в >= _РЕЄСТР.C["виразність_героя"]]
    вих["герой"] = вих["виразні"][0] if вих["виразні"] else None
    return вих


def _пара_образів(a, b):
    """Факти про одну пару: спільні речі, Jaccard за `н`, збіг схеми, літери, героя."""
    ра, рб = _речі_образу(a), _речі_образу(b)
    сп, об = len(ра & рб), len(ра | рб)
    риса = lambda о, k: ((о.get("риси") or {}) if isinstance(о, dict) else {}).get(k)
    рівні = lambda k: (риса(a, k) is not None and риса(a, k) == риса(b, k))
    return dict(спільних=сп, усього=об, jaccard=(round(сп / об, 3) if об else 0.0),
                схема=рівні("схема"), літера=рівні("літера"), герой=рівні("герой"))


def _множина(n, одна, дві, багато):
    """«1 річ · 3 речі · 7 речей». Формулювання набору читає МОДЕЛЬ, і «0 речі» в
    ньому коштувало б рівно того, чим платять за всяку неточність у промпті."""
    n = abs(int(n))
    if n % 100 // 10 == 1:
        return багато
    return {1: одна, 2: дві, 3: дві, 4: дві}.get(n % 10, багато)


def _чому_група(ід, пари):
    """Формулювання групи для моделі — те саме, що в Т-10: «о2, о5, о7 — варіанти
    одного задуму: спільні 3 речі з 4, одна схема; лиши один або зроби різними»."""
    сп = min(п["спільних"] for п in пари)
    ус = max(п["усього"] for п in пари)
    спільне = [н for н, k in (("одна схема", "схема"), ("один герой", "герой"),
                              ("одна літера силуету", "літера"))
               if all(п[k] for п in пари)]
    return ("%s — варіанти одного задуму: спільні %d %s з %d%s; "
            "лиши один або зроби різними"
            % (", ".join(ід), сп, _множина(сп, "річ", "речі", "речей"), ус,
               ("" if not спільне else ", " + ", ".join(спільне))))


def _повтор_слота(об, ід):
    """Слоти, у яких БІЛЬШЕ ПОЛОВИНИ образів набору стоять на одній і тій самій речі.

    Вхід — записи `bridge._вердикти_образів` з мапою `слоти_н` (`номер речі → слот`):
    вона будується там, де номер і слот лежать поруч, бо в самому вердикті лишаються
    тільки номери, а «одне взуття на десять образів» і «одна каблучка» по номерах
    нерозрізненні.

    БЕЗ `слоти_н` ФУНКЦІЯ МОВЧИТЬ, І ЦЕ КАЖЕТЬСЯ ВГОЛОС: готовий ВЕРДИКТ_V1
    (`_образи_суду` приймає і його) цього поля не несе, тож тут «нема входу», а не
    «повторів нема» — рядок про це дописує `різноманітність` у `чому`.

    Поріг — `частка_повтору_слота` з реєстру: рівно половина набору на одній речі
    ще лишає вибір, більше половини — вже ні. Слот рахується від числа образів, у
    яких він УЗАГАЛІ є: сумка в трьох образах із десяти міряється проти трьох.
    """
    import реєстр_правил as _РЕЄСТР
    поріг = _РЕЄСТР.C["частка_повтору_слота"]
    лічба = {}
    for i, о in enumerate(об):
        for н, сл in (о.get("слоти_н") or {}).items():
            лічба.setdefault(сл, {}).setdefault(str(н), []).append(ід[i])
    вих = []
    for сл in sorted(лічба):
        образів = sum(len(v) for v in лічба[сл].values())
        н, де = max(лічба[сл].items(), key=lambda kv: (len(kv[1]), kv[0]))
        якщо = len(де)
        if якщо < 2 or образів < 2 or якщо / образів <= поріг:
            continue
        вих.append(dict(
            слот=сл, річ=н, образи=list(де), частка=round(якщо / образів, 3),
            суть="слот «%s» — одна річ %s на %d %s із %d"
                 % (сл, н, якщо, _множина(якщо, "образ", "образи", "образів"), образів),
            чому="%s стоять на одній речі в слоті «%s» (%s): у цьому слоті набір не "
                 "дає вибору — лиши один такий образ або візьми іншу річ"
                 % (", ".join(де), сл, н)))
    return вих


def різноманітність(образи):
    """`набір.різноманітність`, `набір.герой` і знахідки набору K-VAR-01 / K-COMP-02.

    Вхід той самий, що в `вердикт_v1`: записи `bridge._вердикти_образів` або готовий
    `ВЕРДИКТ_V1` (`_образи_суду`). Ід образів роздаються тим самим правилом
    (`_ід_образу`), інакше «о5» у групі вказував би не на той образ, що «о5» у
    списку образів вердикту.

    ГРУПА «ВАРІАНТИ ОДНОГО» — ЗВʼЯЗНА КОМПОНЕНТА, А НЕ ПАРА. Три образи, що
    різняться однією сумкою, схожі попарно всі три; видавати це трьома парами
    означало б сказати те саме тричі й лишити моделі рахувати самій.

    Умова ребра (Т-10, крок 2): Jaccard ≥ `jaccard_варіанта` **або** (та сама
    колірна схема І той самий герой). Друга половина потрібна саме тому, що склад
    буває різний, а задум — той самий: інші джинси під тим самим червоним пальтом
    у тій самій схемі — це не другий образ.

    Повертає `None`, коли образів нема зовсім: набір без образів — не «ок», а
    відсутність предмета, і казати над ним «різноманітність ок» було б брехнею.
    """
    import outfit as _O
    import колір_образу as _КОЛІР, реєстр_правил as _РЕЄСТР, формальність as _ФОРМ   # Н-02-01, сесія 4
    зап = [(i, о) for i, о in enumerate(_образи_суду(образи), 1)
           if isinstance(о, dict) and (о.get("речі") or о.get("речі_н"))]
    if not зап:
        return None
    ід = [_ід_образу(о, i) for i, о in зап]
    об = [о for _, о in зап]
    вих, зн = {}, []
    # ── ОДИН І ТОЙ САМИЙ СЛОТ НА ВЕСЬ НАБІР (K-VAR-01, 18.09.2026) ───────────
    # ЩО БУЛО ЗЛАМАНО. Ребро «варіанти одного» — це Jaccard пари АБО (та сама
    # схема І той самий герой). Десять образів, у яких різні сукня, сумка й
    # прикраси, а взуття одне, дають Jaccard 1/9 = 0.11 при порозі 0.6, різні
    # схеми й різних героїв — тобто жодного ребра. Виміряно на живому шляху
    # (`проби/vzuttia_руки.py`, каталог_повний, «побачення · ресторан · 19:00»):
    # десять образів на ОДНІЙ парі давали `ок=true`, «усі 10 образів різні» і
    # нуль знахідок набору. Набір, у якому взуття не вибирають, оголошувався
    # вибором — рівно те, що тема-4 XIII зве вибором на вигляд.
    # ЧОМУ ЦЕ ГРУПА, А НЕ ОКРЕМА ЗНАХІДКА. `знахідки_вердикту` зливає знахідки
    # одного правила в ОДИН рядок із найсильнішої (Н-P37), тож другий K-VAR-01
    # тут загубив би свою суть щоразу, коли поруч є група за Jaccard. Отже це
    # той самий предмет тим самим правилом: перелік образів, які між собою не
    # вибір, і причина в рядку `чому`.
    повтори = _повтор_слота(об, ід)
    if len(об) >= 2:
        поріг = _РЕЄСТР.C["jaccard_варіанта"]
        сусіди = {i: set() for i in range(len(об))}
        пари = {}
        for i in range(len(об)):
            for j in range(i + 1, len(об)):
                п = пари[(i, j)] = _пара_образів(об[i], об[j])
                if п["jaccard"] >= поріг or (п["схема"] and п["герой"]):
                    сусіди[i].add(j)
                    сусіди[j].add(i)
        групи, бачені = [], set()
        for i in range(len(об)):
            if i in бачені or not сусіди[i]:
                continue
            стек, компонента = [i], []
            while стек:
                k = стек.pop()
                if k in бачені:
                    continue
                бачені.add(k)
                компонента.append(k)
                стек += [x for x in сусіди[k] if x not in бачені]
            if len(компонента) > 1:
                групи.append(sorted(компонента))
        чому = [_чому_група([ід[i] for i in г],
                            [пари[(min(a, b), max(a, b))] for a in г for b in г if a < b])
                for г in групи]
        всі_групи = [[ід[i] for i in г] for г in групи] + [п["образи"] for п in повтори]
        чому = чому + [п["чому"] for п in повтори]
        вих["різноманітність"] = dict(
            ок=not всі_групи, групи=всі_групи,
            чому=("; ".join(чому) if чому
                  else "усі %d %s різні: жодна пара не збіглася ні складом, ні схемою "
                       "з героєм%s" % (len(об), _множина(len(об), "образ", "образи",
                                                         "образів"),
                                       "" if any(о.get("слоти_н") for о in об)
                                       else "; повтор речі в слоті НЕ перевірявся — "
                                            "у записах образів нема слотів речей")))
        if всі_групи:
            у_групах = len({і for г in всі_групи for і in г})
            зн.append(_РЕЄСТР._зн(
                "K-VAR-01", "soft",
                "%d %s із %d — варіанти одного задуму, а не різні образи%s"
                % (у_групах, _множина(у_групах, "образ", "образи", "образів"), len(об),
                   ("" if not повтори else
                    ": " + "; ".join(п["суть"] for п in повтори))),
                # АДРЕСА ЗНАХІДКИ НАБОРУ — ІД ОБРАЗІВ, не речей (`протокол.ВЕРДИКТ_V1`).
                # Номер повтореної речі стоїть у `суть`, де його читає модель.
                sorted({і for г in всі_групи for і in г}),
                "тема-4 XIII: набір існує, щоб між образами БУЛО з чого обирати; "
                "варіанти одного задуму дають вибір лише на вигляд, а слот, у якому "
                "на весь набір одна річ, — це слот, який не вибирали",
                ремонт="лишити по одному образу з кожної названої групи, а решту "
                       "зробити іншими: інший герой або інша колірна схема — не інша "
                       "сумка при тому самому задумі" + ("" if not повтори else
                       "; у названих слотах (%s) взяти РІЗНІ речі — одна пара на весь "
                       "набір не лишає в цьому слоті вибору"
                       % ", ".join(п["слот"] for п in повтори)),
                вимір=у_групах / len(об), поріг=0.0, повна=1.0))
    # ГЕРОЯ СУДИМО ЛИШЕ ТАМ, ДЕ БУЛО ЩО МІРЯТИ: риси без жодної відновленої речі —
    # це «не виміряно», а не «героя нема» (див. `речей` у `риси_образу`).
    з_рисами = [(і, о.get("риси")) for і, о in zip(ід, об)
                if isinstance(о.get("риси"), dict) and о["риси"].get("речей")]
    if з_рисами:
        без = [і for і, р in з_рисами if not р.get("виразні")]
        двоє = [і for і, р in з_рисами if len(р.get("виразні") or []) >= 2]
        вих["герой"] = dict(ок=not (без or двоє), образи_без_героя=без,
                            образи_з_двома=двоє)
        if без or двоє:
            зн.append(_РЕЄСТР._зн(
                "K-COMP-02", "soft",
                "герой образу: %s"
                % "; ".join(([("без виразної речі — %s" % ", ".join(без))] if без else [])
                            + ([("дві виразні речі сперечаються — %s" % ", ".join(двоє))]
                               if двоє else [])),
                без + двоє,
                "K-COMP-02: образ веде ОДНА виразна річ. Нуль — образ нічого не "
                "каже; два — вони змагаються між собою, і жодна не читається якорем",
                ремонт="дати кожному названому образу рівно одну виразну річ: додати "
                       "якір туди, де його нема, і приглушити одну з двох там, де їх дві",
                вимір=len(set(без) | set(двоє)) / len(з_рисами), поріг=0.0, повна=1.0))
    if зн:
        рядки, _ = знахідки_вердикту(зн, "набір")
        if рядки:
            вих["знахідки"] = рядки
    return вих or None


def координація_набору(образи):
    """`набір.координація` — де кожен образ стоїть на кривій K-COMP-01 (рядок 5 дошки).

    ЩО ЦЕ МІНЯЄ В РІШЕННІ. Поле оголошене в `протокол.ВЕРДИКТ_V1` і не мало ЖОДНОГО
    писача: `coordination.координація()` кладе свій вирок у `знахідки` ОБРАЗУ, тобто
    відповідає на питання «що не так із цим образом», а не на питання набору — «хто
    з десятьох скоординований найтісніше, а хто найрозхристаніше». Друге питання і є
    тим, що Gray та ін. 2014 виміряли: оптимум — це ПОЗИЦІЯ В НАБОРІ, не абсолютна
    відстань. Модель бачила десять окремих зауважень і не бачила таблиці.

    Ранг рахується з тих самих чисел, що й знахідка: середньої попарної близькості
    образу (`близькість_образу` → запис `bridge._вердикти_образів`). Набір без
    розкиду (`coordination.розкид_набору`) рангу не дає — тоді поля нема зовсім, а
    не нуль: «ранг був би шумом вимірювання» лишається утриманням, як і в правилі.

    `бік` — те саме слово, що каже знахідка, у формі дії: ранг нижче вершини —
    образ скоординованіший за більшість, отже «розвести»; вище — «звести».
    """
    пари = [(str(о.get("номер") or ""), о.get("близькість"))
            for о in (образи or [])
            if isinstance(о, dict) and о.get("номер") and о.get("близькість") is not None]
    if len(пари) < 3:
        return []
    try:
        import coordination as _КО
    except Exception:
        return []
    числа = [б for _, б in пари]
    if not (_КО.розкид_набору(числа) or {}).get("можна"):
        return []
    вершина = min(0.95, max(0.05, 0.5 + _КО.C["зсув_вершини"]))
    вих = []
    for ід, б in пари:
        ранг = _КО.ранг_у_наборі(б, числа)
        if ранг is None:
            continue
        вих.append(dict(ід=ід, ранг=ранг,
                        бік=("—" if abs(ранг - вершина) < 1e-9
                             else ("розвести" if ранг < вершина else "звести"))))
    return вих


def вердикт_v1(образи, варіантів=2, випадок=None, кандидати=None, ітерація=1,
               мова=None, реєстри=None, попередній_вердикт=None, відповідь_моделі=None):
    """Другий виклик: вердикт коду над образами моделі — один обʼєкт `ВЕРДИКТ_V1`.

    `образи` — записи `bridge._вердикти_образів`: по одному на образ моделі, уже з
    рядками знахідок (`знахідки_вердикту`), блокерами (`блокери_структури`), речами
    з номерами й чеклістом. Тут вони лише лягають у форму схеми; запис без цих полів
    (образ, на якому суддя впав винятком) у вердикт не входить — його номер лишає
    дірку, і це чесніше за образ із порожніми знахідками.

    ПЕРЕВІРКА ВИКОНАННЯ (Т-05) — ЛИШЕ КОЛИ Є ЧИМ ПЕРЕВІРЯТИ. `попередній_вердикт`
    (ВЕРДИКТ_V1 першої ітерації) і `відповідь_моделі` (ОБРАЗИ_V1 із «виконано») дає
    викликач; з ними на другій ітерації зʼявляються `виконання` в кожному образі,
    `набір.невиконано` і повторна вимога у `завдання.вимоги`, а знахідка, від якої
    модель оголошено відмовилась, іде множником `СВІДОМИЙ_МНОЖНИК`. Без них вердикт
    той самий, що доти: перевірка, яка не має попереднього вердикту, мусить МОВЧАТИ,
    а не вважати, що виконувати було нічого.

    РІЗНОМАНІТНІСТЬ І ГЕРОЙ (Т-10) — `різноманітність` над тими самими записами:
    `набір.різноманітність` (групи «варіантів одного»), `набір.герой` (образи без
    якоря і з двома) і `набір.знахідки` — K-VAR-01 / K-COMP-02 рядками
    `ЗНАХІДКА_ВЕРДИКТУ`, а не самим слідом у лог, як доти (проба P17).

    ЩО ТУТ НЕ БУДУЄТЬСЯ, І ЧОМУ.
    `завдання.відповідь` завжди «ОБРАЗИ_V1» — вибір (ВИБІР_V1) вводить Т-06.
    `ітерація` приходить від викликача (показ — Т-04); без неї — 1.
    `реєстр` і `мова` — на вердикт один: мовний гейт судить увесь текст відповіді,
    а реєстровий вектор верхнього рівня — рівно те, що й доти читав промпт.
    `поза_кандидатами` (річ не з пулу, резолвлена з повного каталогу) у схемі поля
    не має і до моделі не їде — лишається в записі образу для журналу; прозовий
    промпт друкував його рядком «поза списком речей».
    """
    _ном = номери_речей(кандидати)[0] if (кандидати and ПАКУВАТИ_ІНДЕКСОМ) else {}
    try:
        _іт = int(ітерація or 1)
    except (TypeError, ValueError):
        _іт = 1
    # НОВИЙ СУД — ЦЕ `образи`, ЯКІ ТУТ І ЛЯГАЮТЬ У ФОРМУ: судити вдруге заради
    # перевірки не треба, а рахувати її після складання вердикту означало б правити
    # вже готовий обʼєкт (те саме, чого Т-03 позбулась, знісши `_стислі_знахідки`).
    вик = (перевірити_виконання(попередній_вердикт, відповідь_моделі, образи)
           if (_іт >= 2 and попередній_вердикт and відповідь_моделі) else None)
    # Словник і нумерація потрібні лише для оголошених ВІДМОВ (нижче): решта
    # оголошень приїхала сюди вже резолвленою, з `образ.свідомі`.
    _слов_в = _словник_речей(кандидати) if (вик and вик.get("послаблення")) else {}
    _ном_в = _за_номером(кандидати) if _слов_в else {}
    обр = []
    for i, о in enumerate(образи or [], 1):
        if not isinstance(о, dict) or "речі_н" not in о:
            continue
        блокери = list(о.get("блокери") or [])
        зап = dict(ід=str(о.get("номер") or ("о%d" % i)), речі=list(о["речі_н"]))
        if о.get("підпис"):
            зап["підпис"] = str(о["підпис"])
        зап["структура"] = dict(ок=not блокери, блокери=блокери)
        зап["знахідки"] = list(о.get("знахідки") or [])
        _відмови = []
        if вик:
            # ОГОЛОШЕНА ВІДМОВА ПОСЛАБЛЮЄ РЯДОК ТУТ, НА КОПІЇ. Сирі знахідки
            # лишаються в записі образу як були — їх читають показ і журнал, і
            # множник, накладений двічі, дав би 0.36 замість 0.6 на другому колі.
            # Знахідка, уже позначена `свідомий` (оголошення в «свідомо» цієї ж
            # відповіді, `_застосувати_свідомі`), не послаблюється вдруге: це той
            # самий хід, названий двома словами, а не два різні.
            пос = (вик["послаблення"].get(зап["ід"]) or {})
            if пос:
                зап["знахідки"] = [
                    (dict(z, сила_нп=round(float(z.get("сила_нп") or 0) * СВІДОМИЙ_МНОЖНИК, 2),
                          свідомий=True)
                     if (str(z.get("ід") or "") in пос and not z.get("свідомий")) else z)
                    for z in зап["знахідки"]]
                # ── «ВІДХИЛЕНО — БО ЦЕ ЗАДУМ» ТЕЖ ОГОЛОШЕНИЙ ХІД, І ВЕРДИКТ НЕСЕ
                # ЙОГО СЛОВАМИ (рядок 9 дошки, 19.09.2026). `перевірити_виконання`
                # рахує «відхилено» з «чому» ходом і послаблює знахідку ТИМ САМИМ
                # множником, що й «свідомо» (рядок вище). Але сам хід лишався
                # ЛИШЕ міткою `знахідка.свідомий`: поле `свідомі` образу збиралось
                # тільки з поля `свідомо` відповіді. Крок вибору (виклик 3) читає
                # рівно `образ.свідомі` (`вибір_з_json.розриви`) — тож хід,
                # оголошений через «виконано», помирав рівно там: знахідка
                # поверталась до повної сили, ремонт бачив огріх, а жінка не чула
                # «це задум». Тепер джерело істини одне — `образ.свідомі` вердикта,
                # і в ньому обидва способи оголосити хід.
                _відмови = [dict(річ=", ".join(str(r) for r in (z.get("речі") or []) if r),
                                 чому=str(пос[str(z.get("ід") or "")]))
                            for z in (о.get("знахідки") or [])
                            if str(z.get("ід") or "") in пос and not z.get("свідомий")]
            виконання = вик["образи"].get(зап["ід"])
            if виконання:
                зап["виконання"] = виконання
        # ── ОГОЛОШЕНИЙ ХІД СТОЇТЬ У ВЕРДИКТІ, А НЕ ЛИШЕ В МІТЦІ ЗНАХІДКИ ──────
        # ЩО ЦЕ МІНЯЄ В РІШЕННІ (рядок 9 дошки). Вердикт ніс наслідок оголошення
        # (`знахідка.свідомий`, сила ×0.6) і не ніс самого оголошення. Тому крок
        # вибору (виклик 3), який дістає РІВНО цей обʼєкт (`вердикт_вибору`), не
        # мав звідки взяти ні слів ші, ні адресата: `вибір_з_json` складав образ
        # наново, судив його з чистого аркуша, і хід, оголошений на ітерації 2,
        # зникав — у журнал і на картку йшла повна сила.
        _свід, _бач = [], set()
        for с in (list(о.get("свідомі") or [])
                  + (_свідомі_з_json(_відмови, _слов_в, _ном_в) if _відмови else [])):
            if not isinstance(с, dict) or not с.get("текст"):
                continue
            з = dict({k: str(с[k]) for k in ("річ", "чому") if с.get(k)},
                     текст=str(с.get("текст") or ""))
            # Той самий хід, названий двома способами (поле `свідомо` і «відхилено»
            # над знахідкою тієї ж речі), — один рядок, а не два: жінка читає їх.
            ключ = (з.get("річ", ""), з["текст"])
            if ключ in _бач:
                continue
            _бач.add(ключ)
            _свід.append(з)
        if _свід:
            зап["свідомі"] = _свід
        if о.get("чекліст"):
            зап["чекліст"] = о["чекліст"]
        зап["вузол"] = (dict(назва=str(о["вузол"]), чому=str(о.get("рядок_вузла") or ""))
                        if о.get("вузол") else None)
        обр.append(зап)
    вітрина, ноти = _вітрина_ремонту(образи, кандидати)
    м = _мова_вердикту(мова)
    вимоги = (list(ВИМОГИ_ВЕРДИКТУ) + ноти + ([_ВИМОГА_МОВИ] if (м and м["порушення"]) else [])
              + (вик["вимоги"] if вик else []))
    в = {"версія": _ПР.ВЕРСІЯ, "ітерація": 2 if _іт >= 2 else 1}
    if випадок:
        в["випадок"] = str(випадок)
    в["образи"] = обр
    # НАБІР РАХУЄТЬСЯ ПО ЗАПИСАХ, А НЕ ПО `обр`: риси образу (колірна схема, літера,
    # герой) лежать у записі `bridge._вердикти_образів`, а в рядку схеми їх нема —
    # у схему їде вже ВИРОК над набором, не його вхід.
    набір = різноманітність(образи) or {}
    # ОГОЛОШЕНА ВІДМОВА НАД ЗНАХІДКОЮ НАБОРУ ПОСЛАБЛЮЄ ЇЇ ТУТ — тим самим множником
    # і на тій самій копії, що й у знахідках образу вище: ші, яка сказала «лишаю ці
    # два образи схожими, бо …», уже зробила хід, і повна сила після нього — це
    # друге покарання за той самий вибір.
    _пос_наб = (вик or {}).get("послаблення_набору") or {}
    if _пос_наб and набір.get("знахідки"):
        набір["знахідки"] = [
            (dict(z, сила_нп=round(float(z.get("сила_нп") or 0) * СВІДОМИЙ_МНОЖНИК, 2),
                  свідомий=True)
             if (str(z.get("ід") or "") in _пос_наб and not z.get("свідомий")) else z)
            for z in набір["знахідки"]]
    _коорд = координація_набору(образи)
    if _коорд:
        набір["координація"] = _коорд
    if вик and вик["невиконано"]:
        набір["невиконано"] = вик["невиконано"]
    if набір:
        в["набір"] = набір
    if вітрина:
        в["вітрина"] = вітрина
    if м:
        в["мова"] = м
    р = _реєстр_вердикту(реєстри)
    if р:
        в["реєстр"] = р
    # ФОРМУ ВІДПОВІДІ ВИДНО З ВЕРДИКТА — скелет з тієї самої схеми, якою відповідь
    # потім перевіряють (те саме рішення, що в `пакет_для_моделі`).
    _відповідь = "ОБРАЗИ_V1"
    в["завдання"] = {"образів": int(варіантів or 1), "відповідь": _відповідь,
                     "схема_відповіді": скелет_схеми(_ПР.СХЕМИ[_відповідь]),
                     "вимоги": вимоги}
    return в


def _шапка_вибору(образи, випадок=None, скільки_свідомих=2, кандидати=None):
    р = ["Код перевірив твої допрацьовані образи. Ось результат."]
    if випадок:
        р.append("ВИПАДОК: %s" % випадок)
    _ном = номери_речей(кандидати)[0] if (кандидати and ПАКУВАТИ_ІНДЕКСОМ) else None
    for i, о in enumerate(образи or [], 1):
        р.append("")
        р.append("── образ %d%s: %s" % (i, (" · %s" % о["підпис"]) if о.get("підпис") else "",
                                        образ_рядком(о, кандидати, _ном)))
        for с in (о.get("свідомі") or [])[:скільки_свідомих]:
            # запис образу несе оголошення обʼєктом (`bridge._вердикти_образів`);
            # рядок лишається робочим входом — прозовий стенд кладе сюди рядки
            р.append("    СВІДОМО (твій оголошений хід): %s"
                     % (с.get("текст") if isinstance(с, dict) else с))
        for б in (о.get("блокує") or [])[:4]:
            р.append("    БЛОКУЄ: %s" % (б if isinstance(б, str) else б.get("суть", б)))
        for з in (о.get("знахідки") or [])[:5]:
            р.append("    · %s%s" % ((з.get("суть") or ""),
                                     " ← оголошений хід" if з.get("свідомий") else ""))
    return р


def промпт_вибору(образи, випадок=None, без_фото=True):
    """Третій виклик СТЕНДА: один образ і опис для людини одним викликом.

    Лишається як було — його читає шаблон стенда, якого ця правка не торкалась.
    Показ ходить не ним: з Т-06 виклик 3 — це `ВЕРДИКТ_V1` із `завдання.відповідь=
    "ВИБІР_V1"` (`вердикт_вибору`), виклик 4 — `ОПИС_V1` (`опис_v1`)."""
    р = _шапка_вибору(образи, випадок)
    р += [
        "",
        "Обери ОДИН образ — той, за який ти ручаєшся перед цією жінкою. Не той, до "
        "якого менше зауважень: той, який ти вважаєш найкращим для неї й цього випадку.",
        "Далі опиши його для неї:",
        # ПРОЗА — ДЛЯ ЛЮДИНИ, НЕ ДЛЯ МАШИНИ. Тут стояло «колір + hex», і модель
        # слухняно писала «графіт #4a4a4a», а поруч у рядку речі — повний id із
        # доменом магазину. Тестувальниця судить, чи вона це вдягне: адреси в
        # каталозі й шістнадцяткові коди їй не потрібні й читаються як збій.
        # Машинний хвіст лишається — але рівно один рядок, в кінці.
        "1. Речі — по рядку на кожну: що це, крій, довжина, колір словами, тканина.",
        "2. Взуття, верхній шар, аксесуари.",
        "3. Чому це працює — 3–4 речення.",
        "Останнім рядком — «ОБРАЗ: id, id, …».",
        "Не називай чисел світлоти, типів фігури й не згадуй, що мав обмеження. Українською.",
        "У самому описі НЕ пиши id речей і НЕ пиши hex-коди — лише людські слова. "
        "Id потрібні тільки в останньому рядку «ОБРАЗ:».",
        "Якщо в образі є щось нестандартне — як саме це носити, окремим рядком "
        "«СВІДОМО: <що> — <чому>». Цей рядок жінка побачить як пораду.",
    ]
    return "\n".join(р)


# ── `промпт_лише_вибору` І `промпт_опису` ЗНЕСЕНО (Т-06, 12.09.2026) ──────────
# Третій і четвертий виклики говорили прозою, і кожен мав ВЛАСНИЙ опис того, що
# код уже сказав обʼєктом. Вибір перераховував образи рядками `_шапка_вибору`
# («── образ 3 · підпис: слот #12·03 назва»), хоч той самий вердикт ітерації 2
# стояв поруч обʼєктом `ВЕРДИКТ_V1`; опис просив «останнім рядком ОБРАЗ: id», а
# потім «ФОТО НЕ ТЕ: N» — два машинні рядки, які показ вирізав із прози
# регулярками.
# ЦІНА БУЛА НЕ ОХАЙНІСТЬ, А ДВА ТИХИХ РОЗХОДЖЕННЯ. Перше: нумерація фото жила в
# ДВОХ місцях — промпт рахував її словами («· фото 3–4 — сукня …»), а показ
# окремим списком `номерДоІд`, і будь-яка розбіжність вішала позначку «фото не
# те» на ЧУЖУ річ. Друге: правило «вибір приймається лише з ≥2 речами й без
# структурного блокера» стояло в JS регуляркою по словах рядка `блокує`
# (`/по одній на слот|подвоєн|…/`) — тобто найважливіше рішення петлі приймалось
# звіркою тексту, а не полем, і код, який той текст друкує, про неї не знав.
# ТЕПЕР: виклик 3 дістає ТОЙ САМИЙ `ВЕРДИКТ_V1` із `завдання.відповідь="ВИБІР_V1"`
# (`вердикт_вибору`), виклик 4 — `ОПИС_V1` (`опис_v1`), а відповіді читаються
# полями (`вибір_з_json`, `опис_відповідь_з_json`). `_шапка_вибору` лишається
# живою рівно для `промпт_вибору` — одноколісного виклику стенда, якого Т-06 не
# торкається.

# ВИМОГИ ВИБОРУ — те саме рішення, що `ВИМОГИ_ПАКЕТА` і `ВИМОГИ_ВЕРДИКТУ`:
# інструкція лишається текстом, але не прозою, у якій тонуть дані. Формату
# відповіді тут не описує жоден рядок — його називає `завдання.відповідь` і
# скелет зі схеми.
ВИМОГИ_ВИБОРУ = (
    "Це той самий вердикт, що й доти: ті самі образи, «структура», «знахідки». "
    "Допрацьовувати більше нема чого — лишилось обрати ОДИН.",
    "Обери той, за який ти ручаєшся перед цією жінкою. Не той, до якого менше "
    "зауважень: той, який ти вважаєш найкращим для неї й цього випадку.",
    # АДРЕСА ВИБОРУ — ІД ОБРАЗУ, А НЕ ПЕРЕЛІК РЕЧЕЙ. Доти модель копіювала склад
    # рядком, і кожна копія була новою нагодою втратити річ або перейменувати її.
    "«обрано» — це «ід» образу з цього вердикту («о1», «о2», …), не номер речі. "
    "Склад копіювати не треба: код знає, з чого складається кожен образ.",
    "Образ із непорожньою «структура.блокери» не обирай, якщо є хоч один без неї: "
    "код такий вибір не приймає й візьме інший образ замість твого.",
    "Єдина дозволена правка складу — «прибрати»: коли блокер каже, що в одному "
    "слоті дві речі, назви в «прибрати» номер тієї, що гірша для образу.",
    "Опис не пиши — його попросять окремо, коли ти побачиш фото речей.",
    "Відповідь — ЛИШЕ один JSON-обʼєкт за «завдання.схема_відповіді», без "
    "пояснень і без ```.",
)


def вердикт_вибору(вердикт):
    """ТОЙ САМИЙ `ВЕРДИКТ_V1`, але завдання — обрати один образ (Т-06, крок 1).

    ЧОМУ КОПІЯ ОБʼЄКТА, А НЕ ДРУГИЙ ПОБУДОВНИК. Вибір судиться проти того, що код
    САМ сказав моделі: `обрано` звіряється з `образи[].ід` цього ж обʼєкта, а
    «≥2 речі й без структурного блокера» — з `образи[].речі` і `образи[].структура`
    (`вибір_з_json`). Другий побудовник дав би другий набір образів, у якому «о3»
    могло б означати інший образ, ніж у промпті, — і вибір приймався б не над тим,
    що бачила модель.
    `образів: 1` — відповідь на «скільки образів назвати», не обмеження складу.
    """
    в = dict(вердикт or {})
    в["завдання"] = {"образів": 1, "відповідь": "ВИБІР_V1",
                     "схема_відповіді": скелет_схеми(_ПР.СХЕМИ["ВИБІР_V1"]),
                     "вимоги": list(ВИМОГИ_ВИБОРУ)}
    return в


def _образ_вердикту(вердикт, ід):
    """Образ вердикту за його `ід`, або None. Порівняння рядками: «о1» від моделі
    приходить рядком, а в обʼєкті стоїть рядком же — числа тут не буває."""
    for о in ((вердикт or {}).get("образи") or []):
        if isinstance(о, dict) and str(о.get("ід") or "") == str(ід or ""):
            return о
    return None


def _слоти_складу(ід, словник):
    """слот → id-и цього слота в складі. Слот бере зі словника речей (каталог/пул)."""
    сл = {}
    for і in ід:
        сл.setdefault((словник.get(і) or {}).get("слот"), []).append(і)
    return сл


def _склад_вибору(о, словник, за_ном, прибрати=()):
    """Образ вердикту + «прибрати» → склад id-ами й причина, чому він не годиться.

    ЧОМУ СКЛАД РАХУЄТЬСЯ ТУТ, А НЕ БЕРЕТЬСЯ ГОТОВИМ. У вердикті речі стоять
    номерами «#12·03» — тим самим письмом, яким їх бачила модель; id каталогу в
    вердикт не їдуть навмисно (§1: модель id не говорить). Нумерація та сама, бо
    пул той самий: `_за_номером` рахує її над `кандидати` ЦЬОГО прогону, як і
    розбір образів (`образи_з_json`).

    ПРИБРАТИ — ЛИШЕ ДУБЛІКАТ У СЛОТІ (Т-06, крок 1). Образ уже судився в цьому
    складі; річ, знята поза дублем, лишила б вердикт, порахований не над тим, що
    піде жінці. Тому кожна заявка або зараховується, або називається в
    `знехтувано` — мовчки не зникає жодна.
    """
    знайдені, невірні, частини = [], [], {}
    for x in (о.get("речі") or []):
        з, н, ч = _розпізнати_речі(str(x), словник, за_ном)
        знайдені += [і for і in з if і not in знайдені]
        невірні += н
        частини.update(ч)
    запис = _запис_образу(знайдені, невірні, словник, "поле «речі» вердикту", частини)
    ід = list(запис["ід"])
    прибрано, знехтувано = [], []
    for x in (прибрати or []):
        з, _н, _ч = _розпізнати_речі(str(x), словник, за_ном)
        цілі = [і for і in з if і in ід]
        if not цілі:
            знехтувано.append(dict(річ=str(x), чому="такої речі в обраному образі немає"))
            continue
        for і in цілі:
            свій = _слоти_складу(ід, словник).get((словник.get(і) or {}).get("слот")) or []
            if len(свій) > 1:
                ід.remove(і)
                прибрано.append(str(x))
            else:
                знехтувано.append(dict(річ=str(x), чому="у своєму слоті вона одна, "
                                                        "а прибирати дозволено лише другу річ у слоті"))
    # ГЕЙТ ВИБОРУ: дві речі — означення образу (`перевірити_від_моделі` відкидає
    # одну річ тим самим числом), структурний блокер — вердикт коду над ЦИМ
    # образом. `слот_двічі` знімається прибиранням, решта кодів — ні: «нема верху
    # й низу» і «вето» прибиранням речі не лікуються.
    лишок = {с: v for с, v in _слоти_складу(ід, словник).items() if len(v) > 1}
    блокери = [б for б in (((о.get("структура") or {}).get("блокери")) or [])
               if isinstance(б, dict) and (б.get("код") != "слот_двічі" or лишок)]
    чому_ні = None
    if len(ід) < 2:
        чому_ні = ("у складі %d річ — образ починається з двох" % len(ід)) if ід else \
                  "жодної речі вердикту не вийшло розпізнати"
    elif блокери:
        чому_ні = "структурний блокер лишився: %s" % "; ".join(
            str(б.get("суть") or б.get("код"))[:80] for б in блокери[:2])
    return dict(ід=ід, частини=частини, прибрано=прибрано, знехтувано=знехтувано,
                чому_ні=чому_ні, невірні_пари=list(запис["невірні_пари"]))


# ОБРАЗ ІЗ БЛОКЕРОМ АБО НЕПОЛАГОДЖЕНИМ ГЕЙТОМ ОБРАТИ НЕ МОЖНА (16.09.2026). Доти
# вибір спинявся лише на структурному блокері, а знахідка-гейт (джинси під
# заявлений код, річ поза дугою схеми) лишалась реплікою в журналі.
# ПІДНЯТО З ТІЛА `вибір_з_json` (18.09.2026): те саме питання ставить `повнота_набору`,
# і другий такий вираз розійшовся б із цим на першій же правці.
def _чому_не_можна(к, прибирали=False):
    """Чому цей образ вердикта не можна показати, або None."""
    ст = (к or {}).get("структура") or {}
    # «прибрати» знімає другу річ у слоті разом із блокером «слот_двічі» (Т-06);
    # решта блокерів (нема взуття, неповний, нема верху/низу) полем не лікуються.
    _бл = [b for b in (ст.get("блокери") or [])
           if not (прибирали and (b or {}).get("код") == "слот_двічі")]
    if ст.get("ок") is False and _бл:
        return "структурний блокер: " + "; ".join(
            str((b or {}).get("суть") or (b or {}).get("код") or "") for b in _бл[:2])
    г = [z for z in ((к or {}).get("знахідки") or [])
         if isinstance(z, dict) and z.get("регістр") == "гейт" and not z.get("свідомий")]
    if г:
        return "гейти не полагоджено: " + "; ".join(
            "%s %s" % (z.get("правило"), str(z.get("суть") or "")[:70]) for z in г[:2])
    return None


# ── ДОБІР КОДОМ — ОСТАННІЙ ЯРУС РЕМОНТУ ПОВНОТИ ─────────────────────────────
# РІШЕННЯ ВЛАСНИКА 19.09.2026, І ВОНО РОЗШИРЮЄ ПРАВИЛО «КОД ОБРАЗІВ НЕ ЗБИРАЄ».
# Те правило чинне й лишається чинним — воно про СКЛАДАННЯ образу: власний
# перебір композитора знесено 31.08 навмисно, щоб образи вигадувала ші, а не
# код. Тут інше питання. Образ уже складений ші; у ньому структурна ДІРА —
# слот, без якого код сам його не покаже (нема взуття, нема сумки, нема третьої
# речі). Дві спроби моделі вже витрачені (`спроб_повноти`). Далі вибір лише
# такий: або код закриває діру річчю з ТОГО САМОГО пулу, який ші й бачила, або
# жінці йде картка, яку код не приймає. Власник: «якщо відомо, який слот пустий,
# і є кандидат, — модель і код мусять зробити ремонт як треба».
# НАСТУПНІЙ СЕСІЇ: не «лагодь» це назад у «код образів не збирає». Складання
# лишилось за ші; це латка в уже складеному, і вона НАЗВАНА — річ несе
# `додав_код`, жінка читає про це словами на картці, журнал має власну колонку.
_ЧОГО_БРАКУЄ_СЛОВОМ = {
    "сумка": "сумку", "взуття": "взуття", "верхній_шар": "верхній шар",
    "прикраси": "прикрасу", "сережки": "сережки", "кольє": "кольє",
    "намисто": "намисто", "браслет": "браслет", "каблучка": "каблучку",
    "брошка": "брошку", "пояс": "пояс", "шарф": "шарф",
    "головний_убір": "головний убір", "сукня": "сукню", "комплект": "комплект",
    "верх": "верх", "низ": "низ",
}
# Те саме для рядка ПРО КАТАЛОГ (ярус 3): там річ стоїть у родовому й з «жодної».
_НЕМА_В_КАТАЛОЗІ_СЛОВОМ = {
    "нема_сумки": "жодної сумки",
    "нема_взуття": "жодної пари взуття",
    "нема_верху_низу": "основи образу: ні сукні, ні комплекту, ні окремих верху й низу",
    "неповний": "жодної третьої речі — ні шарфа, ні пояса, ні прикраси, ні верхнього шару",
}


def _дібрати_кодом(ід, частини, кандидати, словник, сценарій=None):
    """Закрити структурну діру складеного образу річчю з ТОГО САМОГО пулу.
    → `(ід із дібраним, [{id, слот, чому}], чому_ні)`.

    ПОРЯДОК КАНДИДАТІВ НЕ ПЕРЕВИЗНАЧАЄТЬСЯ. Пул слота вже впорядкований
    композитором: ключ сорту — колірна відстань до центру вікна, а речі запасної
    хвилі (`_доповнено`, у пакеті — `у_дузі: false`) дістають +100, тобто стоять
    після ядра. Це рівно той порядок, у якому пул бачить ші. Другий сорт тут
    означав би, що код і модель звуть «найкращим» різні речі.

    ПРИЙМАЄТЬСЯ ЛИШЕ ПОВНЕ ЗАКРИТТЯ. Образ, у який код доклав річ і все одно не
    прийняв, бреше двічі: жінці — рядком «дібрав код», і собі — «полагоджено».
    Тому при невдачі відкат повний, а `чому_ні` називає, на чому стало.
    """
    import реєстр_правил as _РЕЄСТР
    слоти_пулу = {}
    for сл, пул in (кандидати or {}).items():
        for r in пул:
            слоти_пулу.setdefault(str(r.get("id")), set()).add(сл)

    def _речі(іди):
        вих = []
        for і in іди:
            з = словник.get(і) or {}
            r = dict(з, id=і, слот=(з.get("слот") or "?"))
            ч = (частини or {}).get(і)
            if ч and r.get("слот") == "комплект":
                r["слот"] = ч
                r["частина_комплекту"] = ч
            вих.append(r)
        return вих

    ід, дібрані, чому_ні = list(ід), [], None
    # Кроків — по одному на сімʼю блокера повноти плюс запас: більше дір, ніж
    # родин, у образі не буває, а нескінченного циклу тут бути не мусить.
    for _ in range(len(СЛОТИ_БЛОКЕРА) + 1):
        б = структура_образу(_речі(ід), слоти_пулу, сценарій)
        if not б:
            break
        коди = [_код_блокера(x) for x in б]
        ціль = next((к for к in коди if к in СЛОТИ_БЛОКЕРА), None)
        if ціль is None:
            # «два взуття» — це не діра, це інший образ; доклавши річ, її не
            # закрити, і вдавати протилежне код не буде («нема верху й низу»
            # тут більше не буває — вона своя ціль, СЛОТИ_БЛОКЕРА нижче).
            чому_ні = "блокер, якого річчю не закрити: %s" % str(б[0])[:80]
            break
        взято = None
        for слот in СЛОТИ_БЛОКЕРА[ціль]:
            for r in (кандидати.get(слот) or [])[:_РЕЄСТР.C["добір_кандидатів"]]:
                і = r.get("id")
                if not і or і in ід:
                    continue
                словник.setdefault(і, dict(r, слот=(r.get("слот") or слот)))
                нові = структура_образу(_речі(ід + [і]), слоти_пулу, сценарій)
                # МЕНШЕ БЛОКЕРІВ І ЖОДНОГО НОВОГО: річ, що закриває «нема сумки»
                # й відкриває «у слоті «сумка» 2 речі», — не ремонт, а обмін.
                if len(нові) < len(б) and not (
                        {_код_блокера(x) for x in нові} - set(коди)):
                    взято = (і, слот)
                    break
            if взято:
                break
        # ── ОСНОВА БЕЗ ЖОДНОЇ ПОЛОВИНИ — ЄДИНИЙ ВИНЯТОК ІЗ «ОДНА РІЧ ЗА КРОК» ──
        # (рядок 46 дошки, власник 19.09). Коли бракує і верху, і низу РАЗОМ,
        # жоден одинокий кандидат не закриває блокер: рядок лишається тим самим
        # кодом («нема «низ» (і нема сукні…)» замість «нема «верх» і «низ»…»),
        # тобто лічба блокерів НЕ падає, і цикл вище відкидає кожного одинокого
        # кандидата як «нічого не змінив». Це не стосується часткової відсутності
        # (лишень верх або лишень низ) — там одна річ закриває блокер сама, і
        # генеральний цикл вище вже це знаходить. Тут — єдине місце в добірці, де
        # крок додає дві речі одразу, бо нарізно жодна ремонту не завершує.
        if взято is None and ціль == "нема_верху_низу":
            _в = next((r for r in (кандидати.get("верх") or [])[:_РЕЄСТР.C["добір_кандидатів"]]
                       if r.get("id") and r.get("id") not in ід), None)
            _н = next((r for r in (кандидати.get("низ") or [])[:_РЕЄСТР.C["добір_кандидатів"]]
                       if r.get("id") and r.get("id") not in ід), None)
            if _в and _н:
                словник.setdefault(_в["id"], dict(_в, слот=(_в.get("слот") or "верх")))
                словник.setdefault(_н["id"], dict(_н, слот=(_н.get("слот") or "низ")))
                нові = структура_образу(_речі(ід + [_в["id"], _н["id"]]), слоти_пулу, сценарій)
                if len(нові) < len(б) and not (
                        {_код_блокера(x) for x in нові} - set(коди)):
                    ід += [_в["id"], _н["id"]]
                    дібрані += [dict(id=_в["id"], слот="верх", чому=_ЧОМУ_БЛОКЕРА[ціль],
                                    напис="цю річ дібрав код, а не ші"),
                                dict(id=_н["id"], слот="низ", чому=_ЧОМУ_БЛОКЕРА[ціль],
                                    напис="цю річ дібрав код, а не ші")]
                    continue
        if взято is None:
            чому_ні = "нема_кандидата:%s" % ціль
            break
        і, слот = взято
        ід.append(і)
        дібрані.append(dict(id=і, слот=слот, чому=_ЧОМУ_БЛОКЕРА[ціль],
                            напис="цю річ дібрав код, а не ші"))
    else:
        чому_ні = "структура не закрилась за %d кроків" % (len(СЛОТИ_БЛОКЕРА) + 1)
    if чому_ні or not дібрані or структура_образу(_речі(ід), слоти_пулу, сценарій):
        return list(ід[:len(ід) - len(дібрані)]), [], (чому_ні or "нема чого добирати")
    return ід, дібрані, None


def повнота_набору(вердикт, кандидати=None, каталог=None, сценарій=None,
                   дібрати=False, запасний=None):
    """Що з цього вердикта піде жінці на картку — рішення КОДУ, а не показу.

    → `{ід, частини, номери, образ, повний, рядок, чому, дібрані, рядок_добору}`.
    `повний=True` — образ можна показати (`_чому_не_можна` мовчить). `повний=False`
    — усіх відкинуто, і тоді береться НАЙПОВНІШИЙ (найменше блокерів, найбільше
    речей), а `рядок` каже жінці словами коду, чого в ньому бракує.

    `дібрати=True` — ОСТАННІЙ ЯРУС РЕМОНТУ (рішення власника 19.09.2026): обидві
    спроби моделі витрачені, і структурну діру закриває код (`_дібрати_кодом`).
    Тоді `ід` несе дібрану річ, `дібрані` — її разом зі слотом і причиною, а
    `рядок_добору` — те саме людськими словами для картки. `рядок` (чесний рядок
    про неповноту) лишається ЛИШЕ там, де він правдивий: у пулі під цей слот
    кандидата нема, і тоді він каже про КАТАЛОГ, а не про показ.

    `запасний` — вердикт, над яким рахувати повноту, коли в цьому не склався
    ЖОДЕН образ (остання спроба ремонту не розібралась). Без нього ремонт мав
    третій спосіб не завершитись: відповідь-сміття лишала показ на попередньому
    вердикті, порахованому БЕЗ добору.

    ЧОМУ ЦЕ ІСНУЄ (18.09.2026, спіймано власницею на опублікованому продукті).
    Коли крок вибору не давав образу, показ мовчки брав `в.речі` — верхній рівень
    вердикта, тобто ОСТАННІЙ образ відповіді, чиї блокери там нічого не спиняють.
    Так на картку їхала сукня з туфлями й підвіскою без сумки, і жінка не бачила
    жодного слова про те, що образ неповний. Тепер вибір тут: показати можна лише
    те, що код назвав, а вимушений показ називається вголос.

    ЧОМУ НЕ «НЕ ПОКАЗУВАТИ НІЧОГО». Порожня картка не каже жінці нічого й нічого не
    дає судити; названий неповний образ дає і те, і те. Межу ставить власник, не код.
    """
    словник = _словник_речей(кандидати, каталог)
    за_ном = _за_номером(кандидати)
    найкращий = None
    for к in ((вердикт or {}).get("образи") or []):
        if not isinstance(к, dict):
            continue
        с = _склад_вибору(к, словник, за_ном)
        # `_склад_вибору.чому_ні` тут НЕ гейт: він змішує «речі не розпізнались» із
        # «структурний блокер лишився», а другого ми саме й чекаємо. Гейт — тільки
        # означення образу (дві речі), вирок про блокери дає `_чому_не_можна`.
        if len(с["ід"]) < 2:
            continue
        чому = _чому_не_можна(к)
        бл = [b for b in ((к.get("структура") or {}).get("блокери") or []) if (b or {}).get("код")]
        # КЛЮЧ ПОРЯДКУ: спершу той, якого код приймає; далі — найменше блокерів,
        # найбільше речей. «Найповніший» саме в цьому порядку, а не за лічбою речей:
        # образ на шість речей із двома взуттями повніший лише на вигляд.
        ключ = (1 if чому else 0, len(бл), -len(с["ід"]))
        if найкращий is None or ключ < найкращий[0]:
            найкращий = (ключ, к, с, бл, чому)
    if найкращий is None:
        # ВІДПОВІДЬ, З ЯКОЇ НЕ ВИЙШЛО ЖОДНОГО ОБРАЗУ, — ТЕЖ ВИТРАЧЕНА СПРОБА.
        # Попередній вердикт нікуди не подівся, і саме він піде на картку; тож
        # ремонт завершується НАД НИМ, а не мовчки лишається незавершеним.
        if запасний:
            зап = повнота_набору(запасний, кандидати=кандидати, каталог=каталог,
                                 сценарій=сценарій, дібрати=дібрати)
            if зап.get("ід"):
                зап["з_попереднього"] = True
                return зап
        return dict(ід=[], частини={}, номери={}, образ=None, повний=False, рядок=None,
                    чому="жоден образ вердикта не склався з пулу",
                    дібрані=[], рядок_добору=None)
    _, к, с, бл, чому = найкращий
    ном = номери_речей(кандидати)[0] if кандидати else {}
    рядок, дібрані, рядок_добору, добір_ні = None, [], None, None
    if чому and дібрати and кандидати:
        # ЯРУС 3 РЕМОНТУ: модель двічі не доповнила — закриває код.
        ід2, дібрані, добір_ні = _дібрати_кодом(с["ід"], с.get("частини"), кандидати,
                                                словник, сценарій)
        if дібрані:
            с = dict(с, ід=ід2)
            бл = []
            # Структура закрита (`_дібрати_кодом` приймає лише повне закриття),
            # але ГЕЙТИ правил річчю не лікуються — питаємо про них ще раз тим
            # самим суддею, а не оголошуємо образ прийнятим.
            чому = _чому_не_можна(dict(к, структура=dict(ок=True, блокери=[])))
            фраза = " і ".join(_ЧОГО_БРАКУЄ_СЛОВОМ.get(d["слот"], str(d["слот"]).replace("_", " "))
                               for d in дібрані)
            рядок_добору = ("%s%s до цього образу дібрав код, а не ші. Ші лишила %s, "
                            "а без %s образ не готовий."
                            % (фраза[:1].upper(), фраза[1:],
                               "це місце порожнім" if len(дібрані) == 1 else "ці місця порожніми",
                               "нього" if len(дібрані) == 1 else "них"))
    if чому:
        # ЖІНЦІ — ЛИШЕ ТЕ, ЧОГО БРАКУЄ, І ЛИШЕ ЛЮДСЬКИМИ СЛОВАМИ. Структурний блокер
        # каже «нема сумки» — це її мова й це дія. Гейт правила каже «K-PAL-03 схема
        # «тональна»: слот «сережки» тримає тон 160–184°» — це мова коду, і продукт
        # сам собі її забороняє (`ВИМОГИ_ОПИСУ`: без id, кодів і чисел). Тому на
        # картку йде лише перше; друге лишається в `чому` — для журналу й діагнозу,
        # які читає власник.
        суті = [str((b or {}).get("суть") or "") for b in бл]
        рядок = ("Образ неповний: " + "; ".join(x for x in суті if x)) if суті else None
        # ── ЯРУС 3: ЧЕСНИЙ РЯДОК ЛИШАЄТЬСЯ ЛИШЕ ТАМ, ДЕ ВІН ПРАВДИВИЙ ─────────
        # Коли добір спинився на «нема кандидата», це вже не звіт про показ, а
        # звіт про КАТАЛОГ: під цей випадок сумки в ньому немає. Жінка мусить
        # читати саме це — інакше вона судить систему за брак, якого в системі
        # нема, і чекає полагодження там, де лагодити нема чого.
        if str(добір_ні or "").startswith("нема_кандидата:"):
            _чого = _НЕМА_В_КАТАЛОЗІ_СЛОВОМ.get(добір_ні.split(":", 1)[1])
            if _чого:
                рядок = ("У каталозі під цей випадок немає %s — тому образ лишається "
                         "неповним. Це брак каталогу, а не показу." % _чого)
    # ── ОСНОВИ НЕМА Й ПУЛ ЇЇ НЕ ДАЄ — НЕ АКСЕСУАРИ НА КАРТЦІ (рядок 46, 19.09) ──
    # Відсутня сумка чи третя річ лишає впізнаваний образ: сукня, туфлі й
    # прикраса без сумки — це образ, якому чогось бракує, і чесний рядок над
    # ним чесний. Відсутня ОСНОВА (сукня чи верх+низ) — це інший випадок:
    # `структура_образу` сама каже про такий набір «це аксесуари, а не образ».
    # Коли модель не впоралась і пул основи дати не може, картку показувати
    # нема чого — той самий контракт «немає образу», що вище (`найкращий is
    # None`): `ід` порожній, рядок лишається єдиним, що бачить жінка.
    if добір_ні == "нема_кандидата:нема_верху_низу":
        return dict(ід=[], частини={}, номери={}, образ=None, повний=False,
                    рядок=рядок, чому=чому, дібрані=[], рядок_добору=None,
                    добір_ні=добір_ні)
    return dict(ід=с["ід"], частини=с["частини"],
                номери={і: "#%d·%s" % ном[і] for і in с["ід"] if і in ном},
                образ=str(к.get("ід") or "") or None, повний=not чому,
                рядок=рядок, чому=чому,
                # ── ПОЗНАЧКА ЇДЕ ДАЛІ (рішення власника 19.09.2026) ──────────
                # Дібране кодом не має права злитись із вибором ші: експеримент
                # чотирьох рук міряє саме вибір ші. Тому річ несе `додав_код` у
                # складі образу, рядок — на картці, і журнал має власну колонку.
                дібрані=дібрані, рядок_добору=рядок_добору,
                добір_ні=(добір_ні if чому else None))


# ВИМОГИ РЕМОНТУ ПОВНОТИ — той самий вид, що `ВИМОГИ_ВЕРДИКТУ`: короткі рядки,
# кожен проти названого провалу. Це ОДИН зайвий виклик на руку, і він просить
# рівно одне: доповнити образ до повного речами вітрини.
ВИМОГИ_ПОВНОТИ = (
    "ЖОДЕН із цих образів показати не можна: кожному бракує речі, без якої образ не "
    "готовий. Чого саме бракує — у «структура.блокери» кожного образу.",
    "Візьми ОДИН свій образ — той, який вважаєш найкращим, — і доповни його до повного "
    "речами з «вітрина»: слоти, яких бракує, стоять там першими.",
    "Нічого іншого не міняй: ті самі речі, той самий задум, лише ДОДАЙ те, чого бракує. "
    "По одній речі на слот.",
    "Дай РІВНО ОДИН образ. Відповідь — ЛИШЕ один JSON-обʼєкт за «завдання.схема_відповіді», "
    "без пояснень і без ```.",
)

# ── ДРУГА СПРОБА — АДРЕСНА (19.09.2026, рішення власника) ───────────────────
# ЩО ЦЕ МІНЯЄ В РІШЕННІ. Спроба була ОДНА, і після неї ремонт мав право не
# завершитись: образ лишався неповним, а жінка діставала картку з чесним рядком.
# Власник: «якщо відомо, який слот пустий, і є кандидат — чого тоді ремонт не
# доходить до кінця?». Друга спроба не повторює першу іншими словами: вона каже
# ші, ЩО САМЕ вона щойно повернула, якого слота в тому не було і які конкретні
# речі вітрини його закривають. Загальне прохання вона вже чула — і не виконала.
ВИМОГИ_ПОВНОТИ_2 = (
    "ДРУГА І ОСТАННЯ СПРОБА. Ти вже відповідала на це саме прохання, і код прочитав твою "
    "відповідь: образу ВСЕ ЩЕ бракує речі. Нижче, у «бракує», названо все — який слот "
    "порожній, що ти повернула без нього і які саме речі вітрини його закривають.",
    "Поверни ТОЙ САМИЙ образ і ДОДАЙ до нього по одній речі на кожен названий слот. "
    "Нічого не прибирай, нічого не заміняй, задум не міняй.",
    "Номер речі пиши так, як він стоїть у «вітрина» («#412·07»), — інакше код речі не впізнає "
    "й вважатиме, що слот так і лишився порожнім.",
    "Дай РІВНО ОДИН образ. Відповідь — ЛИШЕ один JSON-обʼєкт за «завдання.схема_відповіді», "
    "без пояснень і без ```.",
)


def _бракує_адресно(образи, потрібні, вітрина, чому):
    """Рядки «о1 — ти повернула …, слота «сумка» в цьому нема; закривають: …».

    ОДИН РЯДОК НА ОБРАЗ І ТРИ РЕЧІ НА СЛОТ: уся вітрина вже стоїть у промпті
    полем, і переказувати її вдруге означало б платити за неї двічі. Три —
    щоб «закривають» лишалось прикладом, а не новим вибором.
    """
    за_образом = {}
    for слот, іди in (потрібні or {}).items():
        for ід in іди:
            за_образом.setdefault(str(ід), []).append(слот)
    рядки = []
    for о in образи:
        ід = str(о.get("ід") or "")
        слоти = за_образом.get(ід) or []
        if not слоти:
            continue
        речі = ", ".join(str(x) for x in (о.get("речі") or [])[:8]) or "—"
        закр = "; ".join(
            "«%s» закривають %s" % (с, ", ".join(
                "%s %s" % (r.get("н"), r.get("назва")) for r in ((вітрина.get(с) or [])[:3])))
            for с in слоти if (вітрина.get(с) or []))
        рядки.append("%s — ти повернула %s, і цього мало: %s. %s"
                     % (ід, речі, " / ".join(чому.get(ід) or слоти),
                        закр or "у вітрині цього слота нема"))
    return рядки


def вердикт_повноти(вердикт, спроба=1):
    """Той самий вердикт ітерації 2, звужений до одного завдання: доповнити до повного.

    `спроба` — котрий це виклик ремонту повноти на цю руку (1 або 2). Друга несе
    `ВИМОГИ_ПОВНОТИ_2` і адресний перелік `бракує`: перше прохання ші вже чула.

    None, коли доповнювати нема чого (усі образи повні) або нема чим (вітрина не
    несе жодного слота, якого бракує) — тоді й зайвого виклику до моделі нема.
    """
    в = dict(вердикт or {})
    образи = [о for о in (в.get("образи") or [])
              if isinstance(о, dict) and any(
                  str((b or {}).get("код") or "") in СЛОТИ_БЛОКЕРА
                  for b in ((о.get("структура") or {}).get("блокери") or []))]
    вітрина = в.get("вітрина") or {}
    if not образи or not вітрина:
        return None
    потрібні, чому = _слоти_повноти(образи, вітрина)
    if not потрібні:
        return None
    # ОБРАЗ ТУТ — САМА СТРУКТУРА: знахідки, чекліст і вузол напруги до питання
    # «чого бракує» стосунку не мають, а важать більшу частину промпта ремонту.
    в["образи"] = [{k: v for k, v in о.items() if k in ("ід", "підпис", "речі", "структура")}
                   for о in образи]
    for ключ in ("набір", "мова", "реєстр"):
        в.pop(ключ, None)
    # ВІТРИНА ЗВУЖУЄТЬСЯ ДО СЛОТІВ ПОВНОТИ: вузли напруги тут не питання, а зайвий
    # виклик має бути найдешевшим із тих, що працюють.
    в["вітрина"] = {с: р for с, р in вітрина.items() if с in потрібні}
    завдання = dict(в.get("завдання") or {})
    завдання["образів"] = 1
    завдання["відповідь"] = "ОБРАЗИ_V1"
    if int(спроба or 1) >= 2:
        # АДРЕСНО — ОКРЕМИМ ПОЛЕМ, А НЕ ХВОСТОМ ВИМОГИ: рядок «бракує» довгий
        # (склад образу + речі вітрини), і всередині `вимоги` він губився б між
        # чотирма короткими наказами, які мусять читатись як наказ.
        завдання["вимоги"] = list(ВИМОГИ_ПОВНОТИ_2)
        в["бракує"] = _бракує_адресно(в["образи"], потрібні, в["вітрина"], чому)
    else:
        завдання["вимоги"] = list(ВИМОГИ_ПОВНОТИ) + [
            "Адресно: " + "; ".join("%s — %s" % (ід, " / ".join(п))
                                    for ід, п in sorted(чому.items()))]
    в["завдання"] = завдання
    return в


def вибір_з_json(текст, вердикт, кандидати=None, каталог=None):
    """`ВИБІР_V1` від моделі → обраний образ id-ами, або названа відмова (Т-06, крок 1).

    Повертає `{обрано, ід, частини, номери, підпис, чому, прибрано, знехтувано,
    замінено, чому_відмова, помилки, розриви, повторний_виклик}`. `ід` порожній
    означає, що показувати нема чого: ні вибір моделі, ні запасний образ коду не
    склались.

    `розриви` — ОГОЛОШЕНІ ХОДИ ОБРАНОГО ОБРАЗУ, зняті з вердикта (`образ.свідомі`)
    і зрезолвлені тут же, поки стоїть пул: `річ` у вердикті — номер пакета, а
    `_застосувати_свідомі` судить над id каталогу. Без них виклик 3 судив образ із
    чистого аркуша: відповідь `ВИБІР_V1` оголошення не несе (їй нема де), і хід,
    названий на ітерації 2, помирав рівно тут — сила поверталась до повної, а
    ремонт, опис і журнал бачили огріх там, де ші зробила навмисно (рядок 9 дошки).

    ПОВТОРНИЙ ВИКЛИК — ЛИШЕ КОЛИ ВИБОРУ НЕМА ЧИМ ПРОЧИТАТИ (§1(б), те саме
    рішення, що в Т-04 над `ОБРАЗИ_V1`). Відповідь без поля `версія`, але з
    `обрано`, яке резолвиться в образ, — робоча: просити її переписати означало б
    подвоїти виклик заради поля, якого код не читає. Тому `помилки` їдуть полем
    ЗАВЖДИ (журнал, діагноз), а `повторний_виклик` — тільки коли образ не
    визначився.

    ЗАПАСНИЙ ОБРАЗ — НЕ МОВЧАЗНИЙ ДЕФОЛТ. Його беруть лише коли вибору немає або
    він не проходить гейт, і тоді `замінено` і `чому_відмова` кажуть, ЩО саме
    сталось. Доти це робив JS, звіряючи слова рядка `блокує`, і в журналі
    лишалось «крок вибору відкинуто» без імені образу, який пішов жінці.
    """
    словник = _словник_речей(кандидати, каталог)
    за_ном = _за_номером(кандидати)
    р = dict(обрано=None, ід=[], частини={}, номери={}, підпис=None, чому=None,
             прибрано=[], знехтувано=[], замінено=None, чому_відмова=None, помилки=[],
             розриви=[])
    об, причина = _ПР.розбір(текст)
    if об is None:
        р["помилки"] = [dict(де="корінь", що=причина)]
    else:
        р["помилки"] = _ПР.перевірити(_ПР.СХЕМИ["ВИБІР_V1"], об)
        р["чому"] = str(об.get("чому") or "").strip() or None
    о = None
    if об is not None:
        о = _образ_вердикту(вердикт, об.get("обрано"))
        if о is None:
            є = ", ".join(str((x or {}).get("ід")) for x in ((вердикт or {}).get("образи") or [])[:10])
            # ДОПИСУЄМО, А НЕ ЗАМІЩАЄМО: коли `обрано` взагалі нема, перша помилка
            # («обрано: обовʼязковий») каже більше за другу, і модель мусить почути
            # обидві — повторний виклик несе весь перелік.
            р["помилки"] = list(р["помилки"] or []) + [
                dict(де="обрано", що="образа з ід «%s» у цьому вердикті немає; є: %s"
                                     % (об.get("обрано"), є or "жодного"))]
    if р["помилки"] and о is None:
        р["чому_відмова"] = "відповідь не прочитано як ВИБІР_V1: %s" % "; ".join(
            str(п.get("що")) for п in р["помилки"][:2])
    if о is not None:
        р["обрано"] = str(о.get("ід") or "")
        р["підпис"] = str(о.get("підпис") or "").strip()[:60] or None
        с = _склад_вибору(о, словник, за_ном, (об.get("прибрати") or []))
        р.update(прибрано=с["прибрано"], знехтувано=с["знехтувано"])
        _чн = с["чому_ні"] or _чому_не_можна(о, прибирали=bool(с["прибрано"]))
        if _чн:
            р["чому_відмова"] = "вибір «%s» не прийнято: %s" % (р["обрано"], _чн)
        else:
            р.update(ід=с["ід"], частини=с["частини"],
                     розриви=_свідомі_з_json(о.get("свідомі"), словник, за_ном))
    if not р["ід"]:
        for к in ((вердикт or {}).get("образи") or []):
            if not isinstance(к, dict) or str(к.get("ід") or "") == (р["обрано"] or ""):
                continue
            if _чому_не_можна(к):
                continue
            с = _склад_вибору(к, словник, за_ном)
            if not с["чому_ні"]:
                р.update(замінено=str(к.get("ід") or ""), ід=с["ід"], частини=с["частини"],
                         розриви=_свідомі_з_json(к.get("свідомі"), словник, за_ном))
                р["підпис"] = str(к.get("підпис") or "").strip()[:60] or None
                break
    if р["помилки"] and not р["обрано"]:
        р["повторний_виклик"] = _ПР.помилка_формату(р["помилки"][:8], відповідь="ВИБІР_V1")
    # НОМЕРИ ОБРАНИХ РЕЧЕЙ ЇДУТЬ ДАЛІ (`bridge.опис` → `ОПИС_V1.образ.речі[].н`):
    # тут пул уже стоїть, а на кроці опису його нема й будувати його вдруге заради
    # кількох номерів означало б ще один відбір каталогу на найдорожчому кроці.
    ном = номери_речей(кандидати)[0] if кандидати else {}
    р["номери"] = {і: "#%d·%s" % ном[і] for і in р["ід"] if і in ном}
    return р


# ВИМОГИ ОПИСУ. Кожен рядок стоїть проти названого провалу живих карток: «червона
# сумка» з фото салатової (02.09), «Жилет на голое тело» (02.09, 18:45), порада
# докупити річ, якої в образі нема, і markdown-зірочки в тексті для жінки.
ФОТО_В_ОПИСІ = (
    "Фото речей стоять ПЕРЕД цим обʼєктом; чиє котре — у полі «фото_номери» кожної "
    "речі («[3, 4]» означає третє й четверте зображення).",
    "ФОТО ЧАСТО ЗНЯТІ НА МОДЕЛЯХ У ПОВНОМУ ОБРАЗІ: бери з кожного фото ЛИШЕ названу "
    "річ, решту одягу в кадрі ігноруй — вона не належить цьому образу.",
)
БЕЗ_ФОТО_В_ОПИСІ = (
    "Фото речей магазини не віддали — описуй за назвами; «фото_не_те» лишай порожнім.",
)
ВИМОГИ_ОПИСУ = (
    "Це образ, який ти обрала. Опиши його для цієї жінки — ТЕ, ЩО БАЧИШ, а не те, "
    "що каже назва.",
    "«текст» — проза для неї, трьома частинами: (1) речі, по рядку на кожну: що це, "
    "крій, довжина, колір словами, тканина; (2) взуття, верхній шар і аксесуари — "
    "ЛИШЕ ті, що є в «образ.речі», без пропозицій докупити; верхній шар при +20 °C і "
    "тепліше не згадуй; (3) чому "
    "це працює — 3–4 речення.",
    "Без markdown: жодних зірочок, жирного чи заголовків — звичайні речення й рядки.",
    # «ЯК ЦЕ НОСИТИ» — ОКРЕМЕ ПОЛЕ, А НЕ РЯДОК «СВІДОМО:» У ПРОЗІ. Доти цей блок
    # картки збирався регуляркою з тексту, тобто залежав від того, чи модель
    # вгадала форму рядка.
    "«як_носити» — по рядку на пораду: який варіант зі «укладка» ти обрала і що "
    "робити з оголошеним ходом зі «свідомі». Жінка прочитає це як пораду.",
    # ПАЛІТРА НАЗИВАЄТЬСЯ В ТРЕТІЙ ЧАСТИНІ, А НЕ ПЕРЕПИСУЄТЬСЯ СПИСКОМ: жінці
    # потрібне те, що вона забере з собою (метал, чого уникати, одне поєднання),
    # а не наша таблиця. Прохання м'яке («якщо є що сказати»), бо поля палітри
    # бувають порожні чесно: метал мовчить на утриманій осі тону.
    "Якщо є «палітра» — у третій частині скажи їй своїми словами те з неї, що "
    "стосується ЦЬОГО образу: метал прикрас, які кольори від неї найдальші, і "
    "одне поєднання, яке вона може зібрати сама. Не переписуй списками й не "
    "називай hex.",
    "Не називай чисел світлоти, типів фігури й не згадуй, що мав обмеження.",
    "ЛИШЕ УКРАЇНСЬКОЮ. Жодного російського слова чи форми — «голое тело», «платье», "
    "«обувь», «оттенок» — це помилка, текст із ними жінці не покажуть.",
    "У «текст» і «як_носити» НЕ пиши номерів речей («#12·03»), id і hex-кодів — "
    "лише людські слова.",
    # СКЛАД НЕ МІНЯЄТЬСЯ НА ОПИСІ, І ЦЕ ВИПРАВЛЕННЯ, А НЕ СУВОРІСТЬ (02.09.2026):
    # промпт вимагав «останнім рядком ОБРАЗ: id», а id моделі не давали — вона
    # фізично не могла їх написати, і найдорожчий крок щоразу відкидався.
    "Склад не міняй: якщо на фото річ не така, як ти думала, — скажи це словами в "
    "описі, а не підмінюй річ.",
    "Фото не та річ, явно інший колір, лише логотип або заглушка — назви номер "
    "ТІЄЇ РЕЧІ в «фото_не_те» («#98·29»). Це не міняє складу образу.",
    # МЕЖА ПОЛЯ НАЗВАНА ВГОЛОС (рядок 44 БЕКЛОГУ, скріншот власника 19.09.2026):
    # рядок «фото може не відповідати назві» стояв під трьома речами з п'яти,
    # зокрема під сукнею, чиє фото — очевидно та сама річ. Вимога вище називає
    # лише ПІДСТАВИ й жодного разу — те, що підставою НЕ є, а фото крамниць
    # знімаються на моделях у повному образі (див. `ФОТО_В_ОПИСІ`), тобто саме
    # ці кадри модель і мала за «щось не те».
    "«фото_не_те» — лише коли на фото ІНША КАТЕГОРІЯ речі, заглушка чи логотип. "
    "Та сама річ на людині, з іншого ракурсу, крупним планом деталі, з іншим "
    "одягом у кадрі або на іншому тлі — НЕ підстава. Сумнів — не називай.",
    "Відповідь — ЛИШЕ один JSON-обʼєкт за «завдання.схема_відповіді», без пояснень "
    "і без ```.",
)
# Що модель не має права писати в прозу. Рядком у `завдання.заборонено`, бо його
# читає модель; сам текст потім чистить `показ.людською` — два яруси на одне
# правило тут навмисні: перший просить, другий не пускає.
ЗАБОРОНЕНО_В_ОПИСІ = ("id речей", "номери «#12·03»", "hex-коди", "markdown")


def _укладка_опису(канал_3):
    """ТРЕТІЙ КАНАЛ КОРПУСУ ПОЛЕМ `укладка` (K-CRA-11 + K-CHN-01, Т-06 крок 2).

    `accessory.команди_розкладки` віддає ОПЦІЇ з названими компромісами (хустка:
    шия / сумка / запʼясток і наслідок кожного), `outer.команди_укладки` — ЗНАХІДКИ
    (вузол пояса тренча, піднятий комір). Обидві форми тут зводяться до одного
    поля схеми `{річ, опції}`: наслідок місця приклеюється до самого місця («у
    руці — читається як вечірнє»), бо схема дозволяє рядок, а втратити наслідок
    означало б дати вибір без ціни. Ворота формату («лише в приміщенні») ідуть
    останнім рядком опцій — це умова вибору, і модель мусить її бачити.
    """
    к3 = канал_3 or {}
    вих = []
    for о in (к3.get("опції") or [])[:6]:
        опції = []
        наслідки = о.get("наслідок_місця") or {}
        for м in (о.get("допустимі_місця") or []):
            н = str(наслідки.get(м) or "").strip()
            опції.append(("%s — %s" % (м, н[:100])) if н else str(м))
        if о.get("ворота_формату"):
            опції.append(str(о["ворота_формату"])[:110])
        if опції:
            вих.append(dict(річ=str(о.get("річ") or о.get("клас") or "річ")[:60], опції=опції))
    for c in (к3.get("команди") or [])[:5]:
        суть = str(c.get("суть") or "").strip()
        if суть:
            вих.append(dict(річ=str((c.get("речі") or ["образ"])[0])[:60], опції=[суть[:140]]))
    return вих


def опис_v1(речі, образ=None, задум=None, випадок=None, свідомі=None, фото_є=True,
            канал_3=None, палітра=None):
    """Четвертий виклик: `ОПИС_V1` — обраний образ обʼєктом, фото йдуть перед ним.

    `речі` — `[{н, назва, слот, магазин, фото, фото_номери}]`, як віддає
    `bridge.опис`. Скільки фото (рішення власника 02.09.2026): речей — усі, що в
    образі; на річ — одне-двоє. Тому річ і несе `фото_номери`: без них модель не
    знає, котре зображення чиє, і описує чуже взуття. Номер фото більше ніде не
    живе — «ФОТО НЕ ТЕ: N» знесено, і модель називає РІЧ, не знімок.

    ПОЛЯ `слот`, `фото_номери`, `вимоги` і `схема_відповіді` схема `ОПИС_V1` не
    оголошує й не мусить: «чужий ключ — не помилка» (шапка `протокол.py`), і
    `схема_відповіді` так само їде в `ВЕРДИКТ_V1.завдання` з Т-03. Без `слот`
    вимога «лише ті речі, що є в образі» неперевірна для моделі — назва не завжди
    каже, сумка це чи взуття.
    """
    р = []
    for x in (речі or []):
        з = dict(н=str(x.get("н") or x.get("id") or ""), назва=str(x.get("назва") or ""))
        for к, v in (("слот", x.get("слот")), ("магазин", x.get("магазин")),
                     ("фото", (x.get("фото") or [None])[0] if isinstance(x.get("фото"), (list, tuple))
                      else x.get("фото"))):
            if v:
                з[к] = str(v)
        ном = [int(n) for n in (x.get("фото_номери") or [])]
        if ном:
            з["фото_номери"] = ном
        р.append(з)
    об = {"версія": _ПР.ВЕРСІЯ, "образ": {"ід": str(образ or "обраний"), "речі": р}}
    if задум:
        об["задум"] = str(задум)[:120]
    свід = [str(с).strip() for с in (свідомі or []) if str(с or "").strip()]
    if свід:
        об["свідомі"] = свід[:4]
    укл = _укладка_опису(канал_3)
    if укл:
        об["укладка"] = укл
    if випадок:
        об["випадок"] = str(випадок)
    # ── ПАЛІТРА ЖІНКИ В ОПИСІ (K-PAL-11/14/15 і прийоми, 17.09.2026) ─────────
    # Опис — єдиний текст, який жінка читає цілком. Доти в ньому не було ні
    # металу, ні «чого уникати», ні жодного поєднання: практиковий шар палітри
    # рахувався, ішов у бриф і зникав до найдорожчого виклику. Склад той самий,
    # що в пакеті (`palettes.для_пакета`), і без чисел — з тієї самої причини.
    if палітра:
        об["палітра"] = dict(палітра)
    об["завдання"] = {
        "мова": "українська",
        "заборонено": list(ЗАБОРОНЕНО_В_ОПИСІ),
        "відповідь": "ОПИС_ВІДПОВІДЬ_V1",
        "схема_відповіді": скелет_схеми(_ПР.СХЕМИ["ОПИС_ВІДПОВІДЬ_V1"]),
        "вимоги": list(ФОТО_В_ОПИСІ if фото_є else БЕЗ_ФОТО_В_ОПИСІ) + list(ВИМОГИ_ОПИСУ),
    }
    return об


def фото_доведено_коду(запис):
    """Чому КОД вважає доведеним, що на фото речі — саме ця річ; None — доказу нема.

    ЩО ЦЕ ЛІКУЄ (рядок 44 БЕКЛОГУ, скріншот власника 19.09). Позначка «фото
    крамниці може не відповідати назві» вішалась на СЛОВО моделі й тільки на
    нього: три речі з п'яти, зокрема сукня, чиє фото очевидно та сама річ. Код
    при цьому мав свідка й мовчав — `каталог_збагачення`: локальна vision-модель
    описала перший кадр КОЖНОЇ речі окремим офлайн-прогоном (`жнива_збагачення`),
    і `фото_номер` там — 1 у 10 718 записах із 10 770, тобто рівно той кадр, який
    `bridge.опис` шле моделі першим.

    ДВІ УМОВИ, І ОБИДВІ ПОТРІБНІ. `збагачення` каже, що на кадрі щось видно
    (впевненість ≥ порога; «річ не видно» — логотип, таблиця розмірів — це 0 і
    до запису не доходить). `фото_слот` каже, що видно саме ЦЕЙ рід речі: опис
    vision-моделі проганяється тим самим словником слотів, яким код судить саму
    річ (`feed.слот`). Без другої умови доказом стала б і каблучка ж-07624, чий
    опис починається «Сукня темно-зеленого кольору» при впевненості 1.0.

    БЕЗ ВХОДУ — ЧЕСНО (CLAUDE.md п.4): речі без жнив, з «річ не видно» або з
    описом, який у слот не ліг, доказу не мають — позначка моделі проходить як є.
    ВИМІРЯНО 19.09.2026 на почищеному фіді, речі з фото: каталог_повний — доказ
    у 8 239 із 12 405 (66.4 %), решта без доказу (1 000 — опис назвав інший слот,
    1 240 — «річ не видно», 1 656 — жнив не було, 239 — опис у слот не ліг);
    каталог_brief — 235 із 485 (48.5 %).
    """
    r = запис or {}
    if not (r.get("збагачення") and r.get("слот") and r.get("фото_слот") == r["слот"]):
        return None
    return ("на першому кадрі vision-модель описала %s — це та сама річ" % r["слот"])


def опис_відповідь_з_json(текст, кандидати=None, каталог=None):
    """`ОПИС_ВІДПОВІДЬ_V1` → проза для жінки, поради й речі з поганим фото (Т-06, крок 3).

    Повертає `{текст, як_носити, фото_не_те, фото_не_ті, фото_не_ті_знято, проза,
    помилки, повторний_виклик}`. `фото_не_ті` — id каталогу, у які резолвились
    номери речей із `фото_не_те`; вони й лягають на картку позначкою під річчю.
    `фото_не_ті_знято` — ті, кому код доказом відмовив (`фото_доведено_коду`),
    разом із причиною: зняття позначки називається, а не робиться мовчки.

    ПРОЗА ДЛЯ МОВНОГО ГЕЙТА — ЛИШЕ ТЕ, ЩО ЧИТАЄ ЖІНКА (`текст` + `як_носити`).
    Гейт над цілим JSON судив би назви полів і номери речей: «#98·29» не є
    українською мовою й не є порушенням, а R-LNG-UA шукає російське саме в прозі.

    ПОВТОРНИЙ ВИКЛИК — ЛИШЕ БЕЗ `текст` (§1(б)): опис без прози показувати нечим,
    а опис без `версія` — робочий. Те саме рішення, що в `вибір_з_json`.
    """
    словник = _словник_речей(кандидати, каталог)
    за_ном = _за_номером(кандидати)
    р = dict(текст=None, як_носити=[], фото_не_те=[], фото_не_ті=[], фото_не_ті_знято=[],
             проза=None, помилки=[])
    об, причина = _ПР.розбір(текст)
    if об is None:
        р["помилки"] = [dict(де="корінь", що=причина)]
    else:
        р["помилки"] = _ПР.перевірити(_ПР.СХЕМИ["ОПИС_ВІДПОВІДЬ_V1"], об)
        р["текст"] = str(об.get("текст") or "").strip() or None
        р["як_носити"] = [str(x).strip() for x in (об.get("як_носити") or [])
                          if str(x or "").strip()][:6]
        _знято = set()
        for x in (об.get("фото_не_те") or []):
            р["фото_не_те"].append(str(x))
            з, _н, _ч = _розпізнати_речі(str(x), словник, за_ном)
            for і in з:
                if і in р["фото_не_ті"] or і in _знято:
                    continue
                # ДОКАЗ КОДУ ПЕРЕВАЖУЄ СЛОВО МОДЕЛІ, І ЛИШЕ ТУТ (рядок 44). Склад
                # образу від цього не міняється: знімається позначка під річчю, а
                # не річ. Мовчати про зняття не можна — воно їде полем у журнал.
                доказ = фото_доведено_коду(словник.get(і))
                if доказ:
                    _знято.add(і)
                    р["фото_не_ті_знято"].append(dict(id=і, чому=доказ))
                else:
                    р["фото_не_ті"].append(і)
    р["проза"] = "\n".join([р["текст"] or ""] + р["як_носити"]).strip() or None
    if not р["текст"]:
        р["повторний_виклик"] = _ПР.помилка_формату(
            р["помилки"][:8] or [dict(де="текст", що="обовʼязковий")],
            відповідь="ОПИС_ВІДПОВІДЬ_V1")
    return р


import re as _re_ід
# домен закінчується літерою/цифрою: кома чи крапка в кінці речення («…@gepur.com.») не
# належить id — спіймано на першій же прозовій відповіді (28.08.2026)
_ІД_РЕГ = _re_ід.compile(r"[A-Za-zА-Яа-яІіЇїЄєҐґ]{1,3}-\d{2,}@[\w\-]+(?:\.[\w\-]+)*")

# ── РОЗПІЗНАВАННЯ РЕЧЕЙ: ОДНЕ ПРАВИЛО НА ДВА ВХОДИ (Т-04) ────────────────────
# Речі моделі приходять або ПОЛЕМ `речі` обʼєкта ОБРАЗИ_V1 (головний шлях), або
# прозою (рука без каталогу, модель, що не витримала формат). Пара «номер·магазин»,
# словник id і половина комплекту мусять означати ТЕ САМЕ на обох входах, тому
# правило лежить тут одне. Доти воно жило лише в `ід_з_тексту`, а JSON доходив до
# нього через `_json_у_рядки` — переклад обʼєкта НАЗАД у рядки ПІДПИС/ОБРАЗ/СВІДОМО;
# поле, назване інакше, зникало без слова, і `свідомо` не доїжджало нікуди (V33).
_ПАРА_РЕГ = _re_ід.compile(r"#(\d+)[·.\-](\d{2})(?:/(верх|низ))?(?![0-9A-Fa-f])")


def _словник_речей(кандидати=None, каталог=None):
    """id → запис речі: спершу каталог, далі пул (слот бере з ключа пулу, якщо в записі нема)."""
    словник = {}
    for r in (каталог or []):
        if r.get("id"):
            словник[r["id"]] = r
    for сл, пул in (кандидати or {}).items():
        for r in пул:
            # кандидати пакета не несуть `слот` у записі — слот є ключем пулу
            if r.get("id"):
                словник.setdefault(r["id"], dict(r, слот=r.get("слот") or сл))
    return словник


def _за_номером(кандидати=None):
    """номер «#412» → (id, код магазину): та сама нумерація, що бачила модель."""
    if not кандидати:
        return {}
    _ном, _коди = номери_речей(кандидати)
    return {n: (і, к) for і, (n, к) in _ном.items()}


def _розпізнати_речі(де, словник, за_ном=None):
    """Один рядок (проза або елемент поля `речі`) → (id, невірні пари, половини комплекту).

    РОЗБІЖНІСТЬ КОДУ МАГАЗИНУ — ПОМИЛКА, А НЕ ПІДКАЗКА. Голий номер резолвився б
    у реальну, але іншу річ, і помилка моделі стала б тихою підміною. Тому пара
    звіряється: номер каже, ЯКА річ, код магазину — чи це та сама річ. Не збіглось
    — річ не зараховується й іде в `невідомі` під власним написанням.

    ПАРА ОБОВʼЯЗКОВА, І ЦЕ НЕ СУВОРІСТЬ, А ЗАХИСТ ВІД HEX. Перша версія приймала
    голий «#412», і регекс ловив `#4a4a4a` як річ номер 4: колір у прозі мовчки
    ставав чужою річчю. Промпт і так просить обидві частини («#412·29»), тож вимога
    збігається з контрактом. Заборона hex-хвоста окремо: «#41·29ab» — не наша пара.
    Без нумерації (`за_ном` порожній) пари не судяться взагалі: сказати «невірна»
    там, де нумерації не існує, означало б звинуватити модель у своїй же відсутності.
    """
    знайдені = [м.group(0) for м in _ІД_РЕГ.finditer(де)]
    # id поза регексом (інший словник магазину) — точний підрядковий збіг
    for і in словник:
        if і not in знайдені and і in де:
            знайдені.append(і)
    невірні, частини = [], {}
    if за_ном:
        for м in _ПАРА_РЕГ.finditer(де):
            n = int(м.group(1)); к = м.group(2)
            пара = за_ном.get(n)
            if пара and к == пара[1]:
                if пара[0] not in знайдені:
                    знайдені.append(пара[0])
                if м.group(3):
                    частини[пара[0]] = м.group(3)   # половина комплекту названа явно
            else:
                невірні.append(м.group(0).strip())
    return знайдені, невірні, частини


def _запис_образу(знайдені, невірні, словник, джерело, частини=None, за_назвою=None, чому=None):
    """Спільний контракт виходу обох розборів: що зараховано, що ні і чому.

    НЕВІРНІ ПАРИ ЇДУТЬ ОКРЕМИМ КАНАЛОМ. Змішати їх з `невідомі` означало б
    втратити різницю між «модель назвала річ, якої нема» і «модель назвала номер,
    що не сходиться з магазином» — а це різні хвороби з різним лікуванням.
    """
    ід, невідомі, бачено = [], [], set()
    for і in знайдені:
        if і in бачено:
            continue
        бачено.add(і)
        (ід if і in словник else невідомі).append(і)
    слоти = {}
    for і in ід:
        слоти.setdefault(словник[і].get("слот"), []).append(і)
    return dict(частини=dict(частини or {}), готово=bool(ід), ід=ід, джерело=джерело,
                невідомі=невідомі + list(невірні), невірні_пари=list(невірні),
                за_назвою=list(за_назвою or []),
                слот_двічі={с: v for с, v in слоти.items() if len(v) > 1},
                чому=(None if ід else (чому or "жодного id зі словника коду")))


def _це_образи(об):
    """Чи це відповідь із образами: ОБРАЗИ_V1 (`образи`) або ОДИН образ обʼєктом
    (`речі`/`образ`). Вибір сюди з Т-06 не заходить: `ВИБІР_V1` несе `обрано`, а не
    склад, і його читає `вибір_з_json`."""
    return isinstance(об, dict) and bool(об.get("образи") or об.get("речі") or об.get("образ"))


def образи_з_json(об, кандидати=None, каталог=None):
    """ОБРАЗИ_V1 (`протокол.ОБРАЗИ_V1`) → той самий запис на образ, що й розбір прози.

    Читає ПОЛЯ, не рядки: `речі` — номери «#12·03» або id, `підпис` — задум,
    `свідомо` — оголошені ходи `[{річ, чому}]`. Один образ обʼєктом теж приймається.

    ЩО ЦЕ ЛІКУЄ (Т-04, V33). Доти JSON ішов крізь `_json_у_рядки`: кожен обʼєкт
    розкладався назад у рядки, `свідомо` перетворювалось на `str(dict)`, і адресата
    оголошення в тому рядку не було — тобто на JSON-шляху оголошений хід НІКОЛИ
    нічого не послаблював, хоч модель його й казала. Тепер адресат їде полем `ід`
    розриву (`_свідомі_з_json`), а не вгадується з тексту.

    ЧОГО ТУТ НАВМИСНО НЕ ПЕРЕНОСИТЬСЯ: `полюс` і `ід` образу від моделі — читача в
    них ще нема (полюси набору — Т-10), а поле без читача виглядає як робочий канал
    і мовчки ним не є. `виконано` читача вже має, але ЧИТАЄ ЙОГО НЕ ЗВІДСИ:
    `перевірити_виконання` (Т-05) бере поле з самого обʼєкта ОБРАЗИ_V1, бо йому
    потрібні ще два входи, яких у записі образу нема й не буде, — попередній вердикт
    і новий суд. Дублювати поле в запис означало б другий канал для одного факту.
    """
    словник = _словник_речей(кандидати, каталог)
    за_ном = _за_номером(кандидати)
    образи = об.get("образи") if isinstance(об.get("образи"), list) else [об]
    вих = []
    for о in образи:
        if not isinstance(о, dict):
            continue
        речі = о.get("речі") or о.get("образ") or []
        if isinstance(речі, str):
            речі = [речі]
        знайдені, невірні, частини = [], [], {}
        for x in речі:
            з, н, ч = _розпізнати_речі(str(x), словник, за_ном)
            знайдені += [і for і in з if і not in знайдені]
            невірні += н
            частини.update(ч)
        запис = _запис_образу(знайдені, невірні, словник, "поле «речі»", частини,
                              чому="у полі «речі» немає жодного номера чи id зі словника коду")
        # ПІДПИС — 3–5 слів задуму, не пояснення. Друга ітерація відрізняє за ним
        # свідомий експеримент від огріху; без нього вона бачить лише номери.
        if о.get("підпис"):
            запис["підпис"] = str(о["підпис"]).strip()[:60]
        запис["свідомі"] = _свідомі_з_json(о.get("свідомо"), словник, за_ном)
        # `текст` лишається в записі, але на JSON-шляху несе ЛИШЕ ПРОЗУ моделі
        # (підпис, «чому», причини оголошених ходів): єдиний його читач —
        # мовний гейт (`перевірити_від_моделі`), а він судить саме прозу. Номери й
        # поля туди не йдуть: «#12·03» не є українською мовою й не є порушенням.
        проза = [str(о[k]).strip() for k in ("підпис", "чому") if str(о.get(k) or "").strip()]
        проза += [str(с.get("чому") or "").strip() for с in запис["свідомі"] if с.get("чому")]
        запис["текст"] = "\n".join(проза) or None
        вих.append(запис)
    return вих


def образи_з_тексту(текст, кандидати=None, каталог=None):
    """N образів з ОДНІЄЇ відповіді: по розбору на кожен рядок «ОБРАЗ: id, id, …».

    ЩО ЦЕ МІНЯЄ (правило 3): `ід_з_тексту` бере ОСТАННІЙ рядок «ОБРАЗ:» і мовчки
    викидає попередні — це було правильно, поки пакет просив один образ, і стало
    блокером, щойно цикл став «ші пропонує N, код судить кожен».

    Порядок у списку — порядок появи в тексті, НЕ ранг: кількість зауважень не є
    оцінкою (R-ABC-08), і менше ремонту не робить кандидата кращим.

    Порожній список НЕ повертається: якщо жодного рядка «ОБРАЗ:» нема, віддається
    один розбір по всьому тексту — рівно те, що робила `ід_з_тексту`, бо «модель
    не вжила формат» не те саме, що «модель нічого не запропонувала».

    JSON — ГОЛОВНИЙ ШЛЯХ, ПРОЗА — ЗАПАС (Т-04). Доти будь-яка відповідь спершу
    йшла крізь `_json_у_рядки` (обʼєкт → рядки → регулярки), і поле, назване
    інакше, зникало без слова. Тепер обʼєкт читає `образи_з_json` полями, а розбір
    рядків лишається там, де він єдиний можливий: відповідь прозою.
    """
    об = _ПР.розібрати_json(текст)
    if _це_образи(об):
        return образи_з_json(об, кандидати=кандидати, каталог=каталог)
    текст = str(текст or "")
    рядки_т = текст.split("\n")
    _обр = [i for i, l in enumerate(рядки_т)
            if _re_ід.match(r"\s*ОБРАЗ\s*[:：]", l, _re_ід.I)]
    if not _обр:
        return [ід_з_тексту(текст, кандидати=кандидати, каталог=каталог)]
    # ── БЛОК НА ОБРАЗ, А НЕ ОДИН ТЕКСТ НА ВСІХ ────────────────────────────────
    # ЩО ЦЕ МІНЯЄ (правило 3, before/after). Рядок «СВІДОМО: <річ> — <чому>» —
    # єдиний спосіб, яким ші каже «це не огріх, це хід». Код його читає
    # (`свідомі_розриви`) і послаблює відповідну знахідку в 0.6 раза.
    #   before — `_вердикти_образів` судив кожен образ БЕЗ тексту взагалі, тож на
    #            N образів жоден свідомий розрив не доходив нікуди: ші пояснила,
    #            код не почув, і друга ітерація діставала свій же навмисний хід у
    #            списку «що знайшов код» — тобто її просили полагодити те, що вона
    #            зробила навмисно. Рівно те, від чого підпис і рядок СВІДОМО й
    #            вигадувались.
    #   after  — кожен образ несе свій блок тексту, і його розрив judиться його ж
    #            поясненням. Передати натомість УВЕСЬ текст було б не краще, а
    #            гірше: пояснення третього образу мовчки послаблювало б знахідку в
    #            сьомому, і сила правила поповзла б без жодного сліду.
    # МЕЖА БЛОКУ. Усе до рядка «ОБРАЗ:» включно (з його ПІДПИСОМ) належить цьому
    # образу; рядки «СВІДОМО:» одразу ПІСЛЯ нього — теж йому, бо саме там їх
    # природно писати. Перший непорожній рядок іншого роду закриває блок.
    # ПОЗИЦІЙНЕ ПРАВИЛО ЖИВЕ ТІЛЬКИ ТУТ — У РОЗБОРІ ПРОЗИ (Н-V33-061, крок 4). Доти
    # цей абзац стояв ще й у `_формат_відповіді`, тобто код ПРОСИВ модель ставити
    # рядок під «ОБРАЗ:» — і тим самим промптом вимагав JSON, де позицію задає
    # структура. Просити більше нема кому: ПАКЕТ_V1 називає поле «свідомо», і в
    # обʼєкті оголошення стоїть УСЕРЕДИНІ свого образу — позицію задає структура,
    # а не порядок рядків (Т-04: `образи_з_json`). Правило лишається робочим для
    # відповідей, які ВСЕ Ж приходять прозою (рука без каталогу, модель, що не
    # витримала формат), і в цьому його єдиний сенс.
    блоки, поч = [], 0
    for i in _обр:
        кін, j = i, i + 1
        while j < len(рядки_т):
            л = рядки_т[j].strip()
            if not л:
                j += 1; continue
            if _СВІДОМО_РЕГ.match(рядки_т[j]):
                кін = j; j += 1; continue
            break
        блоки.append("\n".join(рядки_т[поч:кін + 1]))
        поч = кін + 1
    вих = []
    for б in блоки:
        о = ід_з_тексту(б, кандидати=кандидати, каталог=каталог)
        п = _re_ід.search(r"ПІДПИС\s*[:：]\s*(.+)", б, _re_ід.I)
        # ПІДПИС — 3–5 слів задуму, не пояснення. Друга ітерація відрізняє за ним
        # свідомий експеримент від огріху; без нього вона бачить лише id.
        if п: о["підпис"] = п.group(1).strip()[:60]
        о["текст"] = б
        о["свідомі"] = свідомі_розриви(б)
        вих.append(о)
    return вих


def ід_з_тексту(текст, кандидати=None, каталог=None):
    """Модель відповідає ТЕКСТОМ; код чекає список id. Це і є шов, якого не було:
    `перевірити_від_моделі` брав готовий `ід`, і стенду довелося б парсити прозу
    самому — на кожній платформі по-своєму (28.08.2026).

    Порядок розпізнавання, від найпевнішого:
      1. рядок «ОБРАЗ: id, id, …» (його просить пакет) — беремо ЛИШЕ його;
      2. усі id словника каталогу, що трапились у тексті;
      3. назви кандидатів (нормалізовані, ≥ 12 символів) — лише коли для слота ще
         нема id, і це ПОЗНАЧАЄТЬСЯ («за_назвою»), бо збіг назви слабший за id.
    Не вигадує: id поза словником іде в `невідомі`, два id в одному слоті — у
    `слот_двічі` (модель обрала «або», а не «і»), порожня відповідь — `готово=False`.

    JSON СЮДИ ТЕЖ ДОХОДИТЬ (Т-04) — від викликача, який має лише текст. Тоді
    береться ОСТАННІЙ образ: верхній рівень `перевірити_від_моделі` і є вердиктом
    по останньому образу (`bridge.від_моделі`, коментар біля `в["образи"]`), і так
    само поводився розбір прози — він брав останній рядок «ОБРАЗ:»."""
    об = _ПР.розібрати_json(текст)
    if _це_образи(об):
        образи = образи_з_json(об, кандидати=кандидати, каталог=каталог)
        return (образи[-1] if образи else
                _запис_образу([], [], {}, "поле «речі»",
                              чому="у відповіді є JSON, але жодного образу з речами"))
    текст = str(текст or "")
    частини = {}     # id → «верх»|«низ», коли модель узяла ПОЛОВИНУ комплекту («#12·03/низ»)
    словник = _словник_речей(кандидати, каталог)
    рядок = None
    for м in _re_ід.finditer(r"ОБРАЗ\s*[:：]\s*(.+)", текст, _re_ід.I):
        рядок = м.group(1)                     # останній такий рядок — фінальний
    джерело = "рядок ОБРАЗ" if рядок else "id у тексті"
    _де = рядок if рядок else текст
    # НОМЕР+МАГАЗИН І СЛОВНИК id — ОДНЕ ПРАВИЛО НА ОБА ВХОДИ (`_розпізнати_речі`).
    знайдені, невірні, _част = _розпізнати_речі(_де, словник, _за_номером(кандидати))
    частини.update(_част)
    ід = [і for і in dict.fromkeys(знайдені) if і in словник]
    за_назвою = []
    # НАЗВА — ЛИШЕ КОЛИ РЯДКА «ОБРАЗ:» НЕМА (02.09.2026). Рядок і є контракт;
    # добирати до нього речі з прози означало б, що згадана в поясненні й
    # ВІДКИНУТА річ («сумку лишаю вдома») мовчки стає частиною образу — і
    # тестувальниця судила б річ, якої модель не обирала.
    if кандидати and not рядок:
        зайняті = {словник[і].get("слот") for і in ід}
        норм = lambda s: _re_ід.sub(r"\s+", " ", str(s or "").lower()).strip()
        т = норм(текст)
        for сл, пул in кандидати.items():
            if сл in зайняті: continue
            збіги = [r for r in пул if r.get("назва") and len(норм(r["назва"])) >= 12 and норм(r["назва"])[:40] in т]
            if len(збіги) == 1:
                ід.append(збіги[0]["id"]); за_назвою.append(збіги[0]["id"]); зайняті.add(сл)
            elif len(збіги) > 1:
                за_назвою.append(dict(слот=сл, неоднозначно=[r["id"] for r in збіги]))
    return _запис_образу(ід + [і for і in знайдені if і not in словник], невірні, словник,
                         джерело, частини, за_назвою,
                         чому="у тексті моделі немає жодного id зі словника й жодної назви кандидата")


_СВІДОМО_РЕГ = _re_ід.compile(r"^\s*(?:СВІДОМО|Свідомо|свідомо|НАВМИСНО|Навмисно|навмисно)\s*[:—–-]\s*(.+?)\s*$", _re_ід.M)
СВІДОМИЙ_МНОЖНИК = 0.6   # той самий коефіцієнт, що K-KOH-03 дає ОДНОМУ свідомому розриву (T3)

def свідомі_розриви(текст):
    """Рядки «СВІДОМО: <річ> — <чому>» з ПРОЗОВОЇ відповіді моделі. Бриф давно велить
    моделі «умову порушуй свідомо й скажи одним рядком, яку саме і чому» — але
    зворотного шляху не було: `від_моделі` цей рядок не читав, і оголошений розрив
    судився як неоголошений (28.08.2026). Тепер він читається; формат і є контрактом.

    JSON СЮДИ НЕ ЗАХОДИТЬ (Т-04): в ОБРАЗИ_V1 оголошення — це поле `свідомо` образу,
    і читає його `_свідомі_з_json`. Доти обʼєкт доїжджав сюди рядком «СВІДОМО:
    {'річ': …, 'чому': …}» від `_json_у_рядки` — розрив ЗНАХОДИВСЯ, але адресата в
    ньому не було (номер речі не дорівнює id каталогу), тож він не послаблював
    нічого. Саме це й є V33: код чув оголошення й мовчки його втрачав."""
    return [dict(текст=м.group(1)) for м in _СВІДОМО_РЕГ.finditer(str(текст or ""))]


def _свідомі_з_json(свідомо, словник, за_ном=None):
    """Поле `свідомо` образу (`[{річ, чому}]`) → ті самі розриви, що дає проза, плюс
    АДРЕСАТ полем: `ід` — id речі, яку модель назвала номером «#12·03».

    Чому адресат полем, а не пошуком у тексті: номер речі — це нумерація ПАКЕТА, а
    знахідки коду стоять над id і назвами каталогу. Пошук номера в тексті розриву
    не знаходив нічого й тихо давав `без_адресата` — оголошення зникало (V33).
    Оголошення про образ у цілому (`річ` порожня або «образ») лишається без `ід`:
    його адресата шукає `_застосувати_свідомі` словами, як і в прозі.

    `текст` — НАЗВОЮ РЕЧІ, а не номером, коли номер резолвився. Його читають промпт
    вибору (`_шапка_вибору`), промпт опису (`bridge.опис`) і журнал: у кожного з них
    свій виклик і свіжий контекст, де «#26·28» нічого не значить — нумерація живе в
    ПАКЕТІ, а не у всіх промптах. Машинний адресат від цього не залежить: він у `ід`,
    а номер, як його написала модель, лишається в `річ`."""
    вих = []
    for с in (свідомо or []):
        якщо_рядок = isinstance(с, str)
        річ = "" if якщо_рядок else str((с or {}).get("річ") or "").strip()
        чому = str(с if якщо_рядок else (с or {}).get("чому") or "").strip()
        if not річ and not чому:
            continue
        р = dict(чому=чому)
        назва = річ
        if річ:
            р["річ"] = річ
            знайдені, _невірні, _ч = _розпізнати_речі(річ, словник, за_ном)
            ід = [і for і in знайдені if і in словник]
            if ід:
                р["ід"] = ід[0]
                # ОГОЛОШЕННЯ НАД КІЛЬКОМА РЕЧАМИ МАЄ СТІЛЬКИ Ж АДРЕСАТІВ (рядок 9
                # дошки, 19.09.2026). Доти лишався перший id — для поля `свідомо`
                # це майже завжди одна річ, і різниці не було видно. Але хід,
                # оголошений через «виконано: відхилено», стоїть над ЗНАХІДКОЮ, а
                # знахідка буває над двома-трьома речами: один адресат із трьох
                # означав би, що код послаблює третину того, що ші оголосила.
                if len(ід) > 1:
                    р["ід_речей"] = list(ід)
                назва = ", ".join(str(словник[і].get("назва") or річ)[:40] for і in ід)  # як `образ_рядком`
        р["текст"] = ("%s — %s" % (назва, чому)).strip(" —") if назва else чому
        вих.append(р)
    return вих


def _застосувати_свідомі(знахідки, розриви, речі):
    """Оголошений розрив ПОСЛАБЛЮЄ знахідки над названою річчю (×0.6, як K-KOH-03),
    не ховає їх: сила лишається видимою, знахідка несе `свідомий=True`. Чого це не
    робить, і навмисно: не торкається БЛОКЕРІВ (розмір, вето людини, погода — вимірний
    провал не оголошується) і не приймає оголошення без адресата (річ не названа —
    нема чого послаблювати; оголошення позначається `без_адресата`)."""
    if not розриви: return знахідки, []
    норм = lambda s: _re_ід.sub(r"\s+", " ", str(s or "").lower()).strip()
    звіт = []
    for р in розриви:
        т = норм(р["текст"])
        адресати = set()
        # ── АДРЕСАТ, НАЗВАНИЙ ПОЛЕМ, СИЛЬНІШИЙ ЗА ЗБІГ У ТЕКСТІ (Т-04) ────────
        # В ОБРАЗИ_V1 оголошення несе `річ`, і `_свідомі_з_json` уже перевів номер
        # у id. Шукати той самий номер у тексті було б гірше за марне: номер не
        # дорівнює id каталогу, і саме тому оголошення на JSON-шляху лишалось
        # `без_адресата` й не послаблювало нічого (V33). Якщо названа річ у цьому
        # образі не знайшлась — падаємо на пошук словами, як у прозі: модель могла
        # оголосити хід над річчю сусіднього образу, і це не мовчить.
        ід_р = str(р.get("ід") or "")
        _ід_усі = {str(x) for x in (р.get("ід_речей") or ([ід_р] if ід_р else []))}
        if _ід_усі:
            for rr in речі:
                _і = str(rr.get("id") or "")
                if _і in _ід_усі:
                    адресати |= {_і, rr.get("назва"), rr.get("слот")}
        # Пошук словами лишається БЕЗ ЗМІН — і накриває, як доти, всі речі, які
        # оголошення назвало: одне «СВІДОМО: верх і сумка — …» має двох адресатів.
        for rr in (речі if not адресати else ()):
            norm_id = str(rr.get("id") or "")
            назва = норм(rr.get("назва"))
            if (norm_id and norm_id.lower() in т) or (len(назва) >= 8 and (назва[:24] in т or назва.split(" ")[0] in т.split(" "))):
                адресати |= {norm_id, rr.get("назва"), rr.get("слот")}
            elif rr.get("слот") and (" %s" % rr["слот"]) in (" " + т):
                адресати |= {norm_id, rr.get("назва"), rr.get("слот")}
        адресати.discard(None); адресати.discard("")
        # ОБРАЗ У ЦІЛОМУ — ЛИШЕ КОЛИ РІЧ НЕ НАЗВАНА ПОЛЕМ (Т-04). «свідомо: {річ:
        # #26·28, чому: …це задум образу}» — хід над ОДНІЄЮ річчю, і слово «образ» у
        # причині не має права розтягувати його на знахідки над трьома речами: так
        # оголошення про сукню мовчки послаблювало б K-COMP-* усього образу. У прозі
        # адресата видно лише з тексту, тож там правило лишається як було.
        if not ід_р and any(w in т for w in ("образ", "весь", "усе", "цілком")):
            адресати.add("образ")          # оголошення про образ у цілому
        р = dict(р, адресати=sorted(a for a in адресати if a), послаблено=0)
        if not адресати:
            р["без_адресата"] = True
        звіт.append(р)
    вих = []
    for z in знахідки:
        z = dict(z)
        речі_зн = {str(x) for x in (z.get("речі") or [])}
        # знахідка над УСІМ образом (≥ 3 речей) послаблюється лише оголошенням про образ
        # («СВІДОМО: весь образ — …»), а не про одну річ у ньому
        над_образом = len(речі_зн) >= 3
        if not z.get("блокує") and z.get("сила") != "питання" and z.get("сила_нп"):
            for р in звіт:
                if р.get("без_адресата"): continue
                # ХІД НАД УСІМА РЕЧАМИ ЗНАХІДКИ — ЦЕ ХІД НАД НЕЮ (рядок 9, 19.09.2026).
                # Доти знахідку над ≥3 речами послаблювало лише оголошення про ВЕСЬ
                # образ. Але «виконано: відхилено — це задум» оголошується над ОДНІЄЮ
                # названою знахідкою, і вердикт переносить його сюди списком її ж
                # речей: коли оголошення назвало їх усі, це той самий хід, а не хід
                # про одну річ, мовчки розтягнутий на образ.
                if над_образом and "образ" not in р["адресати"] and not (речі_зн <= set(р["адресати"])):
                    continue
                if (речі_зн & set(р["адресати"])) or (над_образом and "образ" in р["адресати"]):
                    z["сила_нп"] = round(z["сила_нп"] * СВІДОМИЙ_МНОЖНИК, 3)
                    z["свідомий"] = р["текст"]
                    z["сила_нп_джерело"] = (z.get("сила_нп_джерело") or "") + "; свідомий розрив ×%.1f (K-KOH-03, T3)" % СВІДОМИЙ_МНОЖНИК
                    р["послаблено"] += 1
                    break
        вих.append(z)
    return вих, звіт


_HEX_РЕГ = _re_ід.compile(r"#[0-9a-fA-F]{6}\b")

def речі_з_тексту(текст, кеш=None):
    """Образ, який модель ВИГАДАЛА (руки 3 і 4 сліпої проби — каталогу вони не бачать),
    → речі коду тим самим шляхом, що й каталог. ФОРМАТ відповіді просить по рядку на
    річ «що це, крій, довжина, колір + hex, тканина»; кожен такий рядок стає
    псевдо-оффером тимчасового YML: назва = перший сегмент до коми (інакше «довжина в
    підлогу» з опису робила зі штанів вечірню сукню — спіймано на першому ж тесті),
    решта сегментів розкладаються в params тими самими словниками (тканина / крій /
    довжина), колір іде з hex через кеш кольорів по СПРАВЖНІХ id після читати_yml
    (кваліфікація @магазин не вгадується — спіймано там само: кеш мимо, і «коньячна»
    сумка випадала, бо слова у словнику нема). Впевненість 0.8: модель назвала точку,
    не слово. Слот, тип, крій, довжина, тканина далі витягуються функціями feed.прогін
    — щоб вердикт по руках без каталогу лягав у лог зі знахідками коду (28.08.2026).
    Рядок без hex → `без_кольору`; без слота → `без_слота`; другий рядок на той самий
    слот → `надлишок` (образ — по одній речі на слот)."""
    import tempfile as _tf, xml.sax.saxutils as _sx, os as _os, json as _js, feed as _Ф, colorspace as _cs, verify as _V
    рядки = [l.strip(" \t-•·*") for l in str(текст or "").splitlines()]
    кандидати, без_кольору = [], []
    for l in рядки:
        if not _re_ід.match(r"^\s*\d+[.)]\s*\S", l) and not _HEX_РЕГ.search(l): continue
        if l.upper().startswith(("ЧАСТИНА", "ОБРАЗ:", "СВІДОМО")): continue
        м = _HEX_РЕГ.search(l)
        повна = _re_ід.sub(r"^\s*\d+[.)]\s*", "", l)
        if not м:
            без_кольору.append(повна[:80]); continue
        сегменти = [с.strip(" .") for с in повна.split(",")]
        назва = сегменти[0]
        парам = {}
        for с in сегменти[1:]:
            if not с or _HEX_РЕГ.search(с): continue
            if "тканина" not in парам and _V.тканина_зі_слова(с).get("за_чим"): парам["тканина"] = с
            elif "крій" not in парам and _V.крій_зі_слова(с).get("крій"): парам["крій"] = с
            elif "довжина" not in парам and any(w in с.lower() for w in ("довжин", "міді", "максі", "міні", "до колін", "до стегон", "в підлогу", "по щиколотку", "укорочен")):
                парам["довжина"] = с
        кандидати.append((назва, повна, м.group(0).lower(), парам))
    if not кандидати:
        return dict(речі=[], без_кольору=без_кольору, без_слота=[], надлишок=[],
                    чому="жодного рядка з hex — модель не описала речі у форматі")
    офери_xml = []
    for i, (назва, повна, hex_, парам) in enumerate(кандидати, 1):
        п = "".join('<param name="%s">%s</param>' % (_sx.escape(k), _sx.escape(v)) for k, v in парам.items())
        офери_xml.append('<offer id="м-%03d" available="true"><name>%s</name><price>0</price>'
                         '<currencyId>UAH</currencyId><categoryId>1</categoryId>%s</offer>'
                         % (i, _sx.escape(назва), п))
    yml = ('<?xml version="1.0" encoding="UTF-8"?><yml_catalog><shop><name>модель</name><categories>'
           '<category id="1">образ вигаданий моделлю</category></categories><offers>%s</offers></shop></yml_catalog>'
           % "".join(офери_xml))
    fd, шлях = _tf.mkstemp(suffix=".xml"); _os.close(fd)
    fd2, кеш_ш = _tf.mkstemp(suffix=".json"); _os.close(fd2)
    try:
        open(шлях, "w", encoding="utf-8").write(yml)
        # справжні id (з кваліфікацією магазину, якщо феєд її дасть) — ключі кешу кольору
        оф = _Ф.читати_yml(шлях)[0]
        кеш_д, hex_за_ід = {}, {}
        for o, (назва, повна, hex_, парам) in zip(оф, кандидати):
            кеш_д[o["id"]] = dict(lab=list(_cs.hx(hex_)), впевненість=0.8, розкид=None)
            hex_за_ід[o["id"]] = hex_
        _js.dump(кеш_д, open(кеш_ш, "w", encoding="utf-8"))
        пр = _Ф.прогін(шлях, [[]], ліміт_фото=0, кеш=кеш_ш)
    finally:
        for f in (шлях, кеш_ш):
            try: _os.remove(f)
            except OSError: pass
    речі, зайняті, надлишок = [], set(), []
    у_каталозі = set()
    for c in пр["каталог"]:
        у_каталозі.add(c["id"])
        if c["слот"] in зайняті:
            надлишок.append(dict(слот=c["слот"], назва=c["назва"][:60])); continue
        зайняті.add(c["слот"])
        c = dict(c); c["hex"] = hex_за_ід.get(c["id"]); c["джерело"] = "модель"
        речі.append(c)
    без_слота = [dict(назва=(назва or повна)[:60]) for (назва, повна, hex_, парам), o in zip(кандидати, оф)
                 if o["id"] not in у_каталозі]
    return dict(речі=речі, без_кольору=без_кольору, без_слота=без_слота, надлишок=надлишок,
                чому=None if речі else "речі є, але жодна не лягла у слот або не має кольору")


def перевірити_образ_моделі(текст, F, тіло, сценарій=None):
    """Рука без каталогу: текст моделі → речі → той самий граф, що й для вибору коду."""
    import composer as _КМ, graph as _ГР
    р = речі_з_тексту(текст)
    вих = dict(перевірено=False, розбір=р, знахідки=[], граф=None, вузол=None, блокує=[], рядок_вузла=None, мова=None)
    if len(р["речі"]) < 2:
        вих["чому"] = "замало речей із кольором і слотом (%d)" % len(р["речі"]); return вих
    сценарій = dict(сценарій or {})
    готові = [_КМ._у_річ(dict(c), c["слот"], тіло) for c in р["речі"]]
    блокує, сума, зн, _ = _КМ._оцінити(F, готові, тіло, None, None, **сценарій)
    зн, свідомі = _застосувати_свідомі(зн, свідомі_розриви(текст), готові)
    г = _ГР.граф(зн, готові); в = _ГР.вузол_напруги(г)
    вих.update(перевірено=True, речі=[dict(id=r["id"], слот=r["слот"], назва=r["назва"], hex=r.get("hex")) for r in готові],
               знахідки=зн, граф=г, вузол=(в or {}).get("вузол"), рядок_вузла=_ГР.рядок_вузла(в, г),
               блокує=[z.get("суть") for z in блокує], свідомі=свідомі)
    try:
        import language_gate as _LG
        # режим названий явно з тієї самої причини, що в `перевірити_від_моделі`
        # (Т-07 крок 1); руки 3/4 реагують лише на ярус української — межа
        # записана в `language_gate` біля `ЯРУС_УКРАЇНСЬКОЇ` і в показі.
        вих["мова"] = (_LG.перевірити(текст, режим="блокувати")
                       if hasattr(_LG, "перевірити") else None)
    except Exception:
        вих["мова"] = None
    return вих


# ── ЧИ ВЦІЛІВ АКЦЕНТ, ЯКОГО ЗАЖАДАВ САМ КОД ────────────────────────────────
# ЩО ЦЕ ЛОВИТЬ (правило 3, реальний випадок 04.09.2026). Тестувальниця обрала
# червоний і схему «нейтрали+акцент». Спека поклала акцент на взуття й сумку
# (C 28–70, L 57–72). Обидві руки віддали суцільно чорний образ — C ≈ 2 на всіх
# чотирьох слотах. Суддя видав 8 знахідок і ЖОДНОЇ про колір: код приписав
# слоту роль і не перевірив, чи вона виконана. Петля була розімкнена — приписав
# і забув. Мовчання судді неможливо відрізнити від «акцент на місці».
#
# СИЛА ≤ ВЕРИФІКАЦІЯ (правило 4). Тут не стверджується, що образ гірший, — це
# скаже носій. Стверджується рівно те, що вимірюється: код зажадав хрому в
# слоті, річ у слоті її не має. Тому дві РІЗНІ знахідки, бо це два різні
# дефекти з різними адресатами:
#   · пул мав чим — це вибір проти власної спеки (адресат: промпт і модель);
#   · пул не мав чим — це дефіцит каталогу (адресат: закупівля джерел), і
#     звинувачувати модель тут було б помилкою атрибуції.
def схема_образу(речі, спец_слоти, за_ід=None):
    """[знахідки] K-PAL-03 — річ поза дугою обраної схеми, або кольорова річ на
    нейтральній ролі (16.09.2026). Дуга схеми — межа, яку обрала жінка, а не порада:
    доти червона сумка в «тональній сливовій» не давала жодної знахідки."""
    if not спец_слоти or not isinstance(спец_слоти, dict):
        return []
    import colorspace as _КС, реєстр_правил as _РЕЄСТР
    # РЕГІСТР СТАВИТЬСЯ ТУТ: `протокол.регістр_знахідки` бере його з рядка, а не з
    # політики, тож знахідка без поля йшла б реплікою попри політику «гейт».
    _рег = _РЕЄСТР.регістр("K-PAL-03", "hard")
    зн = []
    for r in речі:
        с = r.get("слот")
        сп = спец_слоти.get(с)
        if not isinstance(сп, dict):
            continue
        дуга, роль = сп.get("дуга_тону"), сп.get("роль")
        повна = (за_ід or {}).get(r.get("id")) or r
        lab = повна.get("lab")
        if not lab and повна.get("hex"):
            try: lab = _КС.hx(повна["hex"])
            except Exception: lab = None
        if not lab or len(lab) < 3:
            continue
        try:
            L, C, h = _КС.lch(lab)
        except Exception:
            continue
        if _нейтральний_тон(h, C, L):
            continue                                   # нейтраль законна під будь-яку схему
        схема = спец_слоти.get("_схема", "?")
        if дуга == "нейтраль" and роль in ("домінанта", "секундант"):
            зн.append(dict(правило="K-PAL-03", сила="hard", сила_нп=0.95, впевненість=1.0, регістр=_рег,
                           сила_нп_джерело="межа схеми: роль слота задана обраною схемою",
                           бік="код", слот=с, речі=[r.get("id")],
                           ярлик="кольорова річ на нейтральній ролі",
                           суть="схема «%s» тримає слот «%s» нейтральним, а річ має хрому %.0f" % (схема, с, C),
                           чому="роль слота задана схемою, яку обрала жінка",
                           що_зняло_б="нейтральна річ у слоті «%s»" % с))
            continue
        if not (isinstance(дуга, (list, tuple)) and len(дуга) == 2 and дуга[0] is not None):
            continue
        lo, hi = float(дуга[0]), float(дуга[1])
        в_дузі = (lo <= hi and lo - 10 <= h <= hi + 10) or (lo > hi and (h >= lo - 10 or h <= hi + 10))
        if not в_дузі:
            зн.append(dict(правило="K-PAL-03", сила="hard", сила_нп=0.95, впевненість=1.0, регістр=_рег,
                           сила_нп_джерело="межа схеми: тон речі проти дуги обраної схеми",
                           бік="код", слот=с, речі=[r.get("id")],
                           ярлик="поза дугою схеми",
                           суть="схема «%s»: слот «%s» (роль %s) тримає тон %.0f–%.0f°, а річ має тон %.0f° при хромі %.0f"
                                % (схема, с, роль, lo, hi, h, C),
                           чому="дуга схеми — межа, а не порада: поза нею образ не тримає обраної схеми",
                           що_зняло_б="річ у дузі схеми або нейтральна в слоті «%s»" % с))
    return зн


# ── ПРАКТИКОВА ПАЛІТРА СУДИТЬ ЗІБРАНИЙ ОБРАЗ (K-PAL-07…10, 12, 14, 15) ────────
# ЩО ТУТ БУЛО ДО 17.09.2026. Увесь шар `palettes.py` рахувався на кожному прогоні
# й лишав слід у `trace`: прийоми (K-PAL-02…13), найдальші кольори (K-PAL-14),
# поєднання всередині палітри (K-PAL-15). Жодне з них не судило ОБРАЗ: у вердикт
# від цього шару доїжджали рівно два правила — K-PAL-03 (дуга схеми) і K-PAL-18
# (акцент). Тобто система знала, які кольори найдальші від жінки, і мовчала, коли
# модель ставила саме їх їй до обличчя.
# ЧОМУ СУД, А НЕ ФІЛЬТР ПУЛУ. Прийоми — оператори над ОБРАЗОМ, а не над річчю:
# «контраст як носій» питає про контраст усього образу, «розміщення» — про те, де
# річ стоїть відносно обличчя, «поєднання» — про пари кольорів. Пул їх виконати
# не може за побудовою: у ньому речі стоять поодинці.
_ЗАПАС_ДУГИ = 10.0          # той самий, що в `_у_дузі_вікон` і `схема_образу`

# ШКАЛА FORCE → ВАГА, ОДНА НА МОДУЛЬ. Той самий словник стояв локальним `_НП`
# усередині `перевірити_від_моделі` (16.09: «знахідка без `сила_нп` гине у
# вердикті»); відколи його потребує ще й `палітра_образу`, дві копії розійшлись
# би мовчки — і половина правил палітри важила б не те, що оголосила.
_СИЛА_НП = {"hard": 0.95, "strong": 0.75, "default": 0.5, "soft": 0.35, "hint": 0.2}


def _у_вікнах(вікна, L, C, h):
    """Чи лежить колір у наборі вікон палітри (світлота × хрома × котрась дуга сім'ї)."""
    if not вікна:
        return False
    Llo, Lhi = вікна["L"]; Clo, Chi = вікна["C"]
    if not (Llo <= L <= Lhi) or not (Clo <= C <= Chi):
        return False
    for arcs in (вікна.get("сім_ї") or {}).values():
        for a in (arcs or ()):
            lo, hi = float(a[0]) - _ЗАПАС_ДУГИ, float(a[1]) + _ЗАПАС_ДУГИ
            if (lo <= h <= hi) if lo <= hi else (h >= lo or h <= hi):
                return True
    return False


def _кольори_образу(речі, за_ід=None):
    """[(річ, слот, L, C, h, near)] для речей із ВИМІРЯНИМ кольором.

    `за_ід` обовʼязковий із тієї самої причини, що в `акцент_образу`: рядок пулу,
    який їде моделі, не несе `lab`, і рахувати колір по ньому означало б судити
    дефолтний сірий (див. `bridge.каталог_останнього_пакета`).
    """
    import colorspace as _КС, колір_образу as _КО
    out = []
    for r in (речі or ()):
        повна = (за_ід or {}).get(r.get("id")) or r
        lab = повна.get("lab")
        if not lab and повна.get("hex"):
            try: lab = _КС.hx(повна["hex"])
            except Exception: lab = None
        if not lab or len(lab) < 3:
            continue
        try: L, C, h = _КС.lch(lab)
        except Exception: continue
        слот = r.get("слот")
        out.append((r, слот, L, C, h, _КО.SLOT_NEAR_FALLBACK.get(слот, 0.3)))
    return out


def палітра_образу(речі, спец_слоти, за_ід=None):
    """[знахідки] практикових прийомів над зібраним образом.

    Чекає в `спец_слоти` службові ключі, які кладе шов (`bridge._пакет_каталогу`):
    `_палітра` — вихід `palettes.палітра_практична` (вікна, найдальші, активні
    прийоми), `_контраст` — рівень контрасту особи. Без них правила мовчать, і це
    «без входу», а не «пройдено»: перевірка без палітри була б заглушкою,
    невідрізненною від зеленого вердикту. Саме це й показує третій чекліст
    (`суд_образу.ЧЕКЛІСТ_ПАЛІТРИ`), щоб мовчання було видно.
    """
    П = (спец_слоти or {}).get("_палітра")
    if not isinstance(П, dict) or not П.get("вікна"):
        return []
    import реєстр_правил as _РЕЄСТР, palettes as _ПЛ, колір_образу as _КО
    рівень = (спец_слоти or {}).get("_контраст")
    # НАМІР ТУТ НЕ ЧИТАЄТЬСЯ, І ЦЕ НЕ ПРОПУСК: `palettes.прийоми` уже склав список
    # активних прийомів ІЗ НАМІРОМ (колор-блок і драматизація залежать від нього),
    # тож питати намір удруге означало б завести другого суддю тієї самої умови.
    активні = {x["прийом"] for x in (П.get("прийоми") or []) if x.get("активний")}
    далекі = (П.get("найдальші") or {}).get("вікна")
    гучно = _РЕЄСТР.C["hi_C"]
    зн = []

    def _дод(правило, сила, ярлик, суть, чому, зняло_б, речі_, слот=None, **решта):
        зн.append(dict(правило=правило, сила=сила, сила_нп=_СИЛА_НП[сила], впевненість=1.0,
                       регістр=_РЕЄСТР.регістр(правило, сила), бік="код",
                       сила_нп_джерело="корпусна сила прийому палітри (тема-2 §K-PAL)",
                       слот=слот, речі=[x for x in речі_ if x], ярлик=ярлик,
                       суть=суть, чому=чому, що_зняло_б=зняло_б, **решта))

    точки = _кольори_образу(речі, за_ід)
    # НЕЙТРАЛЬ І МЕТАЛ ВИХОДЯТЬ ІЗ-ПІД ЦИХ ПРАВИЛ, і з тієї самої причини, що в
    # `схема_образу`: нейтраль законна під будь-яку схему (K-COL-06), а фурнітуру
    # судить метал палітри (K-PAL-11), не дуга сім'ї.
    кольорові = [(r, с, L, C, h, near) for r, с, L, C, h, near in точки
                 if not _нейтральний_тон(h, C, L)
                 and not _ПЛ.метал_речі(_lab_з(L, C, h), с)]
    поза_палітрою = [t for t in кольорові if not _у_вікнах(П["вікна"], t[2], t[3], t[4])]

    # ── K-PAL-14 / K-PAL-09: ЩО НОСИТИ БІЛЯ ОБЛИЧЧЯ ─────────────────────────
    # «Кольори палітри біля обличчя; кольори поза палітрою — у слоти далі від
    # обличчя» (K-PAL-09, default) і «найдальші — область із усіма осями,
    # оберненими проти домінанти» (K-PAL-14, hint).
    # ВОНИ НЕ ВИКЛЮЧАЮТЬ ОДНЕ ОДНОГО, І ЦЕ РІШЕННЯ, ЗМІНЕНЕ ПІД ЧАС ПРАВКИ.
    # Перша редакція давала на річ рівно одне з двох («14 названо — 09 мовчить»),
    # і це виявилось хибним із двох боків. По суті: корпус пов'язує їх ПРЯМО —
    # «labelled furthest, not forbidden; K-PAL-08 and K-PAL-09 say how to carry
    # them anyway», тобто 14 називає колір, а 09 каже, куди його подіти; разом
    # вони одна порада, поодинці — половина. По факту: взаємне виключення лишало
    # K-PAL-09 самий залишок (тони, що не лежать ні у вікнах палітри, ні в
    # найдальших) — на стенді це порожня множина, і правило `default`-сили
    # мовчало б на кожному живому вході. Одне правило — один рядок у вердикті
    # (`знахідки_вердикту` зливає за `правило`), тож два рядки тут — це два різні
    # твердження, а не дубль.
    for r, с, L, C, h, near in поза_палітрою:
        if near < _КО.NEAR_МІН:
            continue                        # далеко від обличчя — K-PAL-09 це й дозволяє
        якнайдалі = [x for x in (_КО.SLOT_NEAR_FALLBACK or {}) if _КО.SLOT_NEAR_FALLBACK[x] <= 0.2]
        if далекі and _у_вікнах(далекі, L, C, h):
            _дод("K-PAL-14", "hint", "найдальший колір біля обличчя",
                 "«%s» стоїть біля обличчя, а її колір лежить у найдальшій від ваших осей "
                 "області (%s): жодної спільної характеристики з вами"
                 % (с or "річ", (П.get("найдальші") or {}).get("словами") or "всі осі обернені"),
                 "практики дають «найдальші» як відповідь на «чого уникати»; це не заборона — "
                 "K-PAL-08 і K-PAL-09 кажуть, як їх усе ж нести",
                 "той самий колір у слоті далі від обличчя (%s) або колір із палітри у «%s»"
                 % (", ".join(sorted(якнайдалі)[:3]), с or "цьому слоті"),
                 [r.get("id")], слот=с)
        _дод("K-PAL-09", "default", "колір поза палітрою біля обличчя",
             "«%s» стоїть біля обличчя (вага %.2f), а її колір поза вікнами вашої палітри"
             % (с or "річ", near),
             "індукція локальна (Chevreul: найсильніша на лінії контакту), тому практики "
             "тримають кольори поза палітрою далі від обличчя",
             "перенести цей колір у слот далі від обличчя (%s) або взяти колір палітри"
             % ", ".join(sorted(якнайдалі)[:3]),
             [r.get("id")], слот=с)

    # ── K-PAL-08: КОНТРАСТ ЯК НОСІЙ ─────────────────────────────────────────
    # «Колір поза палітрою можна нести, якщо контраст образу збігається з
    # контрастом людини» (Lamport, hint). Отже правило говорить рівно тоді, коли
    # такий колір В ОБРАЗІ Є: інакше воно не має про що судити. Смуги збігу —
    # ті самі числа K-PAL-15, якими код уже породжує трійки, а не нові.
    if поза_палітрою and len(точки) >= 2:
        розмах = max(t[2] for t in точки) - min(t[2] for t in точки)
        носій = not (рівень == "низький" and розмах > 45) and not (рівень == "високий" and розмах < 30)
        if not носій:
            _дод("K-PAL-08", "hint", "колір поза палітрою без носія",
                 "в образі є колір поза палітрою, а контраст образу (розмах світлоти %.0f) "
                 "не збігається з вашим (%s) — нести його нема на чому" % (розмах, рівень),
                 "Lamport: «easier to wear less flattering colours if you're wearing the right "
                 "contrast levels» — носієм чужого кольору є саме збіг контрастів",
                 "звести контраст образу до вашого або лишити колір поза палітрою в слоті "
                 "далі від обличчя",
                 [t[0].get("id") for t in поза_палітрою])

    # ── K-PAL-15: ПОЄДНАННЯ — ТА САМА ЛОГІКА, ЩО В ТРІЙКАХ ──────────────────
    # Код видає жінці трійки (`palettes.поєднання`); той самий набір перевірок
    # (`palettes.набір_законний`) тепер судить те, що склала модель. Один емітент
    # логіки, не два: інакше система пропонувала б те, що сама відхиляє.
    if len(кольорові) >= 2:
        законно, чому_ні = _ПЛ.набір_законний([(t[2], t[3]) for t in кольорові], рівень)
        if not законно:
            _дод("K-PAL-15", "hint", "кольори образу не в логіці ваших поєднань",
                 "кольори образу разом не тримають тієї логіки, якою складені ваші поєднання: %s" % чому_ні,
                 "стиліст видає не палітру, а готові трійки; вони будуються кроком світлоти "
                 "(K-COL-01), бюджетом хроми (K-COL-02) і вашим рівнем контрасту",
                 "розвести світлоти кольорів або лишити гучним лише один",
                 [t[0].get("id") for t in кольорові])

    # ── K-PAL-02: АКЦЕНТ БЕРЕТЬСЯ ВІД ОЧЕЙ ПЕРШИМ ────────────────────────────
    # «Повторити колір очей як акцент … завжди доступний, ПЕРШИЙ за порядком»
    # (R-COL-17, Perrett 2023: одяг обирають до райдужки, не до шкіри; 200
    # учасників, T2). У пулі це вже діє рангом рядка, але ранг розв'язує лише
    # НІЧИЮ — а тут питання інше й перевірне: слот, якому СХЕМА дала роль акценту,
    # несе колір із сім'ї очей чи чужий. Мовчимо, коли акцент нейтральний: «нема
    # акценту» — це K-PAL-18, інше правило й інший ремонт.
    очі_дуги_02 = (П["вікна"].get("сім_ї") or {}).get("очі") or []
    if очі_дуги_02:
        def _в_очах(h):
            for a in очі_дуги_02:
                lo, hi = float(a[0]) - _ЗАПАС_ДУГИ, float(a[1]) + _ЗАПАС_ДУГИ
                if (lo <= h <= hi) if lo <= hi else (h >= lo or h <= hi):
                    return True
            return False
        for r, с, L, C, h, near in кольорові:
            сп = (спец_слоти or {}).get(с)
            if not isinstance(сп, dict) or сп.get("роль") != "акцент":
                continue
            if _в_очах(h):
                continue
            _дод("K-PAL-02", "hint", "акцент не від очей",
                 "слот «%s» несе акцент, а його тон (%.0f°) не з сім'ї ваших очей (%s)"
                 % (с, h, "; ".join("%.0f–%.0f°" % (a[0], a[1]) for a in очі_дуги_02)),
                 "Perrett 2023: одяг обирають до райдужки, не до шкіри; практики ставлять "
                 "перегук очей першим прийомом — це колір, який у людини вже є",
                 "акцент у сім'ї очей (%s) у слоті «%s»"
                 % ("; ".join("%.0f–%.0f°" % (a[0], a[1]) for a in очі_дуги_02), с),
                 [r.get("id")], слот=с)

    # ── K-PAL-05 / 06: ЯКИЙ ПРИЙОМ ОБРАЗ РЕАЛІЗУЄ — І ЧИ ВІН ЇЇ ──────────────
    # Прийоми — оператори з УМОВОЮ («середній/високий контраст», «на м'якій людині
    # обидва приглушені», «для низького контрасту акцент приглушений»). Умова
    # рахувалась у `palettes.прийоми` і вирішувала лише, чи називати прийом
    # доступним; що образ РЕАЛІЗУЄ саме цей прийом і порушує саме його умову, не
    # питав ніхто. Тут образ спершу ВПІЗНАЄТЬСЯ, а тоді перевіряється умова
    # впізнаного — не всіх підряд: інакше на кожен образ висипалось би по чотири
    # hint-и про прийоми, яких у ньому нема.
    if len(кольорові) >= 2:
        дельти = [abs((кольорові[i][4] - кольорові[j][4] + 180) % 360 - 180)
                  for i in range(len(кольорові)) for j in range(i + 1, len(кольорові))]
        м_яка = (П.get("осі") or {}).get("позиція", {}).get("chroma", 0.0) < 0
        if any(d >= 150 for d in дельти):
            # K-PAL-05 приглушена комплементарна: «один із двох приглушений або малий;
            # на м'якій людині — обидва приглушені»
            гучних = sum(1 for t in кольорові if t[3] >= гучно)
            треба = 0 if м_яка else 1
            if гучних > треба:
                _дод("K-PAL-05", "default", "комплементарна пара не приглушена",
                     "образ веде комплементарна пара (розведення тону %.0f°), а гучних кольорів %d "
                     "при дозволених %d%s" % (max(дельти), гучних, треба,
                                              " — ваша палітра м'яка, тут приглушені обидва" if м_яка else ""),
                     "прийом дозволяє комплемент лише коли один із двох приглушений або малий; "
                     "на м'якій людині — обидва (K-COL-03, бюджет хроми)",
                     "приглушити один із двох кольорів або лишити його малою площею",
                     [t[0].get("id") for t in кольорові if t[3] >= гучно])
        # K-PAL-04 (аналогова) ВЕРДИКТУ ТУТ НЕ МАЄ, І ЦЕ РІШЕННЯ, А НЕ ПРОПУСК.
        # Перша редакція давала знахідку «аналогова пара, а прийом не в наборі для
        # вашого контрасту» — і гілка виявилась недосяжною за побудовою: корпус не
        # вимикає аналогову на жодному контрасті («низький/середній; на високому
        # крок ΔL обовʼязковий»), тож умова «прийом недоступний» хибна завжди.
        # А те, що правило справді стверджує над образом — крок світлоти між
        # сім'ями — уже міряє `набір_законний` (K-PAL-15) тим самим `step_min`
        # K-COL-01; другий рядок про те саме число був би не другим правилом, а
        # тим самим удвічі. K-PAL-04 діє там, де має: він ПОРОДЖУЄ аналогові трійки
        # (`palettes.поєднання` з ід="K-PAL-04") і стоїть у пакеті й описі серед
        # прийомів, доступних цій людині, зі своєю умовою.

    # ── K-PAL-06: НЕЙТРАЛІ ПЛЮС ОДИН АКЦЕНТ ──────────────────────────────────
    # «Нейтралі людини + один акцент, перший — сім'я очей; дефолт для високого
    # контрасту; ДЛЯ НИЗЬКОГО АКЦЕНТ ПРИГЛУШЕНИЙ» (K-COL-03; palettehunt; Lamport).
    # ЧОМУ ПОЗА ЛАНЦЮЖКОМ ВПІЗНАВАННЯ ВИЩЕ, І ЦЕ ВИПРАВЛЕННЯ, А НЕ СМАК: той
    # ланцюжок стоїть під `len(кольорові) >= 2`, бо впізнає ВІДНОШЕННЯ між двома
    # кольорами (комплемент, сусідні сім'ї). А цей прийом упізнається якраз
    # ОДНИМ кольоровим на тлі нейтралей — тобто під тією умовою він недосяжний за
    # побудовою. Спіймано пробою: образ «гучна сорочка + три нейтралі» на
    # низькоконтрастній жінці проходив мовчки.
    if len(кольорові) == 1 and len(точки) > 1 and рівень == "низький" and кольорові[0][3] >= гучно:
        акц = кольорові[0]
        _дод("K-PAL-06", "default", "акцент не приглушений на низькому контрасті",
             "образ — ваші нейтралі плюс один акцент, і акцент гучний (хрома %.0f ≥ %.0f) "
             "при низькому контрасті" % (акц[3], гучно),
             "прийом дає для низького контрасту приглушений акцент: гучний на низькому "
             "контрасті читається не як акцент, а як чужа пляма",
             "приглушити акцент або лишити його малою площею",
             [акц[0].get("id")], слот=акц[1])

    # ── K-PAL-07: КОЛОР-БЛОК ВИМКНЕНО НА НИЗЬКОМУ КОНТРАСТІ ─────────────────
    # `palettes.прийоми` вже вирішує, чи прийом доступний ЦІЙ людині («statement
    # або високий контраст; вимкнено на низькому»). Доти це рішення нікуди не
    # їхало. Тут воно судить образ: дві-три кольорові сім'ї у великих слотах — це
    # і є колор-блок, і на низькому контрасті під conventional його нема в наборі.
    ВЕЛИКІ = ("верх", "низ", "сукня", "комплект", "верхній_шар")
    сім_ї_великих = {_сім_я_кута(h) for r, с, L, C, h, near in кольорові if с in ВЕЛИКІ}
    сім_ї_великих.discard(None)
    if len(сім_ї_великих) >= 2 and "колор_блок" not in активні:
        _дод("K-PAL-07", "hint", "колор-блок на низькому контрасті",
             "у великих слотах стоять %d кольорові сім'ї (%s) — це колор-блок, а він "
             "не в наборі прийомів для вашого контрасту під цим наміром"
             % (len(сім_ї_великих), ", ".join(sorted(сім_ї_великих))),
             "Imogen Lamport: колор-блок — виняток («unless heavy colour blocking»), "
             "не дефолт низького контрасту",
             "лишити одну кольорову сім'ю у великих слотах, решту віддати нейтралям",
             [t[0].get("id") for t in кольорові if t[1] in ВЕЛИКІ])

    # ── K-PAL-10: ПРИНТ ПРОТИ ПАЛІТРИ ───────────────────────────────────────
    # Корпус (тема-2:1856): «принт придатний, якщо його домінанта в палітрі і
    # внутрішній контраст ≈ контраст людини». Канал повернувся 16.09, коли річ
    # пулу дістала `колір`/`hex`: домінанту принту система тепер має — це той
    # самий представник кольору речі, яким її й судять скрізь. ДРУГОЇ ПОЛОВИНИ
    # ПРАВИЛА НЕМА І ЦЕ СКАЗАНО ВГОЛОС: внутрішній контраст принту фід не міряє,
    # тому знахідка говорить лише про домінанту й називає межу в `ламається`.
    for r, с, L, C, h, near in поза_палітрою:
        повна = (за_ід or {}).get(r.get("id")) or r
        віз = str(повна.get("візерунок") or "").strip().lower()
        if not віз or віз in ("solid", "однотонний"):
            continue
        _дод("K-PAL-10", "default", "домінанта принту поза палітрою",
             "«%s» має візерунок «%s», а домінанта його кольору поза вікнами вашої палітри"
             % (с or "річ", віз),
             "Lamport 2018: принт придатний, коли його домінанта — ваш колір",
             "принт, домінанта якого в палітрі, або однотонна річ у цьому слоті",
             [r.get("id")], слот=с,
             ламається="внутрішній контраст принту фід не міряє — судиться лише домінанта")

    # ── K-PAL-12: ДРАМАТИЗАЦІЯ М'ЯКОЇ ПАЛІТРИ ───────────────────────────────
    # «М'яку палітру робити драматичною контрастом світлоти, фактурою і блиском,
    # а не хромою» (Lamport 2019, hint). Прийом активний лише під statement при
    # chroma < 0 — і рівно тоді правило має що сказати: якщо образ пішов у гучний
    # колір замість світлоти, він драматизує не тим важелем.
    if "драматизація_м_якої" in активні and len(точки) >= 2:
        гучні = [t for t in кольорові if t[3] >= гучно]
        розмах = max(t[2] for t in точки) - min(t[2] for t in точки)
        if гучні and розмах < 30:
            _дод("K-PAL-12", "hint", "драматизація хромою, не світлотою",
                 "ваша палітра м'яка, а образ драматизується гучним кольором (хрома ≥ %.0f) "
                 "при розмаху світлоти лише %.0f L*" % (гучно, розмах),
                 "Lamport: м'яку палітру робить драматичною контраст світлоти, фактура і блиск, "
                 "а не хрома — гучний колір на м'якій людині читається як чужий, не як сміливий",
                 "розвести світлоти речей або взяти фактуру й блиск замість гучного кольору",
                 [t[0].get("id") for t in гучні])

    # ── K-PAL-13: СИВИНА — ОЧІ СТАЮТЬ ГОЛОВНИМ АКЦЕНТОМ ─────────────────────
    # Прийом активний лише на ахроматичному волоссі (`palettes.прийоми`), і доти
    # це рішення не мало наслідку взагалі: на живому вході батарея не має профілю
    # з сивиною, тож гілка не виконувалась, а якби й виконалась — нікуди не йшла.
    # Тут вона судить: коли волосся не несе температури, єдиний акцент, що лишився
    # від рис, — сім'я очей, і образ без неї біля обличчя втрачає останній перегук.
    if "сивина" in активні:
        очі_дуги = (П["вікна"].get("сім_ї") or {}).get("очі") or []
        біля = [t for t in кольорові if t[5] >= _КО.NEAR_МІН]
        має_очі = any(
            any(((float(a[0]) - _ЗАПАС_ДУГИ <= t[4] <= float(a[1]) + _ЗАПАС_ДУГИ)
                 if float(a[0]) <= float(a[1])
                 else (t[4] >= float(a[0]) - _ЗАПАС_ДУГИ or t[4] <= float(a[1]) + _ЗАПАС_ДУГИ))
                for a in очі_дуги)
            for t in біля)
        if очі_дуги and біля and not має_очі:
            _дод("K-PAL-13", "default", "сивина без акценту від очей",
                 "волосся не несе температури, тому головним акцентом лишаються очі — "
                 "а біля обличчя нема жодного кольору з їхньої сім'ї",
                 "Lamport 2026; Shop My Palette 2026: із сивиною контраст, глибина й хрома "
                 "м'якшають, сірий стає нейтраллю, а очі стають головним акцентом",
                 "колір із сім'ї очей біля обличчя — шарф, верх або сережки",
                 [t[0].get("id") for t in біля])
    return зн


# ── БЮДЖЕТ ХРОМИ Й ВІДЛУННЯ СУДЯТЬ ОБРАЗ І БЕЗ ВИМІРЯНИХ ПЛОЩ (K-COL-02, K-COL-05)
# ЩО ТУТ БУЛО ДО 17.09.2026, І ЧОМУ ЦЕ НЕ «ЩЕ ОДИН СУДДЯ». Емітенти обох правил є
# від початку і написані правильно — `колір_образу.бюджет_хроми` і
# `колір_образу.відлуння`. Але обидва стоять ЗА ГЕЙТОМ ПЛОЩІ в `суд_образу.review`
# (`площі_є = all(e["площа"] is not None and e.get("джерело_площі") …)`), а свідком
# виміру там навмисно є ПОХОДЖЕННЯ площі, не наявність числа. На живому вході
# `джерело_площі` не ставить ніхто: `composer._у_річ` кладе заглушку 1/N, а
# `outfit.площі_з_геометрії` рахує площу лише з довжин виробу, яких фід не дає.
# ВИМІРЯНО НА `каталог_повний.xml` (10 770 офферів, 17.09.2026): речей із
# походженням площі — 0, тобто гейт закритий на 100 % образів, і два правила з
# корпусною силою `strong`/`default` не сказали жодного слова жодного разу.
# ГЕЙТ ПЛОЩІ НЕ ЧІПАЄТЬСЯ, І ЦЕ НАВМИСНО: він захищає від вигаданої площі, і саме
# він поіменно ловив хибні вердикти (заглушка 1/6 додавала три знахідки й ковтала
# одну справжню). Змінено інше: ТА ЧАСТИНА ОБОХ ПРАВИЛ, ЯКІЙ ПЛОЩА НЕ ПОТРІБНА,
# судить зібраний образ тут — з кольору, який ВИМІРЯНО, і зі слота, який названо.
#   K-COL-02 — «≤1–2 високонасичених елементи на образ, РАХУЮЧИ волосся й оправу»:
#     це ЛІЧБА, і площа в ній потрібна лише щоб відсіяти ювелірний масштаб. Тут
#     його відсіює слот (набір `_ЮВЕЛІРНІ`), а не поріг площі.
#   K-COL-05 — «акцент або повторюється, або є свідомим фокусом»: лічба ЗОН, і
#     площа потрібна лише як міра «малості» сироти. Тут її замінює КЛАС СЛОТА
#     (великі слоти проти акцентних) — і ця заміна названа в `ламається`.
# ЧОГО ТУТ НЕМА: другої половини K-COL-02 («конфлікт хром: два гучні кольори
# СПІВМІРНОЇ ПЛОЩІ») і порогу `focus_area` у K-COL-05. Обидві стоять на порівнянні
# площ, а не на їх наявності, і вигадати їх зі слота не можна — вони лишаються в
# `колір_образу`, за гейтом площі, і оживуть разом із ним.
# ДУБЛЯ НЕ БУДЕ: коли площі колись зміряються, обидва емітенти дадуть по знахідці
# того самого правила, а `знахідки_вердикту` зливає їх у ОДИН рядок за `правило`,
# лишаючи найсильнішу — тобто ту, що стоїть на вимірі, а не на слоті.
_ВЕЛИКІ_СЛОТИ = ("верх", "низ", "сукня", "комплект", "верхній_шар")
# Ювелірний масштаб — слотом, бо площі нема. Той самий поділ, що вже стоїть у
# `колір_образу.SLOT_NEAR_FALLBACK` (сережки/каблучка/годинник) і в
# `МЕТАЛ_ЮВЕЛІРНА_ПЛОЩА`: метал у цих слотах бюджету хроми не витрачає.
_ЮВЕЛІРНІ = ("прикраси", "сережки", "намисто", "кольє", "каблучка", "браслет",
             "годинник", "брошка")
_СУСІДНІ_ТОНИ = 45.0        # той самий, що `колір_образу.відлуння.СУСІДНІ`


def бюджет_і_відлуння(речі, F=None, за_ід=None, фокус=None):
    """[знахідки] K-COL-02 (бюджет хроми) і K-COL-05 (відлуння) над ЗІБРАНИМ образом.

    Площі не потрібно: перше правило рахує ГУЧНІ елементи, друге — ЗОНИ. `F` —
    риси особи (`волосся*`, `оправа`): корпус K-COL-02 прямо каже «counting hair,
    counting eyewear frames», і без них бюджет рахувався б не за правилом.
    """
    import реєстр_правил as _РЕЄСТР, palettes as _ПЛ
    гучно = _РЕЄСТР.C["hi_C"]
    точки = _кольори_образу(речі, за_ід)
    if not точки:
        return []
    зн = []

    def _дод(правило, сила, ярлик, суть, чому, зняло_б, речі_, ремонт=None, **решта):
        зн.append(dict(правило=правило, сила=сила, сила_нп=_СИЛА_НП[сила], впевненість=1.0,
                       регістр=_РЕЄСТР.регістр(правило, сила), бік="код",
                       сила_нп_джерело="корпусна сила правила кольору (тема-4 §K-COL)",
                       речі=[x for x in речі_ if x], ярлик=ярлик, суть=суть, чому=чому,
                       ремонт=ремонт or зняло_б, що_зняло_б=зняло_б, **решта))

    # ── K-COL-02: БЮДЖЕТ ХРОМИ ────────────────────────────────────────────────
    # Метал у ювелірному слоті з бюджету виходить із тієї самої причини, що в
    # `колір_образу.бюджет_хроми`: золотий ланцюжок — не колірний блок. Там межу
    # тримає площа, тут — слот.
    гучні = [(r, с) for r, с, L, C, h, near in точки
             if C >= гучно and not (с in _ЮВЕЛІРНІ and _ПЛ.метал_речі(_lab_з(L, C, h), с))]
    бюджет = [("«%s»" % (r.get("назва") or r.get("id") or с)) for r, с in гучні]
    особа_гучна = []
    for k, f in (F or {}).items():
        if not isinstance(f, dict) or str(k).startswith("_"):
            continue
        if str(k).startswith("волосся") and (f.get("C") or 0) >= гучно:
            особа_гучна.append("волосся (C*%.0f)" % f["C"])
        if k == "оправа" and (f.get("C") or 0) >= гучно:
            особа_гучна.append("оправа (C*%.0f)" % f["C"])
    разом = len(гучні) + len(особа_гучна)
    if разом > 2:
        _дод("K-COL-02", "strong", "понад бюджет хроми",
             "високонасичених елементів %d при стелі 2: %s — решта образу не встигає бути тлом"
             % (разом, ", ".join(бюджет + особа_гучна)),
             "корпус рахує не кольори, а ГУЧНІ елементи, і волосся та оправа входять у "
             "бюджет нарівні з речами: вони теж приобличчевий акцент, тільки постійний",
             "лишити один гучний як фокус; решту взяти приглушеними версіями тієї самої "
             "сім'ї або нейтралями (K-COL-03: нейтралі + акцент)",
             [r.get("id") for r, _ in гучні], поріг=2, вимір=разом,
             ламається="без виміряних площ дрібний аксесуар важить у лічбі як велика річ — "
                       "поріг ювелірного масштабу тут тримає СЛОТ, а не частка образу")

    # ── K-COL-05: ВІДЛУННЯ ────────────────────────────────────────────────────
    # Групування за дугою 45°, а не за ім'ям сім'ї, — те саме рішення й з тієї
    # самої причини, що в `колір_образу.відлуння`: сусідні тони (200°, 230°, 255°)
    # читаються як ОДИН акцент, а тверді межі сімей рвали їх на «сироту» й «пару».
    кольорові = [(r, с, L, C, h) for r, с, L, C, h, near in точки
                 if not _нейтральний_тон(h, C, L) and not _ПЛ.метал_речі(_lab_з(L, C, h), с)]
    групи = []
    for t in sorted(кольорові, key=lambda t: -t[3]):
        for g in групи:
            d = abs(g[0][4] - t[4]); d = min(d, 360 - d)
            if d <= _СУСІДНІ_ТОНИ:
                g.append(t); break
        else:
            групи.append([t])
    for g in групи:
        зони = {t[1] for t in g}
        назва = _сім_я_кута(g[0][4]) or "тон ~%d°" % round(g[0][4])
        if len(зони) == 1:
            слот = next(iter(зони))
            if слот in _ВЕЛИКІ_СЛОТИ:
                continue            # велика поверхня — це не сирота-акцент, а сам образ
            свідомий = bool(фокус) and слот in фокус
            _дод("K-COL-05", "hint" if свідомий else "default",
                 "акцент-сирота" if not свідомий else "акцент у оголошеному фокусі",
                 "акцент «%s» стоїть в одному акцентному слоті («%s») і більше ніде — "
                 "око не знаходить наміру" % (назва, слот),
                 "гештальтний повтор: колір, який не відлунює у другій рознесеній зоні і "
                 "не оголошений фокусом, читається як шум, а не як хід",
                 ("фокусна зона оголошена («%s») — акцент легітимний як пуант" % слот
                  if свідомий else
                  "повторити цей колір у другій рознесеній зоні (взуття ↔ сумка ↔ шарф ↔ "
                  "прикраси) АБО оголосити цю зону фокусом АБО прибрати"),
                 [t[0].get("id") for t in g], слот=слот, вимір=len(зони), поріг=2,
                 ламається="без виміряних площ «малість» сироти міряє КЛАС СЛОТА, не частка "
                           "образу: гучна сумка й дрібна брошка тут важать однаково, а "
                           "великий слот із того самого кольору правило мовчки пропускає")
        elif len(зони) > _РЕЄСТР.C["echo_max"]:
            _дод("K-COL-05", "soft", "відлуння понад стелю",
                 "акцент «%s» повторено у %d зонах — повтор перестає читатись як намір і "
                 "стає уніформою" % (назва, len(зони)),
                 "стеля відлуння: 4+ носії одного кольору — це вже matchy, а не перегук",
                 "лишити 2–3 носії, решту перевести в нейтраль",
                 [t[0].get("id") for t in g], вимір=len(зони), поріг=_РЕЄСТР.C["echo_max"],
                 ламається="тональна колона одного кольору — інша схема (K-COL-03 §2), не "
                           "відлуння; схема образу сюди не доїжджає, тому стеля тут груба")
    return зн


def _lab_з(L, C, h):
    """(L, C, h) → Lab. Локальна дрібниця: `palettes.метал_речі` питає Lab, а тут
    колір уже розкладений на осі, і збирати його назад через `colorspace` двічі
    в одному циклі дорожче, ніж порахувати два косинуси."""
    import math as _м
    r = _м.radians(float(h))
    return (float(L), float(C) * _м.cos(r), float(C) * _м.sin(r))


def акцент_образу(речі, спец_слоти, кандидати=None, за_ід=None):
    """[знахідки] — де роль «акцент» призначена, але хроми в образі нема.

    `за_ід` — id → запис КАТАЛОГУ. Він тут обов'язковий: записи пулу, які їдуть
    до моделі, несуть лише назву, ціну й словесну зону, БЕЗ `lab`. Рахувати
    хрому по них означало б діставати None на кожній речі й через це завжди
    списувати провал на каталог — тобто зробити звинувачення сталим, а перевірку
    невідрізненною від заглушки. Спіймано першим же прогоном: «у пулі НЕМА
    жодної речі з хромою» стояло і там, де речі були.
    """
    if not спец_слоти:
        return []
    за_слотом = {}
    for r in речі:
        за_слотом.setdefault(r.get("слот"), r)
    зн = []
    # ключі на «_» — службові (напр. `_схема`), не слоти. Без цього фільтра
    # рядок схеми потрапляв у цикл як «слот» і валив перевірку AttributeError.
    акцентні = [(с, сп) for с, сп in спец_слоти.items()
                if not str(с).startswith("_") and isinstance(сп, dict)
                and сп.get("роль") == "акцент" and сп.get("C")]
    for с, сп in акцентні:
        r = за_слотом.get(с)
        if r is None:                      # слота в образі нема — це не «зник акцент»
            continue
        C = _хрома(r)
        if C is None:                      # колір речі не виміряний: мовчати чесніше,
            continue                       # ніж рахувати невимір за провал
        Cmin = float(сп["C"][0])
        if C >= Cmin:
            continue
        # чи взагалі БУЛО з чого взяти акцент у цьому слоті
        пул = ((кандидати or {}).get(с) or [])
        повні = [(за_ід or {}).get(x.get("id")) or x for x in пул]
        мали = [x for x in повні if (_хрома(x) or 0.0) >= Cmin]
        if мали:
            зн.append(dict(правило="K-PAL-18", сила="soft", бік="код",
                           слот=с, ярлик="акцент зник",
                           суть=("схема «%s» дала слоту «%s» роль акценту (хрома від %.0f), "
                                 "а річ у ньому має %.0f — у пулі було %d речей із хромою"
                                 % (спец_слоти.get("_схема", "?"), с, Cmin, C, len(мали))),
                           чому="вибір проти власної спеки: акцент був доступний і не взятий",
                           що_зняло_б="річ із хромою ≥ %.0f у слоті «%s»" % (Cmin, с)))
        else:
            зн.append(dict(правило="K-PAL-18", сила="hint", бік="дані",
                           слот=с, ярлик="акценту не було з чого взяти",
                           суть=("схема «%s» вимагає акценту в слоті «%s» (хрома від %.0f), "
                                 "але в пулі цього слота НЕМА жодної речі з такою хромою"
                                 % (спец_слоти.get("_схема", "?"), с, Cmin)),
                           чому="дефіцит каталогу, не вибір моделі: звинувачувати модель тут — "
                                "помилка атрибуції",
                           що_зняло_б="джерела з кольоровими речами в цьому слоті"))
    # ЗВЕДЕНОЇ ЗНАХІДКИ («жоден акцентний слот не несе хроми») ТУТ НЕМА НАВМИСНО.
    # Вона була написана й ВИДАЛЕНА того ж прогону: `слот=None` не чіпляється до
    # жодної речі, тому граф її відкидає, і назовні їхали дві знахідки з трьох.
    # Правило, яке виконується, лишає слід і не доходить до людини, — рівно той
    # третій ярус, який тут заборонено. Дві послотові знахідки кажуть усе те саме
    # й доїжджають.
    return зн


def _хрома(r):
    """C* речі або None. None — це «не виміряно», і воно не рахується за провал."""
    lab = r.get("lab")
    if not lab and r.get("hex"):
        try:
            import colorspace as _КС
            lab = _КС.hx(r["hex"])
        except Exception:
            lab = None
    if not lab or len(lab) < 3:
        return None
    return (float(lab[1]) ** 2 + float(lab[2]) ** 2) ** 0.5


def структура_образу(речі, слоти_пулу=None, сценарій=None):
    """Блокери означення образу: по одній речі на слот, і є сукня або верх+низ.

    Це не правило стилю — це те, чим образ є. Дві пари взуття в одному образі
    ніхто не носить; образ без верху й низу (і без сукні) — це не образ, а
    аксесуари. Верхній шар, взуття, сумка й прикраси можуть бути відсутні —
    їх відсутність не робить образ не-образом.

    `слоти_пулу`: id → множина слотів, у яких ця річ стояла в пулі. ДВОСЛОТОВІ
    речі (кардиган: каталожний слот «верхній_шар», а в пулі і «верх») мусять
    рахуватись тим слотом, у якому вони справді стоять в образі: без цього
    кардиган, узятий як верх, дав би хибний блокер «нема верх» (спіймано
    пробою 02.09). Правило: спершу кожна річ бере свій каталожний слот; коли
    обов'язковий слот лишається порожнім, його закриває річ, що мала його в
    пулі, — і тоді вона вже не рахується у своєму каталожному."""
    import collections as _c, composer as _КМ, graph as _ГР
    б = []
    обов = [s for s in _ГР.СЛОТИ if s not in _КМ.СЛОТИ_НЕОБОВЯЗКОВІ]
    # ключ — ПОЗИЦІЯ речі, не id: речі без id (тести, вигадані руками 3/4) не
    # мають злипатись в одну
    призн = [(r.get("слот") or "?") for r in речі]
    # ЦІЛА РІЧ НЕ ПЕРЕПРИЗНАЧАЄТЬСЯ В ПОЛОВИНУ (04.09.2026, спіймано наскрізним
    # прогоном): комплект має в пулі і «верх», і «низ» (слоти_альт), і цикл нижче
    # ставив його у порожній «верх» — після чого «низ» лишався порожнім, і суддя
    # блокував «нема низу» рівно той образ, у якому низ є. Сукня й комплект
    # закривають обидва обов'язкові слоти собою і в перепризначення не входять.
    ЦІЛІ = ("сукня", "комплект")
    if слоти_пулу:
        зайняті = set(призн)
        # (внутрішньої перевірки «річ у ЦІЛІ — пропустити» тут нема навмисно: зовнішня
        # умова вже не пускає в перепризначення жоден образ із цілою річчю, і мутант
        # показав, що внутрішня була мертвою — прибрано того ж дня)
        if not (set(призн) & set(ЦІЛІ)):
            for s in обов:
                if s in зайняті:
                    continue
                for i, r in enumerate(речі):
                    if s in (слоти_пулу.get(str(r.get("id"))) or ()) and призн[i] != s:
                        призн[i] = s; зайняті.add(s); break
    # ДРУГИЙ ШАР НА ТОРСІ (тема-11, 05.09.2026): жакет, кардиган, жилет, піджак, блейзер,
    # болеро, кімоно, накидка поверх верху — це шар, а не другий «верх». Виміряно на
    # чотирьох сценаріях: «у слоті «верх» 2 речі (Базовий жакет…)» блокував законні образи.
    _ШАР2 = re.compile(r"жакет|кардиган|жилет|піджак|блейзер|болеро|кімоно|накидк|пончо|тренч|бомбер", re.I)
    if призн.count("верх") > 1:
        _верхи = [i for i, p in enumerate(призн) if p == "верх"]
        _шари = [i for i in _верхи if _ШАР2.search(str(речі[i].get("тип") or "") + " " + str(речі[i].get("назва") or ""))]
        if _шари and len(_шари) < len(_верхи):
            for i in _шари[:1]:
                призн[i] = "шар2"; речі[i]["шар"] = 2
    лічба = _c.Counter(призн)
    # ЛІЧБА ВЕДЕ СІМ'Ю СЛОТІВ, А НЕ БУКВАЛЬНИЙ СЛОТ (рядок 47, 19.09.2026):
    # дві пари сережок у слотах «сережки» й «прикраси» — це та сама сім'я, і
    # рахуватись мають РАЗОМ. `є` (обов'язкові слоти нижче) лишається на
    # буквальному `лічба` — сім'я тут лише для ЦЬОГО блокера.
    _сім_призн = [_сім_я_слота(p, речі[i].get("назва") or речі[i].get("тип")) for i, p in enumerate(призн)]
    for сл, n in _c.Counter(_сім_призн).items():
        if n > 1:
            імена = [str(r.get("назва") or r.get("id"))[:40] for i, r in enumerate(речі) if _сім_призн[i] == сл]
            б.append("у сім'ї «%s» %d речі (%s) — образ носять по одній на слот: лиши одну" % (сл, n, "; ".join(імена)))
    є = set(лічба)
    # ОДНЕ ДЖЕРЕЛО ІСТИНИ: обов'язкові слоти — ті, яких композитор не вважає
    # необов'язковими (зараз верх і низ); сукня заміняє обидва. Те саме правило,
    # що стоїть на ПОДАЧІ кандидатів, тепер стоїть і на СУДЖЕННІ образу моделі —
    # доти воно жило лише в композиторі, і образ із самих аксесуарів проходив.
    бракує = [s for s in обов if s not in є]
    if бракує and not ({"сукня", "комплект"} & є):
        б.append("нема %s (і нема сукні, яка їх заміняє) — це аксесуари, а не образ"
                 % " і ".join("«%s»" % s for s in бракує))
    # ── ПОДВОЄНИЙ НИЗ (04.09.2026, рішення власника про комплекти) ───────────
    # Слот «сукня» закриває верх і низ разом — і для сукні, і для костюма/комплекту
    # (feed.набір_цілий). Сукня + спідниця або костюм + штани — два низи, і це
    # не образ, а помилка означення: те саме, що два взуття. Верх ПОВЕРХ сукні
    # (сорочка під сарафан) — законний шар, тому «сукня + верх» тут не блокується.
    if "сукня" in є and "низ" in є:
        б.append("«сукня» і «низ» разом — низ подвоєний: лиши сукню або лиши низ")
    if "комплект" in є and ("низ" in є or "верх" in є):
        б.append("«комплект» (верх і низ в одному SKU) і окремий %s разом — подвоєння: "
                 "лиши комплект або візьми половину, сказавши СВІДОМО"
                 % " та ".join(s for s in ("верх", "низ") if s in є))
    # ── ПОВНОТА ОБРАЗУ ЗА НАГОДОЮ (16.09.2026) ─────────────────────────────────
    # Доти образ без взуття і на три речі проходив структуру: «верхній шар, взуття,
    # сумка й прикраси можуть бути відсутні». Тестувальниця бачила «Взуття в образі
    # нема» в описі. Повнота — властивість образу, не смаку: без взуття й сумки образ
    # не готовий для жодної нагоди, крім спорту й дому; понад верх/низ (або сукню)
    # потрібна ще одна річ — шар, прикраса, пояс, шарф чи головний убір (бриф і
    # так це просив, але без наслідку).
    _сц = dict(сценарій or {})
    _наг = " ".join(str(_сц.get(k) or "") for k in ("нагода", "місце", "подія", "дрес_код")).lower()
    _спорт = any(w in _наг for w in ("спорт", "трен", "йога", "біг", "пляж", "вдома", "домаш", "дім"))
    if "взуття" not in є:
        б.append("нема взуття — без взуття образ не готовий: додай пару під нагоду")
    if not _спорт and "сумка" not in є:
        б.append("нема сумки — для цієї нагоди сумка обов'язкова")
    _ТРЕТЯ = {"верхній_шар", "шар2", "прикраси", "пояс", "шарф", "головний_убір", "сережки",
              "намисто", "кольє", "браслет", "брошка", "каблучка", "окуляри", "годинник", "рукавички"}
    if not _спорт and not (є & _ТРЕТЯ):
        б.append("потрібна ще одна річ понад верх, низ і взуття: верхній шар, прикраса, пояс, "
                 "шарф або головний убір")
    _мін = 4 if ({"сукня", "комплект"} & є) else 5
    if not _спорт and len(речі) < _мін:
        б.append("образ неповний: %d реч%s, а для нагоди потрібно щонайменше %d"
                 % (len(речі), ("і" if len(речі) in (2, 3, 4) else "ей"), _мін))
    return б


# ── K-COMP-01 БУВ РЕАЛІЗОВАНИЙ І НЕ ВИКЛИКАВСЯ ЖОДНОГО РАЗУ (08.09.2026) ─────
# ЩО ЦЕ МІНЯЄ (правило 3, before/after). `coordination.координація` — єдине
# правило системи, що стоїть на ВИМІРЯНОМУ емпіричному результаті (Gray та ін.
# 2014), і воно вимагає НАБОРУ: «оптимум — це позиція в наборі, а не абсолютна
# колірна відстань». 31.08 його підʼєднали до ранжування композитора — а того ж
# дня власний перебір композитора знесли. Відтоді єдиним викликачем лишився
# `composer._координація_з`, який працює тільки під прапорцем `вимір=N`, а його
# продукт не передає ніколи. Тобто:
#   before — на живому шляху K-COMP-01 не виносився НІ РАЗУ. Шапка composer.py
#            при цьому й далі описувала його як діючий ключ ранжування.
#   after  — набором стають ІНШІ образи, що модель запропонувала на цей самий
#            випадок. Це і є набір кандидатів у сенсі статті: людина обирає між
#            ними, і ранг усередині них — саме те, що Gray міряли.
# ЧОМУ НЕ ПУЛ КАТАЛОГУ. Пул — це речі, не образи; середня попарна близькість
# визначена лише над зібраним образом. Вигадати з пулу «набір образів» означало
# б повернути власний перебір коду, який знесено 31.08 навмисно.
# ЧОГО ЦЕ НЕ РОБИТЬ: не блокує (сила default/hint) і не додає жодної константи —
# поріг рангу й підлога розкиду вже є в `coordination`, і саме вони вирішують,
# чи правило взагалі має право говорити.
def близькість_образу(речі):
    """Середня попарна близькість образу (d_ok) — число, з якого K-COMP-01 будує
    ранг. None, коли кольоронесучих речей менше двох: тоді ранг не існує."""
    try:
        import outfit as _O, coordination as _КО
        import колір_образу as _КОЛІР, реєстр_правил as _РЕЄСТР, формальність as _ФОРМ   # Н-02-01, сесія 4
        return _КО.середня_близькість(_O.елементи(list(речі or [])))
    except Exception:
        return None


def перевірити_від_моделі(ід, F, каталог, тіло, сценарій=None, кандидати=None, текст_моделі=None,
                          драп=None, спец_слоти=None, частини=None, набір_близькостей=None,
                          розриви=None):
    """Образ, який зібрала модель (список id), крізь той самий гіперграф.
    Повертає блокери, ребра за напругою, вузол напруги, речі поза кандидатами й
    мовні порушення тексту моделі (language_gate). Речі, яких у каталозі нема,
    названі, не вигадані.

    `розриви` — оголошені ходи ЦЬОГО образу, уже розібрані (`образи_з_json`, поле
    `свідомо`). Порожній список означає «модель не оголосила нічого», а `None` —
    «розбору не було, візьми з тексту» (проза: `свідомі_розриви`). Різниця не
    косметична: на JSON-шляху текст відповіді несе ВСІ образи, і пошук рядків у
    ньому послаблював би знахідку сьомого образу поясненням третього (Т-04)."""
    import composer as _КМ, graph as _ГР
    сценарій = dict(сценарій or {})
    # ДРАП ДО ГІПЕРГРАФА. `суд_образу.метали` і `колір_образу.температура_нейтралі` беруть
    # аргумент `драп`, але жоден виклик його не слав — правила вгадували метал із
    # фото там, де є пряма відповідь людини (R-PC-04: елісітація первинна).
    if драп:
        сценарій.setdefault("драп", драп)
    розбір = None
    if not ід and текст_моделі:
        розбір = ід_з_тексту(текст_моделі, кандидати=кандидати, каталог=каталог)
        ід = list(розбір["ід"]) + list(розбір["невідомі"])
        if not частини and розбір.get("частини"):
            частини = розбір["частини"]      # половина комплекту з тексту — і на верхньому рівні
    за_ід = {c["id"]: c for c in каталог}
    нема = [i for i in ід if i not in за_ід]
    речі = [_КМ._у_річ(dict(за_ід[i]), за_ід[i]["слот"], тіло) for i in ід if i in за_ід]
    # ПОЛОВИНА КОМПЛЕКТУ НАЗВАНА ЯВНО (05.09.2026): «#12·03/низ» → річ судиться як низ,
    # структура не бачить подвоєння, картка й опис знають, що це частина комплекту.
    for r in речі:
        ч = (частини or {}).get(r.get("id"))
        if ч and r.get("слот") == "комплект":
            r["слот"] = ч; r["частина_комплекту"] = ч
    вих = dict(нема_в_каталозі=нема, поза_кандидатами=[], знахідки=[], граф=None, вузол=None,
               блокує=[], рядок_вузла=None, мова=None, розбір=розбір)
    if кандидати:
        дозволені = {r["id"] for пул in кандидати.values() for r in пул}
        вих["поза_кандидатами"] = [i for i in ід if i in за_ід and i not in дозволені]
    # ── ЧИ ЦЕ ВЗАГАЛІ ОБРАЗ (02.09.2026, прогін 20:02) ─────────────────────
    # Картка руки 1: два взуття, дві сумки, сережки, підвіска — і ЖОДНОГО
    # блокера. Граф судив колір, посадку й ошатність кожної речі, але ніхто
    # не питав, чи це образ: по одній речі на слот і сукня або верх+низ. Це
    # означення, не смак, тому воно тут, у коді, і блокує — ремонт і вибір
    # дістають його рядком БЛОКУЄ і мусять розв'язати.
    _слоти_пулу = {}
    for _сл, _пул in (кандидати or {}).items():
        for _r in _пул:
            _слоти_пулу.setdefault(str(_r.get("id")), set()).add(_сл)
    вих["структура"] = структура_образу(речі, _слоти_пулу, сценарій)
    # знахідки про зниклий акцент рахуються ДО раннього виходу «замало речей»:
    # образ із двох речей теж мусить показати обраний колір
    import palettes as _ПЛ_схем
    вих["акцент"] = (акцент_образу(речі, спец_слоти, кандидати, за_ід)
                     + схема_образу(речі, спец_слоти, за_ід)
                     # Прийоми практикової палітри над зібраним образом (K-PAL-07…10,
                     # 12, 13, 14, 15). Їдуть тим самим відром, що й K-PAL-03/18: воно
                     # рахується ДО раннього виходу «замало речей» і не входить у ключ
                     # ранжування — це вердикт, а не штраф за вибір комбінації.
                     + палітра_образу(речі, спец_слоти, за_ід)
                     # ОБІЦЯНКА СХЕМИ (K-COL-03) — чи образ виконує те, що жінці
                     # пообіцяли на екрані палітри. Тіло — у `palettes`, бо схеми,
                     # їхні сім'ї та обіцянки живуть там; тут лише виклик, тим
                     # самим відром, що K-PAL-03/18 (вердикт, не штраф за комбінацію).
                     + _ПЛ_схем.обіцянка_схеми(речі, спец_слоти, за_ід)
                     # K-COL-02 і K-COL-05 — та їхня половина, якій виміряна площа
                     # не потрібна (див. секцію `бюджет_і_відлуння`). Тим самим
                     # відром і з тієї самої причини: це ВЕРДИКТ над зібраним
                     # образом, а не штраф за вибір комбінації, тож у ключ
                     # ранжування композитора воно не входить.
                     + бюджет_і_відлуння(речі, F, за_ід, (сценарій or {}).get("фокус")))
    # ЗНАХІДКА БЕЗ `сила_нп` ГИНЕ У ВЕРДИКТІ (16.09.2026): `знахідки_вердикту` відкидає
    # нульові. K-PAL-18 народжувалась без ваги — тобто ніколи не доходила до моделі.
    for _z in вих["акцент"]:
        if _z.get("сила_нп") is None and _z.get("сила") in _СИЛА_НП:
            _z["сила_нп"] = _СИЛА_НП[_z["сила"]]
            _z.setdefault("впевненість", 1.0)
    if len(речі) < 2:
        # ОДНА РІЧ — НЕ ОБРАЗ І НЕ «ПРОЙДЕНО» (04.09.2026, вердикт 7: модель обрала
        # «ОБРАЗ: #43·21» — сам костюм; код відповів без `речі` і без `перевірено`,
        # міст дописав `перевірено=True`, показ вивів порожню картку з трьома
        # сирими рядками). Тепер це блокер і явне «не перевірено», а речі їдуть
        # назовні, щоб показ мав із чого будувати картку.
        вих["чому"] = ("замало речей: %d — образ потребує щонайменше двох речей, "
                       "код не має що судити" % len(речі))
        вих["перевірено"] = False
        вих["блокує"] = list(вих["структура"]) + [
            "образ з однієї речі — це не образ: додай щонайменше взуття (або верх/низ до комплекту)"]
        вих["речі"] = [dict(id=r["id"], слот=r["слот"], назва=r.get("назва"),
                            **({"частина_комплекту": r["частина_комплекту"]} if r.get("частина_комплекту") else {}))
                       for r in речі]
        return вих
    _жн = (сценарій or {}).get("_жорстке_ні"); _вт = (сценарій or {}).get("_вето")
    сценарій = {k: v for k, v in (сценарій or {}).items() if k not in ("_жорстке_ні", "_вето")}
    блокує, сума, зн, _повний = _КМ._оцінити(F, речі, тіло, _жн, _вт, **сценарій)
    # ── КЛЮЧ СОРТУВАННЯ І ТЕ, ЩО БАЧИТЬ ЛЮДИНА, — РІЗНІ СПИСКИ (07.09.2026) ────
    # ЩО ЦЕ МІНЯЄ В РІШЕННІ (before/after).
    #   before — `_оцінити` СВІДОМО не бере в `зн` ремонти, команди, питання й
    #            «без входу»: ремонт — це вихід, а не вада речі, а брак входу не є
    #            вадою РЕЧІ. Міркування правильне — але `зн` звідси йшло далі як
    #            ЄДИНЕ джерело того, що показати людині. Тобто функція сортування
    #            вирішувала, про що система має право сказати, і мовчки викидала
    #            цілий канал корпусу: `канал_3` (команди розкладки, K-CRA-11 /
    #            K-CHN-01) не доходив нікуди, а аксесуарні «входу нема» не ставали
    #            припущеннями (K-IO-03, `hard`).
    #   after  — повний вихід перевірки (він тут завжди був, і його викидали в `_`)
    #            дає два окремі виходи: третій канал і черга на вхід. Ключ
    #            сортування лишається тим самим, тобто ранжування не змінилось.
    import знахідка as _ЗН
    _усі_пари = _ЗН.без_повторів(_ЗН.усі(_повний))
    _у_ключі = {(z.get("правило"), str(z.get("суть"))[:120]) for z in зн}
    # ТРЕТІЙ КАНАЛ МАЄ ДВІ ФОРМИ, І ЦЕ НЕ НЕДОГЛЯД. `outer.команди_укладки` віддає
    # ЗНАХІДКИ (пояс тренча, піднятий комір — там є правило, сила й ремонт), а
    # `accessory.команди_розкладки` — ОПЦІЇ З КОМПРОМІСАМИ (річ, клас, допустимі
    # місця, наслідок кожного). Друге навмисно не знахідка: канонічний авторитет
    # домену відмовляється робити цей вибір правилом, тож система подає варіанти,
    # а не вердикт. Тому збирач знахідок їх і не бачить — його справа інша.
    _команди_зн = [dict(правило=z.get("правило"), суть=z.get("суть"),
                        чому=z.get("чому"), речі=z.get("речі"))
                   for ш, z in _усі_пари if "/команди" in ш]
    _опції = []
    for _г in (_повний.get("аксесуари"), _повний.get("верхній_шар")):
        if isinstance(_г, dict):
            _опції += list(_г.get("канал_3") or [])
    вих["канал_3"] = dict(команди=_команди_зн, опції=_опції)
    вих["черга_на_вхід"] = [z for ш, z in _усі_пари
                            if (z.get("регістр") == "питання" or z.get("сила") == "питання")
                            and (z.get("правило"), str(z.get("суть"))[:120]) not in _у_ключі]
    # ── УТРИМАНЕ РІШЕННЯ — ТРЕТІЙ СТАН, І ДОТИ ВІН ЗНИКАВ ЦІЛКОМ (17.09.2026) ──
    # ЩО ЦЕ МІНЯЄ В РІШЕННІ. Пʼять правил дерева народжують знахідку силою
    # «утримано» — K-CLR-05 (метал на оливковому підтоні), K-COL-01, K-COL-02,
    # K-COL-05 (площі не виміряні), K-BOD-05 (довжина ноги). Кожна з них написана
    # рівно для того, щоб УХВАЛЕНЕ РІШЕННЯ БУЛО ВИДНО: докстрінг K-CLR-05 каже це
    # дослівно — «стиліст не міг відрізнити „правило перевірено й утримано на
    # оливковому підтоні“ від „правило не спрацювало“». І далі по трубі вони
    # зникали: `знахідки_вердикту` відкидає їх через `_питання_або_нуль`
    # (`сила_нп` у них None за побудовою — виміру нема), а `черга_на_вхід` бере
    # лише регістр/силу «питання», тобто «утримано» не потрапляло НІКУДИ. Правило,
    # написане проти мовчання, мовчало саме.
    # ЧОМУ ОКРЕМЕ ВІДРО, А НЕ В ПИТАННЯ. Питання каже «доміряй ось це» — там є що
    # зробити. Утримання каже «перевірено, і саме тому нічого не стверджую» — там
    # робити нема чого, і змішати їх означало б поставити в чергу на вхід рішення,
    # яке вже ухвалене.
    # `_у_ключі` тут НЕ фільтрує, і це не недогляд: утримані рядки лежать саме В
    # `зн` (їх кладуть туди `стани` й `посадка`) — і гинуть уже НА ВИХОДІ з нього,
    # у `знахідки_вердикту`, бо `сила_нп` у них None за побудовою. Відкинути їх
    # тут за те, що вони в ключі, означало б відкинути рівно ті, заради яких
    # відро й заведене.
    вих["утримано"] = [z for ш, z in _усі_пари
                       if z.get("сила") == "утримано" or z.get("регістр") == "утримано"]
    # ── K-SIG-01: ГЕЙТ НАД ВЛАСНОЮ МОВОЮ КОДУ ВИХОДИВ У НІКУДИ (17.09.2026) ───
    # `перевірити_образ` рахує `мовний_гейт` — прогін заборонених формул по ПОЛЯХ
    # ВЛАСНИХ знахідок (суть, чому, ремонт). Докстрінг функції пояснює, навіщо:
    # «заборонена формула найімовірніше з'явиться не у вільному тексті ШІ, а в
    # РЕМОНТІ наших власних правил — саме там система радить, що робити з тілом».
    # Читав це поле рівно один споживач — прилад `run_outfit.py`. На шляху
    # `від_моделі`, тобто там, де знахідки справді їдуть жінці, воно не виходило
    # нікуди. K-SIG-01 («сигнал розкоші не встановлений; заборона симетрична»)
    # разом із рештою анти-правил модуля мовчав у порожнечу: «промовчало
    # правильно» й «ніколи не перевірялось» лишали однаковий слід.
    вих["мовний_гейт_коду"] = (_повний.get("мовний_гейт")
                               if isinstance(_повний, dict) else None)
    # Чеклісти надлишку й прісності (K-SYS-08/09) рахуються в `перевірити_образ` і
    # доти лишались усередині неї: єдиним споживачем був стенд. Тема-4 називає їх
    # обовʼязковими воротами видачі, тож вони мусять доїхати щонайменше до
    # промпту ремонту — там модель ще може щось із ними зробити.
    вих["чеклісти"] = _повний.get("чеклісти")
    вих["реєстри"] = _повний.get("реєстри")
    # ── K-COMP-07: ФОРМУЛА — СТАРТОВА ТОЧКА, А НЕ ВИРОК ──────────────────────
    # ЩО ЦЕ МІНЯЄ В РІШЕННІ. Правило в зведенні стояло «нема в коді», і це було
    # правдою: жоден модуль не читав його твердження. А твердження в нього рівно
    # одне й воно ПЕРЕВІРНЕ: «formulas seed generation; they never validate
    # output. A formula-shaped outfit still has to pass the blandness checklist»
    # (тема-4 Part IV). Обидва входи на цьому шляху вже є й лежать поруч:
    # `спец_слоти["_схема"]` — назва колірної формули, за якою складали пул
    # (`palette.ПРИЙОМИ`), а `чеклісти["прісність"]` — чекліст K-SYS-09.
    # ЩО САМЕ СТВЕРДЖУЄТЬСЯ: не «образ поганий» — це скаже носійка, — а рівно те,
    # що вимірюється: образ побудований за готовою формулою І при цьому провалює
    # N пунктів підлоги прісності, тобто формула спрацювала як заготовка й не
    # спрацювала як перевірка. Сила `hint` — стільки дає корпус.
    # ЧОМУ ЦЕ НЕ ДУБЛЬ ЧЕКЛІСТА. Чекліст називає ПУНКТИ; це правило називає
    # причину, з якої їх легко проґавити — «схема ж обрана правильна». Без нього
    # провалені пункти читаються як дрібниці на тлі правильної схеми.
    _схема = (спец_слоти or {}).get("_схема")
    _прс = [p for p in ((вих.get("чеклісти") or {}).get("прісність") or [])
            if isinstance(p, dict) and p.get("стан") == "провал"]
    if _схема and _прс:
        import реєстр_правил as _РЕЄСТР7
        зн = list(зн) + [dict(_РЕЄСТР7._зн(
            "K-COMP-07", "hint",
            "формула «%s» узята за готову, а образ провалює %d %s підлоги прісності"
            % (_схема, len(_прс), _множина(len(_прс), "пункт", "пункти", "пунктів")),
            [r["id"] for r in речі],
            "стандартні поєднання — це РОЗВ'ЯЗАНІ заготовки, з яких починають, а не "
            "вирок, яким закінчують: формула засіває генерацію й ніколи не перевіряє "
            "вихід. Провалені пункти: %s"
            % "; ".join(str(p.get("що") or p.get("пункт")) for p in _прс[:3]),
            ремонт=["пройтись по названих пунктах прісності окремо — правильна схема "
                    "жодного з них не закриває"],
            ламається="сила `hint` — стільки дає корпус, і не більше: «формульність» "
                      "тут міряється самим фактом обраної схеми, а не тим, наскільки "
                      "образ до неї притиснутий. Свідома робота ВСЕРЕДИНІ формули "
                      "(відхилення-джокер, яке корпус і називає) цим виміром від "
                      "механічного виконання не відрізняється",
            поріг=0.0, вимір=float(len(_прс)), повна=2.0),
            сила_нп=round(min(1.0, len(_прс) / 2.0) * 0.5, 2),
            сила_нп_джерело="вимір (власний: провалених пунктів прісності при обраній формулі)")]
    # ── КОМАНДИ Й РЕМОНТИ ВЕРХНЬОГО ШАРУ — ЦЕ ЗНАХІДКИ, І ЇМ ТРЕБА У ВЕРДИКТ ──
    # ЩО ЦЕ МІНЯЄ В РІШЕННІ (правило 3, before/after, виміряно 17.09.2026 на
    # каталог_повний.xml через `bridge.від_моделі`).
    #   before — `composer._оцінити` бере з гілки верхнього шару РІВНО два відра:
    #            `ворота` і `преференції` (його власний коментар пояснює, чому
    #            ремонт не входить у СУМУ ШТРАФІВ — і це міркування правильне й
    #            лишається). Але `зн` звідти йшло далі як ЄДИНЕ джерело вердикту,
    #            тож разом із ключем сортування воно вирішувало, про що система
    #            має право СКАЗАТИ. Наслідок поіменно: K-OUT-19 (вузол пояса
    #            тренча), K-OUT-13 (стійка заміщає шарф), K-OUT-34 (ціна стану
    #            «накинуто»), K-OUT-29 (піднятий комір) з `команди`, і K-OUT-11
    #            (розстебнути), K-OUT-26 (пояс поверх пуховика), K-OUT-32
    #            (накинути) з `ремонти` — сім правил теми-11 народжувались
    #            повноцінними знахідками (правило, сила, сила_нп, суть, речі,
    #            ремонт) і не доходили ні до моделі, ні до жінки.
    #   after  — вони дописуються до `зн` ТУТ, тобто ПІСЛЯ `_оцінити`: у ключ
    #            ранжування вони не входять (комбінація з доступним ремонтом і
    #            далі не карається за те, що в неї є вихід), а у вердикт входять.
    #            Той самий прийом, яким сюди їде `вих["акцент"]` двома рядками
    #            нижче.
    # ЧОМУ ЛИШЕ ВЕРХНІЙ ШАР. `accessory` віддає в третій канал ОПЦІЇ З
    # КОМПРОМІСАМИ (річ, клас, допустимі місця, наслідок), а не знахідки — це
    # названо в коментарі до `канал_3` нижче і є рішенням домену. `outer` віддає
    # саме знахідки, і форма це підтверджує: `знахідка.це_знахідка` бачить їх,
    # а опції — ні.
    # `канал_3` НЕ ЧІПАЄТЬСЯ: його читає ендпойнт `опис` (bridge._поля_укладки,
    # гейт §97), і забрати звідти команди означало б полагодити один шлях,
    # зламавши інший.
    _вш_гілка = _повний.get("верхній_шар")
    _вш_зн = []
    if isinstance(_вш_гілка, dict):
        _вже_зн = {(z.get("правило"), str(z.get("суть"))[:120]) for z in зн}
        for _відро in ("команди", "ремонти"):
            for _z in (_вш_гілка.get(_відро) or []):
                if not isinstance(_z, dict) or not _z.get("правило"):
                    continue
                _кз = (_z.get("правило"), str(_z.get("суть"))[:120])
                if _кз in _вже_зн:
                    continue
                _вже_зн.add(_кз)
                _вш_зн.append(_z)
        зн = list(зн) + _вш_зн
    # ── ТЕ САМЕ ДЛЯ АКСЕСУАРНОЇ ГІЛКИ, І МЕЖА ТУТ ІНША (17.09.2026) ───────────
    # Учорашній блок вище свідомо взяв ЛИШЕ верхній шар і записав чому: `accessory`
    # віддає у третій канал ОПЦІЇ З КОМПРОМІСАМИ, а не знахідки. Це лишається
    # правдою про `канал_3` і не чіпається. Але поруч із ним на аксесуарній гілці
    # лежать ДВА відра, які віддають саме знахідки — повні, з правилом, силою,
    # силою_нп, суттю, речами й ремонтом, — і `composer._оцінити` не бере їх з тієї
    # самої причини, з якої не брав команди верхнього шару: він читає з гілки рівно
    # `ворота` й `преференції`.
    #   `віднімання`      — K-ACC-13, прохід на віднімання (`accessory.віднімання`);
    #   `надточний_збіг`  — K-ACC-10, названа відмова від точного збігу.
    # Обидва ставить сюди `перевірити_образ` ОКРЕМИМИ ключами гілки, тобто вони
    # народжувались повноцінними й не доходили ні до моделі, ні до жінки.
    # Ключ ранжування не змінюється — дописуємо ПІСЛЯ `_оцінити`, як і вище.
    _акс_гілка = _повний.get("аксесуари")
    if isinstance(_акс_гілка, dict):
        _вже_акс = {(z.get("правило"), str(z.get("суть"))[:120]) for z in зн}
        for _відро in ("віднімання", "надточний_збіг"):
            for _z in (_акс_гілка.get(_відро) or []):
                if not isinstance(_z, dict) or not _z.get("правило"):
                    continue
                _ка = (_z.get("правило"), str(_z.get("суть"))[:120])
                if _ка in _вже_акс or _z.get("сила") == "питання":
                    continue
                _вже_акс.add(_ка)
                зн = list(зн) + [_z]
    # ── СІМ'Я РЕМЕСЛА ЇДЕ ТИМ САМИМ ШВОМ, ЩО Й КОМАНДИ ВЕРХНЬОГО ШАРУ ────────
    # ЩО ЦЕ МІНЯЄ В РІШЕННІ (17.09.2026). `composer._оцінити` бере з
    # `перевірити_образ` п'ять названих ключів композиції плюс ворота й
    # преференції двох гілок; відра `ремесло` в тому переліку нема й бути не
    # мусить — це ті самі міркування, що для ремонтів: K-CRA-01 («третьої речі
    # нема») — діагноз зібраного образу, а не вада РЕЧІ, і карати нею комбінацію
    # в ключі ранжування означало б двічі рахувати те, що вже рахує підлога
    # інтересу. А у ВЕРДИКТ воно входить: інакше шість правил сім'ї далі не
    # казали б жінці нічого. Тому дописується ТУТ, після `_оцінити`, тим самим
    # прийомом, яким сюди їдуть команди верхнього шару й `вих["акцент"]`.
    # ── ПІДСУМОК ДВОБІЧНОЇ МОДЕЛІ ЯКОСТІ — ТИМ САМИМ ШВОМ (K-SYS-08/09) ──────
    # `суд_образу.чеклісти` рахує стелю надлишку й підлогу прісності на КОЖНОМУ
    # образі й доти лишала по них рівно `trace.запис`. Підсумок — твердження про
    # образ ЯК ЦІЛЕ, якого не робить жодне правило окремого пункта, тож він їде у
    # вердикт. Сюди, а не в `_оцінити`: у ключ ранжування він не входить із тієї
    # самої причини, що ремесло — інакше та сама вада рахувалася б двічі, раз
    # своїм правилом і раз підсумком.
    _чек_зн = [z for z in ((_повний.get("чеклісти") or {}).get("знахідки") or [])
               if isinstance(z, dict) and z.get("правило")]
    if _чек_зн:
        _вже_ч = {(z.get("правило"), str(z.get("суть"))[:120]) for z in зн}
        зн = list(зн) + [z for z in _чек_зн
                         if (z.get("правило"), str(z.get("суть"))[:120]) not in _вже_ч]
    _ремесло = [z for z in (list(_повний.get("ремесло") or [])
                             + list(_повний.get("силует_образу") or []))
                if isinstance(z, dict) and z.get("правило")]
    if _ремесло:
        _вже_р = {(z.get("правило"), str(z.get("суть"))[:120]) for z in зн}
        зн = list(зн) + [z for z in _ремесло
                         if (z.get("правило"), str(z.get("суть"))[:120]) not in _вже_р]
    # ВИМКНЕНЕ РІШЕННЯМ ВЛАСНИКА 05.09.2026: правила розміру (припуск, прилягання,
    # тісність) — доки в каталозі нема мірок виробу; K-CRA-04 «прибери одну річ» — геть.
    # Тип фігури й силует лишаються.
    # K-COMP-01: ранг цього образу серед ІНШИХ, які модель дала на той самий випадок.
    # Без набору правило само себе утримує й каже це вголос — саме тому набір тут
    # необовʼязковий, а не вигаданий.
    if набір_близькостей:
        try:
            import outfit as _O2, coordination as _КО2
            import реєстр_правил as _РЕЄСТР   # Н-02-01, сесія 4
            зн = list(зн) + _РЕЄСТР.обмежити_вагу(
                _КО2.координація(_O2.елементи(речі),
                                 набір_кандидатів=[v for v in набір_близькостей if v is not None]))
        except Exception:
            pass
    зн = [z for z in зн if not _вимкнене(z)]
    # ДОПОВНЕННЯ СУДДІ ЗА НАЗВАМИ (05.09.2026, проби правил): базові правила читають поля
    # (виріз, візерунок, метал), яких у каталозі майже нема, — і мовчали на міні+декольте,
    # леопард+смужка, срібло при «теплих», рюкзак на весілля, паєтки вдень. Тут те саме
    # правило — з назви речі, силою hint/soft, з позначкою джерела.
    # ── ДЕДУП K-COL-10 — ЗА ПРАВИЛОМ, А НЕ ЗА НАБОРОМ РЕЧЕЙ (Н-V16-041) ──────
    # Ключ `(правило, речі)` на K-COL-10 не працював за побудовою: `колір_образу.принти`
    # судить лише ВИДИМІ речі (`видимі_id`, і образ проганяється у двох станах),
    # а `_доповнення_судді` — усі речі за назвою. Набори речей через це різні, і
    # ключі не збігались. Виміряно (леопард-верх + смужка-низ + клітинка-пальто):
    # у `/знахідки` лягали ТРИ K-COL-10 — «c1+c2» (у приміщенні), «c2+c3»
    # (надворі) і «c1+c2+c3» із назв, тобто одну проблему стиліст читав тричі.
    # Взято другий варіант наряду: для K-COL-10 у ключі лише ПРАВИЛО. Звужувати
    # `_доповнення_судді` до видимих речей — не варіант: воно й написане для
    # образів БЕЗ полів каталогу, і звуження зняло б знахідки там, де немає з чого
    # порахувати видимість. Решта правил доповнення ключ не міняють: у них по
    # одному виробнику, і набір речей у ключі там відрізняє два різні випадки.
    _ЗА_ПРАВИЛОМ = ("K-COL-10",)
    _ключ = lambda z: ((z.get("правило"),) if z.get("правило") in _ЗА_ПРАВИЛОМ
                       else (z.get("правило"), tuple(sorted(z.get("речі") or []))))
    _вже = {_ключ(z) for z in зн}
    for z in _доповнення_судді(речі, сценарій, драп):
        if _ключ(z) not in _вже:
            зн.append(z)
            _вже.add(_ключ(z))
    # НАМІР statement (тема-6/8): гучність — легітимна; конфлікт хром і кількість інтересу
    # важать удвічі менше, і це видно в суті
    if (сценарій or {}).get("intent") == "statement":
        for z in зн:
            if z.get("правило") in ("K-COL-02", "K-COMP-04", "K-INT-04", "K-COMP-03"):
                z["сила_нп"] = round(float(z.get("сила_нп") or 0) * 0.5, 2)
                z["суть"] = str(z.get("суть") or "") + " (намір statement: сила вдвічі менша)"
    # ВЕТО ЛЮДИНИ — АБСОЛЮТ (K-PC-08 у базі: «абсолютний фільтр», K-PER-05): знахідка стає блокером
    # `блокує` — ОДНОРІДНИЙ список ЗНАХІДОК-СЛОВНИКІВ із `composer._оцінити`; рядок нижче
    # (формування `вих["блокує"]`) кличе `.get` на кожному елементі. Дописаний сюди РЯДОК
    # клав у список чужий тип і валив увесь `перевірити_від_моделі` з AttributeError —
    # тобто найсильніше правило системи спрацьовувало рівно так, щоб знести суддю. Тому
    # сюди йде знахідка з підміненою `суть`, а не рядок: тип елемента не міняється, а
    # назовні контракт той самий (рядки з `суть`), бо перетворення робить рядок нижче.
    # Дедуплікація теж мусила переїхати: `б not in блокує` порівнювало рядок зі словниками
    # й НІКОЛИ не спрацьовувало б — той самий K-PC-08 лягав би двічі. Ключ — правило й речі.
    _мітка = lambda z: dict(z, суть="вето людини: %s" % str(z.get("суть") or "")[:80])
    _ключ = lambda z: (z.get("правило"), tuple(z.get("речі") or ()))
    # K-PC-08 УЖЕ лежить у `блокує`: `_оцінити` бере туди всі знахідки з `блокує=True`,
    # а вето несе саме його. Тому мітка ставиться НА МІСЦІ, а не другим записом — інакше
    # людина дістала б той самий блокер двічі, раз із префіксом і раз без.
    _позначені = set()
    _нов_блок = []
    for z in блокує:
        if isinstance(z, dict) and z.get("правило") == "K-PC-08":
            _позначені.add(_ключ(z)); _нов_блок.append(_мітка(z))
        else:
            _нов_блок.append(z)
    # …а якщо вето прийшло лише знахідкою (шлях, де `_оцінити` її не блокувало) — дописати.
    for z in зн:
        if z.get("правило") == "K-PC-08" and _ключ(z) not in _позначені:
            _позначені.add(_ключ(z)); _нов_блок.append(_мітка(z))
    блокує = _нов_блок
    # оголошені розриви моделі — ДО графа, щоб вузол напруги рахувався з ослабленими силами
    зн = list(зн) + list(вих.get("акцент") or [])
    зн, свідомі = _застосувати_свідомі(
        зн, (розриви if розриви is not None else свідомі_розриви(текст_моделі)), речі)
    вих["свідомі"] = свідомі
    г = _ГР.граф(зн, речі); в = _ГР.вузол_напруги(г)
    вих.update(знахідки=sorted(зн, key=lambda z: -(z.get("сила_нп") or 0.0)),
               граф=г, вузол=(в or {}).get("вузол"), рядок_вузла=_ГР.рядок_вузла(в, г),
               блокує=list(вих["структура"]) + [str(z.get("суть") or "")[:100] for z in блокує],
               сума_сил=сума,
               речі=[dict(id=r["id"], слот=r["слот"], назва=r.get("назва"),
                          **({"частина_комплекту": r["частина_комплекту"]} if r.get("частина_комплекту") else {}))
                     for r in речі])
    if текст_моделі:
        try:
            import language_gate as _МГ, реєстр_правил as _РЕЄСТР_МОВИ
            # РЕЖИМ НАЗВАНИЙ ЯВНО (Т-07 крок 1). Дефолт у `перевірити` той самий, але
            # читач цього рядка мусить бачити, що вирок тут БЛОКУЄ: на кроці опису
            # `можна_видавати=False` тягне повторний виклик (`мова_повтор`), а після
            # останньої спроби — рішення власника Р-2 (`мова_рішення`). Дефолт
            # у сигнатурі гейта не міняти: його самоперевірка кличе функцію без
            # аргументу й стверджує `можна_видавати` — зміна зробила б ті
            # твердження тривіально істинними.
            вих["мова"] = _МГ.перевірити(текст_моделі, режим="блокувати")
            # ── ФОЛЬКЛОРНА КОНСТАНТА ДОЇЖДЖАЄ ДО ВЕРДИКТУ (K-COL-07, 17.09.2026) ──
            # ЩО ТУТ БУЛО. Гейт ловить «60-30-10» відколи його дописали 08.09 — і
            # спрацювання лягало в `мова["фольклорні_числа"]`, звідки його не читає
            # НІХТО: `_мова_вердикту` бере лише `порушення`, `_мова_порушення` (вхід
            # `мова_повтор` і `мова_рішення`) — теж лише `порушення`. Тобто код рахував
            # і мовчав: рівно «лише слід», яким зведення аудиту й позначило K-COL-07.
            # ЩО ЦЕ МІНЯЄ В РІШЕННІ (before/after, справжній рядок прогону):
            #   before — модель пише «Правило 60-30-10 дасть вам збалансований образ»;
            #            `можна_видавати=True`, у вердикті жодного рядка, і жінка читає
            #            фольклорну пропорцію як вимір;
            #   after  — у вердикті зʼявляється «у тексті стоїть фольклорна константа
            #            «поділ площ 60-30-10 (K-COL-07)» — «60-30-10»: число звучить як
            #            вимір, якого нема» [hint 0.20, репліка].
            # ЧОМУ НЕ БЛОК І ЧОМУ `hint`. Корпус (тема-4:308) прямо: «FORCE: `hint`,
            # [folkloric constant] … a default proportion, NEVER a threshold», а сам
            # список у гейті підписаний «не заборонені в тексті, але заборонені ЯК
            # ПОРОГИ». Тому `можна_видавати` не чіпається й перепису це не тягне:
            # зауваження, не вето. Сила береться з корпусу правила константи, коли
            # воно hint-ове, і з `_СИЛА_НП` — для решти списку.
            # ЧОМУ ТУТ, А НЕ В `language_gate`: гейт — чистий судець ТЕКСТУ й не знає
            # ні речей, ні форми знахідки; знахідки в цьому файлі складає одна рука.
            for _к in ((вих["мова"] or {}).get("фольклорні_числа") or []):
                _п = _к.get("правило")
                if not _п:
                    continue          # константа без ід корпусу лишається позначкою
                вих["знахідки"].append(dict(
                    правило=_п, сила="hint", сила_нп=_СИЛА_НП["hint"], впевненість=1.0,
                    регістр=_РЕЄСТР_МОВИ.регістр(_п, "hint"), бік="код", речі=[],
                    сила_нп_джерело="корпусна сила фольклорної константи: пропорція за "
                                    "замовчуванням, ніколи не поріг",
                    ярлик="фольклорна константа в тексті",
                    суть="у тексті стоїть фольклорна константа «%s» — «%s»: число звучить "
                         "як вимір, якого нема" % (_к.get("константа"),
                                                   "», «".join(_к.get("збіги") or [])[:80]),
                    чому=_к.get("чому"),
                    ремонт="сказати те саме без числа: «більша частина — тло, менша — "
                           "акцент» замість пропорції, яку ніхто не міряв",
                    що_зняло_б="той самий зміст без числа",
                    ламається="гейт ловить ФОРМУЛЮВАННЯ, не НАМІР: перефразування "
                              "обходить його тривіально"))
        except Exception as _e:
            вих["мова"] = dict(помилка=str(_e))
    return вих


import re  # тут, а не лише нижче в файлі (5160): компільовані вирази читаються при


# ── КРОКИ 3 І 4 ЗНЕСЕНО РАЗОМ ЗІ СВОЇМИ ЕНДПОЙНТАМИ (Н-02-03, 13.09.2026) ────
# Тут стояли `пакет_пояснення`, `пояснення_від_моделі` (крок 3: код дає факти
# графа → модель пише → код перевіряє) і `запит_приміряння` (крок 4: промпт
# приміряння з фото каталогу). Єдиним викликачем усіх трьох був `bridge`
# (`пояснення`, `приміряння`) — ендпойнти, яких показ не кликав ніколи; вони
# знесені тією самою правкою. Крок 5 (`вердикт_у_ребра`) лишається: його кличе
# `bridge.вердикт`, а того — `показ.html:1618,1643` (Н-P12).
# ЩО ЦЕ ЗАБИРАЄ Й ЧОГО НЕ ЗАБИРАЄ: разом з кроком 4 пішов єдиний читач правила
# «перше НЕ-СМІТТЄВЕ фото» (свотчі 50×50). Сам відбір фото цим не змінено — його
# робить `підфід` на своєму боці й далі; змінилось те, що обіцянки «крок 4 це
# прочитає» більше нема, поки крок 4 не напишуть під реального читача.

# ── КРОК 5. ВЕРДИКТ: «носитиму / ні» повертається на ребра графа ──────────────
def вердикт_у_ребра(вердикт, в, коментар=""):
    """Записи для калібрування: на кожне правило образу — його напруга й вердикт."""
    г = в.get("граф") or {}
    з = str(вердикт).strip().lower()
    # ── СЛОВА ПОКАЗУ СТОЯТЬ ТУТ, А НЕ В JS (Н-P12) ───────────────────────────
    # Крок 5 не кликався нізвідки, і розходження словників було невидиме: картка
    # питає «Вдягнеш?» і дає рівно три відповіді — «вдягну як є», «вдягну, якщо
    # змінити одну річ», «не вдягну». Жодна не збігалась із набором нижче, тож
    # КОЖЕН вердикт показу прочитався б як «не носитиму», і калібрування виміряло
    # б власний переклад замість людини. Перекладати в JS не можна з тієї ж
    # причини, з якої формат промпта будує код: два словники розійшлися б на
    # першій правці картки.
    # «ЯКЩО ЗМІНИТИ ОДНУ РІЧ» — НЕ НОСИТИМУ, І ЦЕ НЕ ДРІБНИЦЯ: ребра рахуються
    # проти ЦЬОГО складу образу, а та відповідь каже, що цього складу жінка не
    # вдягне. Третій стан (умовна згода) тут не зникає — він лишається в рядку
    # журналу полем `вердикт_людини`; у калібрування він іде як «ні».
    носитиму = з in ("так", "носитиму", "yes", "1", "true", "вдягну як є")
    ребра = г.get("ребра") if isinstance(г, dict) else None
    if not ребра:
        ребра = [dict(правило=z.get("правило"), напруга=float(z.get("сила_нп") or 0.0))
                 for z in (в.get("знахідки") or []) if z.get("правило")]
    образ = "+".join(str(r.get("id")) for r in (в.get("речі") or в.get("образ") or []))
    return [dict(образ=образ, правило=р["правило"], напруга=round(float(р.get("напруга") or 0.0), 3),
                 носитиму=носитиму, коментар=коментар) for р in ребра]


def калібрування(записи, мінімум=8):
    """Per правило: частка «ні» при присутності ребра проти частки «ні» без нього.
    Це і є «сила ≤ верифікація» в дії: правило з ≥ `мінімум` вердиктів дістає
    вимірний тір (T1), решта — «не калібровано». Різниця часток — розрізнювальна
    сила за вердиктами, НЕ нова константа: вона перераховується з кожним вердиктом."""
    import collections as _c
    за_образом = _c.defaultdict(list)
    for з in записи: за_образом[з.get("образ") or id(з)].append(з)
    усі_образи = list(за_образом.values())
    n_ні_усього = sum(1 for о in усі_образи if о and not о[0]["носитиму"])
    вих = {}
    правила = {з["правило"] for з in записи}
    for р in sorted(правила):
        з_ним = [о for о in усі_образи if any(з["правило"] == р for з in о)]
        без = [о for о in усі_образи if not any(з["правило"] == р for з in о)]
        ні_з = sum(1 for о in з_ним if not о[0]["носитиму"]); ні_без = sum(1 for о in без if not о[0]["носитиму"])
        n = len(з_ним)
        вих[р] = dict(образів_з=n, образів_без=len(без),
                      частка_ні_з=round(ні_з / n, 2) if n else None,
                      частка_ні_без=round(ні_без / len(без), 2) if без else None,
                      різниця=(round(ні_з / n - (ні_без / len(без) if без else 0), 2) if n else None),
                      тір=("T1 (вердикти носіння)" if n >= мінімум else "не калібровано: %d із %d вердиктів" % (n, мінімум)))
    return вих



# ═══════════════════════ 05.09.2026: обмін, відсічення, паспорт ═══════════════════════
import json as _json_
import re

# `_json_у_рядки` СТОЯЛА ТУТ І ЗНЕСЕНА (Т-04). Вона перекладала обʼєкт моделі НАЗАД
# у рядки ПІДПИС/ОБРАЗ/СВІДОМО/ЧОМУ/ПОТРІБНО, щоб його розібрали регулярки прози.
# Ціна перекладу: `свідомо` ставало `str(dict)` і втрачало адресата (V33), `потрібно`
# їхало в пошук разом з іменами полів, а поле, назване інакше, зникало без слова.
# Тепер обʼєкт читають полями (`образи_з_json`, `запити_речей_з_тексту`), а розбір
# прози лишається окремим шляхом для рук без каталогу. Одна точка РОЗБОРУ тексту —
# `протокол.розібрати_json`.


def запити_речей_з_тексту(текст):
    """Прохання моделі про річ ПОЗА пулом, словами: поле `потрібно` ОБРАЗИ_V1
    (`[{слот, опис}]` або рядок), а в прозовій відповіді — рядки «ПОТРІБНО: …».
    Це право ші, про яке домовлялися: код шукає по всьому каталогу
    (`bridge.від_моделі` → `шукати_словами`).

    Поле читається ПРЯМО (Т-04): доти обʼєкт ішов крізь `_json_у_рядки`, де
    `{"слот": "шарф", "опис": "червоний шарф"}` ставав рядком `str(dict)` — і в
    пошук їхав разом із дужками й іменами полів."""
    об = _ПР.розібрати_json(текст)
    if isinstance(об, dict) and (_це_образи(об) or "потрібно" in об):
        вих = []
        for п in (об.get("потрібно") or []):
            опис = (п.get("опис") or п.get("слот")) if isinstance(п, dict) else п
            if str(опис or "").strip():
                вих.append(str(опис).strip())
        return вих[:5]
    return [м.group(1).strip() for м in
            re.finditer(r"^\s*ПОТРІБНО\s*[:：]\s*(.+)$", str(текст or ""), re.M)][:5]


# ВИМКНЕННЯ — ІМЕННЕ, І НЕ ТУТ (Н-P22). Реєстр із причиною на кожному ID лежить у
# `status.ВИМКНЕНІ_ПРАВИЛА`: вимкнути правило — рішення власника, а не механізм судді.
# Поруч стояв текстовий регекс `припуск|приляганн|тісн|ковзанн`, який різав знахідку
# за СЛОВОМ у `суть`/`чому`. Вимір на живому шляху (6 прогонів `тест_живого_шляху.py`,
# 64 знахідки крізь фільтр) показав, що він не спіймав жодного K-CRA-04 — той ловиться
# за ID — зате вбив K-BOD-02 ×12, правило силуету, якого власник не вимикав. Слово не
# знає, чиє воно, тому регекса нема. Як вимкнути ТЕМУ, а не правило, — див. коментар
# над реєстром у `status.py`.
ВИМКНЕНІ_ПРАВИЛА = frozenset(status.ВИМКНЕНІ_ПРАВИЛА)

def _вимкнене(z):
    """Чи знахідка знята рішенням власника. Читає ЛИШЕ `правило`: знахідка без ID
    не може бути вимкнена, бо вимкнено іменно, а не за текстом."""
    return (z.get("правило") or "") in ВИМКНЕНІ_ПРАВИЛА


# ТУТ СТОЯВ ДРУГИЙ `def _формат_відповіді` — перевизначення першого через аліас
# `_формат_відповіді_старий` (05.09.2026). Обидва знесено Т-02 разом з аліасом:
# схему відповіді оголошує `протокол.ОБРАЗИ_V1`, а пакет називає її іменем у
# `завдання.відповідь`. Перевизначення функції посеред файлу лишається тут
# застереженням: `grep "def _формат_відповіді"` давав ДВА збіги, і який із них
# працює, читалось лише з порядку рядків.



def _доповнення_судді(речі, сценарій=None, драп=None):
    """Правила бази, які базовий суддя не бачить без полів каталогу — за назвою речі.
    K-KOH-10 одна відкрита зона; K-COL-10 змішування принтів; K-CRA-07 один метал;
    K-KOH-06 блиск удень; K-KOH-08 сумка нижче рівня події."""
    сц = сценарій or {}; вих = []
    година = сц.get("година"); вечір = (година is not None and int(година) >= 17)
    _о = сц.get("_ошатність"); lo = None
    if isinstance(_о, (list, tuple)) and len(_о) == 2:
        try: lo = min(float(_о[0]), float(_о[1]))
        except (TypeError, ValueError): lo = None
    def _з(правило, сила, сила_нп, суть, ids):
        return dict(правило=правило, сила=сила, сила_нп=сила_нп, суть=суть + " [з назви речі]", речі=ids,
                    сила_нп_джерело="назва речі (полів каталогу нема)")
    назви = [(r.get("id"), str(r.get("назва") or ""), r.get("слот") or "") for r in речі]
    # 1) K-KOH-10: відкриті зони — декольте/спина, ноги, плечі — по одній зоні на річ
    зони = {}
    for id_, n, сл in назви:
        if сл in ("верх", "сукня", "комплект", "низ"):
            if re.search(r"декольте|корсет|бюстьє|бандо|глибок\w* виріз|відкрит\w* спин|з відкритою спиною", n, re.I): зони.setdefault("декольте/спина", []).append(id_)
            if сл != "верх" and re.search(r"\bміні\b|шорт|коротк\w* спідниц|ультракоротк", n, re.I): зони.setdefault("ноги", []).append(id_)
            if re.search(r"без рукав|на тонких бретел|на бретел|майка|топ-бандо|відкрит\w* плеч", n, re.I): зони.setdefault("плечі", []).append(id_)
    ліміт = 2 if вечір else 1
    if len(зони) > ліміт:
        вих.append(_з("K-KOH-10", "soft", round(min(1.0, (len(зони) - ліміт) / 2.0 + 0.3), 2),
                      "відкритих зон %d (%s) при межі %d для %s" % (len(зони), ", ".join(зони), ліміт, "вечора" if вечір else "дня"),
                      sorted({i for v in зони.values() for i in v})))
    # 2) K-COL-10: два різні принти
    # ЩО ЦЕ МІНЯЄ (правило 3, before/after, 08.09.2026)
    #   before: · два різні принти в одному образі: анімалістичний, смужка [з назви речі] [0.50]
    #   after:  · різні принти: анімалістичний (верх) + смужка (низ) — зв'язати спільним
    #             кольором або дати одному домінувати площею [з назви речі] [0.50]
    # Старий рядок називав ІМЕНА принтів і не називав ні речі, ні ходу: ші діставала
    # «їх два» без адреси, до якої прикласти руки. Ід у полі `речі` цього не рятують —
    # `промпт_ремонту` друкує лише `суть` і `сила_нп`, а `ремонт` тут не заповнюється
    # взагалі. Слот кожного принта вже лежить у `назви` третім полем, тож речення тепер
    # каже, В ЯКИХ СЛОТАХ принти зіткнулись і що з ними зробити.
    # ХІД НЕ ВИГАДАНО, А ВЗЯТО В САМОГО ПРАВИЛА (ревізія 08.09.2026). Перша редакція
    # хвоста казала «звести до одного принта, решту речей однотонними» — це ЧУЖА, суворіша
    # норма, якої корпус не тримає. Своє ж K-COL-10 (`колір_образу.принти`) має рівно два виходи
    # у полі `ремонт`: «замінити один принт на версію, що містить колір другого, АБО
    # зв'язати третьою річчю у спільному кольорі», а `ламається` додає третій — «чітке
    # домінування одного принту за площею рятує навіть без нитки» (те саме в
    # звірка_механізмів.md: нитка + різні масштаби + домінування). Мікс принтів корпус НЕ
    # забороняє, тож і речення його не забороняє: воно називає ті самі два виходи.
    ПРИНТИ = [("анімалістичний", r"леопард|зебр|анімал|пітон|змії"), ("смужка", r"смуж|смугаст|stripe"), ("клітинка", r"клітин|карт\w*|тартан|гусяч"), ("квіти", r"квіт|флор"), ("горох", r"горох|горошок|polka")]
    знайдені = {}; слоти_принта = {}
    for id_, n, сл in назви:
        for ім, рег in ПРИНТИ:
            if re.search(рег, n, re.I):
                знайдені.setdefault(ім, []).append(id_)
                слоти_принта.setdefault(ім, []).append(сл or "без слота")
    if len(знайдені) >= 2:
        _де = " + ".join("%s (%s)" % (ім, "/".join(dict.fromkeys(слоти_принта[ім]))) for ім in знайдені)
        вих.append(_з("K-COL-10", "soft", 0.5, "різні принти: %s — зв'язати спільним кольором або дати одному домінувати площею" % _де, sorted({i for v in знайдені.values() for i in v})))
    # 3) K-CRA-07: метал прикрас проти слова людини
    м = str((драп or {}).get("метал") or "").lower()
    теплий = м in ("теплі", "теплий", "золото")
    холодний = м in ("холодні", "холодний", "срібло")
    for id_, n, сл in назви:
        if сл in ("сережки", "намисто", "кольє", "браслет", "каблучка", "брошка", "прикраси", "пояс", "сумка"):
            if теплий and re.search(r"сріб|silver|родій|платин|сталь", n, re.I):
                вих.append(_з("K-CRA-07", "soft", 0.5, "срібний метал при теплій драпіровці (її слово — золото)", [id_]))
            if холодний and re.search(r"золот|gold|позолот|латун", n, re.I):
                вих.append(_з("K-CRA-07", "soft", 0.5, "золотий метал при холодній драпіровці (її слово — срібло)", [id_]))
    # 4) K-KOH-06: блиск удень
    # ЩО ЦЕ МІНЯЄ (правило 3, before/after, 08.09.2026)
    #   before: · блиск (паєтки/люрекс/стрази) о 13:00 — денний контекст [з назви речі] [0.45]
    #   after:  · блиск (паєтки/люрекс/стрази) у слоті «верх» о 13:00 — денний контекст:
    #             взяти матову річ у цей слот [з назви речі] [0.45]
    # Старий рядок виходив однаковий на паєтковий топ і на люрексову сукню: він називав
    # ГОДИНУ, а не річ, і не мав ходу — «денний контекст» не каже, що з блиском робити,
    # а ід речі в промпт ремонту не друкується. Слот блискучої речі розпакований тут же
    # (`сл` у цьому ж циклі), напрям однобічний — день просить матового; обидва в реченні.
    if година is not None and int(година) < 17:
        for id_, n, сл in назви:
            if re.search(r"паєтк|люрекс|металік|блискіт|стрази|ламе\b", n, re.I):
                вих.append(_з("K-KOH-06", "soft", 0.45, "блиск (паєтки/люрекс/стрази) у слоті «%s» о %02d:00 — денний контекст: взяти матову річ у цей слот" % (сл or "без слота", int(година)), [id_])); break
    # 5) K-KOH-08: сумка нижче рівня події
    if lo is not None and lo >= 6:
        for id_, n, сл in назви:
            if сл == "сумка" and re.search(r"рюкзак|шопер|пляжн|поясн|спортивн|бананк", n, re.I):
                вих.append(_з("K-KOH-08", "soft", 0.6, "тип сумки (рюкзак/шопер/поясна) нижчий за рівень події %d" % int(lo), [id_])); break
    return вих
